/* Project headers contain inline ELF validators shared with the packer.  In
 * this translation unit they must use the loader-owned primitives too: an
 * inline helper can remain reachable after the target thread-pointer handoff.
 * Declare and redirect before parsing those headers. */
static void *ldr_memcpy(void *, const void *, size_t);
static void *ldr_memset(void *, int, size_t);
static int ldr_memcmp(const void *, const void *, size_t);
static void *ldr_memchr(const void *, int, size_t);
static size_t ldr_strlen(const char *);
static int ldr_strcmp(const char *, const char *);
static int ldr_strncmp(const char *, const char *, size_t);
static char *ldr_strchr(const char *, int);
static char *ldr_strrchr(const char *, int);

#undef memcpy
#undef memset
#undef memcmp
#undef memchr
#undef strlen
#undef strcmp
#undef strncmp
#undef strchr
#undef strrchr
#define memcpy  ldr_memcpy
#define memset  ldr_memset
#define memcmp  ldr_memcmp
#define memchr  ldr_memchr
#define strlen  ldr_strlen
#define strcmp  ldr_strcmp
#define strncmp ldr_strncmp
#define strchr  ldr_strchr
#define strrchr ldr_strrchr

