enum glibc_private_flow {
    GLIBC_PRIVATE_FLOW_NORMAL = 1,
    GLIBC_PRIVATE_FLOW_CONDITIONAL,
    GLIBC_PRIVATE_FLOW_BRANCH,
    GLIBC_PRIVATE_FLOW_TERMINAL
};

/* A deliberately small instruction contract shared by the private-rtld
 * provenance walkers.  Decoders report only direct control-flow edges and
 * definite GPR writes.  Unknown instructions and indirect jumps terminate
 * that path; they are never assumed harmless. */
struct glibc_private_instruction {
    size_t end;
    size_t target;
    enum glibc_private_flow flow;
    uint32_t writes;
};

typedef int (*glibc_private_decode_fn)(
    const uint8_t *, size_t, size_t, struct glibc_private_instruction *);
typedef int (*glibc_private_field_fn)(
    const uint8_t *, size_t, size_t, unsigned int,
    size_t *, size_t *);

#define GLIBC_PRIVATE_CFG_LIMIT 8192U
#define GLIBC_PRIVATE_PAIR_LIMIT 512U

static int glibc_private_enqueue_successors(
    const struct glibc_private_instruction *instruction, size_t length,
    uint16_t *queue, size_t capacity, size_t *tail)
{
    size_t successors[2];
    size_t count = 0;

    if (instruction->flow == GLIBC_PRIVATE_FLOW_NORMAL ||
        instruction->flow == GLIBC_PRIVATE_FLOW_CONDITIONAL)
        successors[count++] = instruction->end;
    if (instruction->flow == GLIBC_PRIVATE_FLOW_BRANCH ||
        instruction->flow == GLIBC_PRIVATE_FLOW_CONDITIONAL)
        successors[count++] = instruction->target;
    for (size_t i = 0; i < count; i++) {
        if (successors[i] >= length)
            continue;
        if (*tail >= capacity || successors[i] > UINT16_MAX)
            return 0;
        queue[(*tail)++] = (uint16_t)successors[i];
    }
    return 1;
}

/* Prove that an offset is a real instruction boundary reachable from the
 * function entry.  Merely finding bytes which decode as a GOT load is not
 * enough: immediates, branch-skipped padding, and dead tails are excluded. */
static int glibc_private_offset_reachable(
    const uint8_t *code, size_t length, size_t target,
    glibc_private_decode_fn decode)
{
    unsigned char seen[GLIBC_PRIVATE_CFG_LIMIT];
    uint16_t queue[2 * GLIBC_PRIVATE_CFG_LIMIT + 1];
    size_t head = 0;
    size_t tail = 0;

    if (!code || !decode || length == 0 ||
        length > GLIBC_PRIVATE_CFG_LIMIT || target >= length)
        return 0;
    ldr_memset(seen, 0, length);
    queue[tail++] = 0;
    while (head < tail) {
        struct glibc_private_instruction instruction;
        size_t position = queue[head++];

        if (seen[position])
            continue;
        seen[position] = 1;
        if (position == target)
            return 1;
        if (!decode(code, length, position, &instruction) ||
            instruction.end <= position || instruction.end > length)
            continue;
        if (!glibc_private_enqueue_successors(
                &instruction, length, queue,
                sizeof(queue) / sizeof(queue[0]), &tail))
            return 0;
    }
    return 0;
}

/* Starting immediately after a provenance-producing GOT load, find an exact
 * private field along at least one decoded path which keeps the base register
 * live.  Calls are represented by each architecture decoder's ABI clobber
 * mask; an indirect edge or unknown instruction ends only that path. */
static int glibc_private_register_field_path(
    const uint8_t *code, size_t length, size_t start,
    unsigned int base_register, size_t expected_offset,
    size_t expected_width, glibc_private_decode_fn decode,
    glibc_private_field_fn field)
{
    unsigned char seen[GLIBC_PRIVATE_CFG_LIMIT];
    uint16_t queue[2 * GLIBC_PRIVATE_CFG_LIMIT + 1];
    size_t head = 0;
    size_t tail = 0;

    if (!code || !decode || !field || length == 0 ||
        length > GLIBC_PRIVATE_CFG_LIMIT || start >= length ||
        base_register >= 32)
        return 0;
    ldr_memset(seen, 0, length);
    queue[tail++] = (uint16_t)start;
    while (head < tail) {
        struct glibc_private_instruction instruction;
        size_t offset;
        size_t width;
        size_t position = queue[head++];

        if (seen[position])
            continue;
        seen[position] = 1;
        if (!decode(code, length, position, &instruction) ||
            instruction.end <= position || instruction.end > length)
            continue;
        if (field(code, length, position, base_register, &offset, &width) &&
            offset == expected_offset &&
            (expected_width == 0 || width == expected_width ||
             (width == 2 * sizeof(size_t) &&
              expected_width == sizeof(size_t))))
            return 1;
        if (instruction.writes & (UINT32_C(1) << base_register))
            continue;
        if (!glibc_private_enqueue_successors(
                &instruction, length, queue,
                sizeof(queue) / sizeof(queue[0]), &tail))
            return 0;
    }
    return 0;
}

struct glibc_private_pair_state {
    uint16_t position;
    uint8_t fields;
};

/* The two size_t words must occur on one real path rooted in the same GOT
 * load.  This is stricter than independently finding each word on mutually
 * exclusive or unreachable paths. */
static int glibc_private_register_pair_path(
    const uint8_t *code, size_t length, size_t start,
    unsigned int base_register, size_t first_offset,
    glibc_private_decode_fn decode, glibc_private_field_fn field)
{
    unsigned char seen[4][GLIBC_PRIVATE_PAIR_LIMIT];
    struct glibc_private_pair_state
        queue[8 * GLIBC_PRIVATE_PAIR_LIMIT + 1];
    size_t head = 0;
    size_t tail = 0;

    if (!code || !decode || !field || length == 0 ||
        length > GLIBC_PRIVATE_PAIR_LIMIT || start >= length ||
        base_register >= 32 ||
        first_offset > SIZE_MAX - sizeof(size_t))
        return 0;
    ldr_memset(seen, 0, sizeof(seen));
    queue[tail++] = (struct glibc_private_pair_state){
        (uint16_t)start, 0 };
    while (head < tail) {
        struct glibc_private_pair_state state = queue[head++];
        struct glibc_private_instruction instruction;
        size_t successors[2];
        size_t successor_count = 0;
        size_t offset;
        size_t width;

        if (seen[state.fields][state.position])
            continue;
        seen[state.fields][state.position] = 1;
        if (!decode(code, length, state.position, &instruction) ||
            instruction.end <= state.position || instruction.end > length)
            continue;
        if (field(code, length, state.position, base_register,
                  &offset, &width)) {
            if (offset == first_offset &&
                width == 2 * sizeof(size_t))
                state.fields = 3;
            else if (width == sizeof(size_t) && offset == first_offset)
                state.fields |= 1;
            else if (width == sizeof(size_t) &&
                     offset == first_offset + sizeof(size_t))
                state.fields |= 2;
        }
        if (state.fields == 3)
            return 1;
        if (instruction.writes & (UINT32_C(1) << base_register))
            continue;
        if (instruction.flow == GLIBC_PRIVATE_FLOW_NORMAL ||
            instruction.flow == GLIBC_PRIVATE_FLOW_CONDITIONAL)
            successors[successor_count++] = instruction.end;
        if (instruction.flow == GLIBC_PRIVATE_FLOW_BRANCH ||
            instruction.flow == GLIBC_PRIVATE_FLOW_CONDITIONAL)
            successors[successor_count++] = instruction.target;
        for (size_t i = 0; i < successor_count; i++) {
            if (successors[i] >= length)
                continue;
            if (tail >= sizeof(queue) / sizeof(queue[0]) ||
                successors[i] > UINT16_MAX)
                return 0;
            queue[tail++] = (struct glibc_private_pair_state){
                (uint16_t)successors[i], state.fields };
        }
    }
    return 0;
}
