  static inline int arch_set_tp(uintptr_t tp) {
      /* Publishing the target TCB/DTV is also a compiler ordering boundary:
       * no initialization access may move past the TP switch, and no target
       * TLS access may move before it. */
      __asm__ volatile("msr tpidr_el0, %0" :: "r"(tp) : "memory");
      return 0;
  }
  static inline uintptr_t arch_get_tp_syscall(void) {
      return arch_get_tp();
  }
  static inline __attribute__((unused)) uintptr_t
  arch_read_tp_offset(unsigned off) {
      return *(uintptr_t *)(arch_get_tp() + off);
  }
  static inline long arch_raw_write(int fd, const void *buf, size_t len) {
      return arch_raw_syscall3(SYS_write, fd, (long)buf, (long)len);
  }
  static inline long arch_raw_close(int fd) {
      return arch_raw_syscall1(SYS_close, fd);
  }
#else
  #error "Unsupported architecture"
#endif

typedef int *(*errno_location_fn)(void);
static errno_location_fn g_real_errno_location;
static int g_target_tls_active;
static int g_target_errno_ready;
static int g_loader_errno;

static inline int raw_syscall_failed(long result)
{
    return (unsigned long)result >= (unsigned long)-4095L;
}

/* Record a Linux error without ever addressing bootstrap-libc TLS after the
 * target TP is live.  VFS entry points additionally publish it through the
 * admitted target libc's __errno_location implementation, but only after
 * target relocation has made that implementation callable. */
static inline void set_loader_errno(int err)
{
    if (g_target_tls_active && g_target_errno_ready &&
        g_real_errno_location) {
        *g_real_errno_location() = err;
        return;
    }
    /* Startup is single-threaded until target relocation/initialization.
     * Keep its errors out of either libc's TLS. */
    g_loader_errno = err;
}

static inline int loader_errno_value(void)
{
    if (g_target_tls_active && g_target_errno_ready) {
        if (g_real_errno_location)
            return *g_real_errno_location();
    }
    return g_loader_errno;
}

static inline long loader_syscall_result(long result)
{
    if (raw_syscall_failed(result)) {
        set_loader_errno((int)-result);
        return -1;
    }
    return result;
}

static void *loader_mmap(void *address, size_t length, int prot, int flags,
                         int fd, off_t offset)
{
    long result = arch_raw_syscall6(SYS_mmap, (long)address, (long)length,
                                    prot, flags, fd, (long)offset);

    if (raw_syscall_failed(result)) {
        set_loader_errno((int)-result);
        return MAP_FAILED;
    }
    return (void *)(uintptr_t)result;
}

static int loader_munmap(void *address, size_t length)
{
    return (int)loader_syscall_result(
        arch_raw_syscall2(SYS_munmap, (long)address, (long)length));
}

#ifdef DLFREEZE_PROTECTION_LIFECYCLE_GATE
static size_t g_loader_mprotect_calls;
#endif

static int loader_mprotect(void *address, size_t length, int prot)
{
#ifdef DLFREEZE_PROTECTION_LIFECYCLE_GATE
    g_loader_mprotect_calls++;
#endif
    return (int)loader_syscall_result(
        arch_raw_syscall3(SYS_mprotect, (long)address, (long)length, prot));
}

#ifdef DLFREEZE_FILEBACK_GATE
static size_t g_mremap_attempts;
static size_t g_mremap_accepts;
static int g_mremap_forced_errno;
static size_t g_mremap_force_attempt;
static int g_executable_probe_forced_munmap_errno;
#endif

/* MREMAP_DONTUNMAP is a Linux ABI flag even when an older libc's headers do
 * not expose it.  Bootstrap admission has already exercised this exact
 * syscall form inside a disposable child, so this wrapper is reached only
 * for a positively proven startup source. */
static void *loader_mremap_dontunmap(void *source, size_t length,
                                     void *target)
{
#if defined(SYS_mremap)
    long result;

#ifdef DLFREEZE_FILEBACK_GATE
    g_mremap_attempts++;
    if (g_mremap_forced_errno != 0 &&
        (g_mremap_force_attempt == 0 ||
         g_mremap_attempts == g_mremap_force_attempt)) {
        set_loader_errno(g_mremap_forced_errno);
        return MAP_FAILED;
    }
#endif
    result = arch_raw_syscall5(
        SYS_mremap, (long)source, (long)length, (long)length,
        MREMAP_MAYMOVE | MREMAP_FIXED | MREMAP_DONTUNMAP,
        (long)target);
    if (raw_syscall_failed(result)) {
        set_loader_errno((int)-result);
        return MAP_FAILED;
    }
#ifdef DLFREEZE_FILEBACK_GATE
    g_mremap_accepts++;
#endif
    return (void *)(uintptr_t)result;
#else
    (void)source;
    (void)length;
    (void)target;
    set_loader_errno(ENOSYS);
    return MAP_FAILED;
#endif
}

static int loader_open(const char *path, int flags)
{
    return (int)loader_syscall_result(
        arch_raw_syscall4(SYS_openat, AT_FDCWD, (long)path, flags, 0));
}

static int loader_close(int fd)
{
    return (int)loader_syscall_result(arch_raw_syscall1(SYS_close, fd));
}

static ssize_t loader_read(int fd, void *buffer, size_t length)
{
    return (ssize_t)loader_syscall_result(
        arch_raw_syscall3(SYS_read, fd, (long)buffer, (long)length));
}

static ssize_t loader_write(int fd, const void *buffer, size_t length)
{
    return (ssize_t)loader_syscall_result(
        arch_raw_syscall3(SYS_write, fd, (long)buffer, (long)length));
}

static ssize_t loader_pread(int fd, void *buffer, size_t length, off_t offset)
{
    return (ssize_t)loader_syscall_result(
        arch_raw_syscall4(SYS_pread64, fd, (long)buffer, (long)length,
                          (long)offset));
}

static int loader_fstat(int fd, struct stat *status)
{
    return (int)loader_syscall_result(
        arch_raw_syscall2(SYS_fstat, fd, (long)status));
}

static int loader_stat(const char *path, struct stat *status)
{
    return (int)loader_syscall_result(
        arch_raw_syscall4(SYS_newfstatat, AT_FDCWD, (long)path,
                          (long)status, 0));
}

static void loader_exit(int status) __attribute__((noreturn));
static void loader_exit(int status)
{
    (void)arch_raw_syscall1(SYS_exit_group, status);
    for (;;) {}
}

/* The target thread pointer replaces the bootstrap libc's thread pointer
 * part-way through direct loading.  Even usually-pure libc entry points are
 * not a sound post-handoff dependency: an alternate static libc is free to
 * dispatch them through TLS or other libc-owned process state.  Keep the
 * loader's byte/string primitives wholly inside this translation unit.
 *
 * memcpy/memset use explicit instructions so compilers cannot recognize the
 * implementation loop and turn it back into a call to the bootstrap libc.
 * The scan helpers use volatile reads for the same reason.  Direct loading is
 * admitted only on the two architectures covered below. */
static void *ldr_memcpy(void *destination, const void *source, size_t length)
{
    void *result = destination;
    unsigned char *dst = destination;
    const unsigned char *src = source;

#if defined(__x86_64__)
    /* Startup parsing copies thousands of fixed-size ELF records.  REP MOVSB
     * is excellent for bulk mappings but has disproportionate setup cost for
     * those 4--64 byte copies.  Use only baseline x86-64 instructions for the
     * bounded short path; each access remains wholly inside the caller's
     * range and unaligned x86 loads/stores are architectural. */
    if (length <= 64) {
        while (length >= 16) {
            __asm__ volatile(
                "movdqu (%1), %%xmm0\n\t"
                "movdqu %%xmm0, (%0)"
                :
                : "r"(dst), "r"(src)
                : "xmm0", "memory");
            dst += 16;
            src += 16;
            length -= 16;
        }
        if (length >= 8) {
            uint64_t word;

            __asm__ volatile(
                "movq (%1), %0\n\t"
                "movq %0, (%2)"
                : "=&r"(word)
                : "r"(src), "r"(dst)
                : "memory");
            dst += 8;
            src += 8;
            length -= 8;
        }
        if (length >= 4) {
            uint32_t word;

            __asm__ volatile(
                "movl (%1), %0\n\t"
                "movl %0, (%2)"
                : "=&r"(word)
                : "r"(src), "r"(dst)
                : "memory");
            dst += 4;
            src += 4;
            length -= 4;
        }
        if (length >= 2) {
            uint16_t word;

            __asm__ volatile(
                "movw (%1), %0\n\t"
                "movw %0, (%2)"
                : "=&r"(word)
                : "r"(src), "r"(dst)
                : "memory");
            dst += 2;
            src += 2;
            length -= 2;
        }
        if (length != 0) {
            unsigned char byte;

            __asm__ volatile(
                "movb (%1), %0\n\t"
                "movb %0, (%2)"
                : "=&q"(byte)
                : "r"(src), "r"(dst)
                : "memory");
        }
        return result;
    }
    __asm__ volatile("rep movsb"
                     : "+D"(dst), "+S"(src), "+c"(length)
                     :
                     : "memory");
#elif defined(__aarch64__)
    while (length >= 16) {
        uint64_t first;
        uint64_t second;

        __asm__ volatile(
            "ldp %0, %1, [%2], #16\n\t"
            "stp %0, %1, [%3], #16"
            : "=&r"(first), "=&r"(second), "+r"(src), "+r"(dst)
            :
            : "memory");
        length -= 16;
    }
    if ((length & 8U) != 0) {
        uint64_t word;

        __asm__ volatile(
            "ldr %0, [%1], #8\n\t"
            "str %0, [%2], #8"
            : "=&r"(word), "+r"(src), "+r"(dst)
            :
            : "memory");
    }
    if ((length & 4U) != 0) {
        uint32_t word;

        __asm__ volatile(
            "ldr %w0, [%1], #4\n\t"
            "str %w0, [%2], #4"
            : "=&r"(word), "+r"(src), "+r"(dst)
            :
            : "memory");
    }
    if ((length & 2U) != 0) {
        uint32_t word;

        __asm__ volatile(
            "ldrh %w0, [%1], #2\n\t"
            "strh %w0, [%2], #2"
            : "=&r"(word), "+r"(src), "+r"(dst)
            :
            : "memory");
    }
    if ((length & 1U) != 0) {
        unsigned int byte;

        __asm__ volatile(
            "ldrb %w0, [%1], #1\n\t"
            "strb %w0, [%2], #1"
            : "=&r"(byte), "+r"(src), "+r"(dst)
            :
            : "memory");
    }
#endif
    return result;
}

static void *ldr_memset(void *destination, int value, size_t length)
{
    void *result = destination;
    unsigned char *dst = destination;
    unsigned char byte = (unsigned char)value;

#if defined(__x86_64__)
    __asm__ volatile("rep stosb"
                     : "+D"(dst), "+c"(length)
                     : "a"(byte)
                     : "memory");
#elif defined(__aarch64__)
    uint64_t pattern = byte;

    pattern |= pattern << 8;
    pattern |= pattern << 16;
    pattern |= pattern << 32;
    while (length >= 16) {
        __asm__ volatile("stp %1, %1, [%0], #16"
                         : "+&r"(dst)
                         : "r"(pattern)
                         : "memory");
        length -= 16;
    }
    if ((length & 8U) != 0) {
        __asm__ volatile("str %1, [%0], #8"
                         : "+&r"(dst)
                         : "r"(pattern)
                         : "memory");
    }
    if ((length & 4U) != 0) {
        __asm__ volatile("str %w1, [%0], #4"
                         : "+&r"(dst)
                         : "r"(pattern)
                         : "memory");
    }
    if ((length & 2U) != 0) {
        __asm__ volatile("strh %w1, [%0], #2"
                         : "+&r"(dst)
                         : "r"(pattern)
                         : "memory");
    }
    if ((length & 1U) != 0) {
        __asm__ volatile("strb %w1, [%0], #1"
                         : "+&r"(dst)
                         : "r"((unsigned int)byte)
                         : "memory");
    }
#endif
    return result;
}

#define LDR_MEMCHR_WORD_BATCH 4U
#define LDR_MEMCHR_VECTOR_BYTES 16U
#define LDR_MEMCHR_VECTOR_BATCH 4U

typedef unsigned char ldr_byte_vector
    __attribute__((__vector_size__(LDR_MEMCHR_VECTOR_BYTES)));
typedef ldr_byte_vector ldr_unaligned_byte_vector
    __attribute__((__aligned__(1), __may_alias__));

union ldr_byte_vector_view {
    ldr_byte_vector vector;
    unsigned char bytes[LDR_MEMCHR_VECTOR_BYTES];
};

static inline ldr_byte_vector
ldr_byte_vector_load(const volatile unsigned char *address)
{
    /* Only the memory access needs byte alignment and aliasing permission.
     * Keep vector values naturally aligned for the compiler's register and
     * function ABI, while this volatile load remains one bounded access. */
    return *(const volatile ldr_unaligned_byte_vector *)
        (const void *)address;
}

static inline ldr_byte_vector
ldr_byte_vector_equal(ldr_byte_vector chunk, ldr_byte_vector pattern)
{
#if defined(__x86_64__)
    __asm__ volatile(
        "pcmpeqb %1, %0"
        : "+x"(chunk)
        : "x"(pattern)
        : "cc");
#elif defined(__aarch64__)
    __asm__ volatile(
        "cmeq %0.16b, %0.16b, %1.16b"
        : "+w"(chunk)
        : "w"(pattern));
#endif
    return chunk;
}

static inline int
ldr_byte_vector_has_match(ldr_byte_vector equality)
{
#if defined(__x86_64__)
    unsigned int mask;

    /* SSE2 is part of the x86-64 baseline. */
    __asm__ volatile(
        "pmovmskb %1, %0"
        : "=r"(mask)
        : "x"(equality));
    return mask != 0;
#elif defined(__aarch64__)
    unsigned int any;

    /* Advanced SIMD is part of the AArch64 baseline. */
    __asm__ volatile(
        "umaxv %b0, %0.16b\n\t"
        "umov %w1, %0.b[0]"
        : "+w"(equality), "=r"(any));
    return any != 0;
#endif
}

static inline size_t
ldr_byte_vector_match_index(ldr_byte_vector equality)
{
#if defined(__x86_64__)
    unsigned int mask;

    __asm__ volatile(
        "pmovmskb %1, %0"
        : "=r"(mask)
        : "x"(equality));
    return mask != 0 ? (size_t)__builtin_ctz(mask)
                     : LDR_MEMCHR_VECTOR_BYTES;
#elif defined(__aarch64__)
    union ldr_byte_vector_view view = { .vector = equality };

    for (size_t i = 0; i < LDR_MEMCHR_VECTOR_BYTES; i++)
        if (view.bytes[i] != 0)
            return i;
    return LDR_MEMCHR_VECTOR_BYTES;
#endif
}

/* Read only complete, in-range vectors. A mismatch is resolved in address
 * order, preserving unsigned-byte lexicographic ordering on both targets.
 * Like the other loader primitives this must never dispatch through the
 * bootstrap libc after the target thread pointer has been installed. */
static int ldr_memcmp(const void *left, const void *right, size_t length)
{
    const volatile unsigned char *a = left;
    const volatile unsigned char *b = right;

    while (length >= 4U * LDR_MEMCHR_VECTOR_BYTES) {
        ldr_byte_vector equal[4];
        ldr_byte_vector all;

        for (unsigned int i = 0; i < 4; i++)
            equal[i] = ldr_byte_vector_equal(
                ldr_byte_vector_load(a + i * LDR_MEMCHR_VECTOR_BYTES),
                ldr_byte_vector_load(b + i * LDR_MEMCHR_VECTOR_BYTES));
        all = equal[0] & equal[1] & equal[2] & equal[3];
        if (ldr_byte_vector_has_match(~all)) {
            for (unsigned int i = 0; i < 4; i++) {
                size_t index = ldr_byte_vector_match_index(~equal[i]);

                if (index < LDR_MEMCHR_VECTOR_BYTES) {
                    index += i * LDR_MEMCHR_VECTOR_BYTES;
                    return a[index] < b[index] ? -1 : 1;
                }
            }
        }
        a += 4U * LDR_MEMCHR_VECTOR_BYTES;
        b += 4U * LDR_MEMCHR_VECTOR_BYTES;
        length -= 4U * LDR_MEMCHR_VECTOR_BYTES;
    }
    while (length >= LDR_MEMCHR_VECTOR_BYTES) {
        ldr_byte_vector equal = ldr_byte_vector_equal(
            ldr_byte_vector_load(a), ldr_byte_vector_load(b));
        size_t index = ldr_byte_vector_match_index(~equal);

        if (index < LDR_MEMCHR_VECTOR_BYTES)
            return a[index] < b[index] ? -1 : 1;
        a += LDR_MEMCHR_VECTOR_BYTES;
        b += LDR_MEMCHR_VECTOR_BYTES;
        length -= LDR_MEMCHR_VECTOR_BYTES;
    }
    while (length-- != 0) {
        unsigned char av = *a++;
        unsigned char bv = *b++;

        if (av != bv)
            return av < bv ? -1 : 1;
    }
    return 0;
}

#ifdef DLFREEZE_MEMCHR_COMPLEXITY_GATE
static size_t g_ldr_memchr_word_loads;
static size_t g_ldr_memchr_byte_loads;
static size_t g_ldr_memchr_vector_loads;
static size_t g_ldr_memchr_vector_batch_iterations;
static size_t g_ldr_memchr_vector_batch_reductions;
static size_t g_ldr_memchr_batch_iterations;
static size_t g_ldr_memchr_single_word_iterations;
#define LDR_MEMCHR_COUNT(counter) ((counter)++)
#else
#define LDR_MEMCHR_COUNT(counter) ((void)0)
#endif

static void *ldr_memchr(const void *memory, int value, size_t length)
{
    const volatile unsigned char *cursor = memory;
    typedef uintptr_t ldr_alias_word __attribute__((__may_alias__));
    const size_t word_size = sizeof(ldr_alias_word);
    const ldr_alias_word ones = UINTPTR_MAX / UINT8_MAX;
    const ldr_alias_word high_bits = ones << 7;
    const ldr_alias_word pattern = ones * (unsigned char)value;
    const volatile unsigned char *candidate_cursor = NULL;
    unsigned char byte = (unsigned char)value;
    ldr_byte_vector vector_pattern = {
        byte, byte, byte, byte, byte, byte, byte, byte,
        byte, byte, byte, byte, byte, byte, byte, byte
    };

#define LDR_MEMCHR_TEST_WORD(offset)                                      \
    do {                                                                 \
        ldr_alias_word word =                                            \
            *(const volatile ldr_alias_word *)(const void *)             \
                (cursor + (offset));                                     \
        ldr_alias_word candidate = word ^ pattern;                       \
                                                                         \
        LDR_MEMCHR_COUNT(g_ldr_memchr_word_loads);                       \
        if (((candidate - ones) & ~candidate & high_bits) != 0) {        \
            candidate_cursor = cursor + (offset);                        \
            goto confirm_candidate;                                     \
        }                                                                \
    } while (0)

    _Static_assert((sizeof(ldr_alias_word) &
                    (sizeof(ldr_alias_word) - 1)) == 0,
                   "loader word size must be a power of two");
    _Static_assert(sizeof(ldr_byte_vector) == LDR_MEMCHR_VECTOR_BYTES,
                   "loader vector size mismatch");
    _Static_assert((LDR_MEMCHR_VECTOR_BYTES &
                    (LDR_MEMCHR_VECTOR_BYTES - 1U)) == 0,
                   "loader vector size must be a power of two");
    /* Both supported ELF64 architectures provide a baseline 16-byte vector
     * ISA (SSE2 on x86-64, Advanced SIMD on AArch64).  Load four increasing
     * vectors without an alignment precondition, retain their equality
     * results, and reduce their OR once for the overwhelmingly common
     * 64-byte miss.  A hit inspects those saved results in address order, so
     * first-match semantics require no second read and remain independent of
     * endian.  Every load is entered only when its complete vector is inside
     * the caller's declared span. */
    while (length >= LDR_MEMCHR_VECTOR_BATCH *
                         LDR_MEMCHR_VECTOR_BYTES) {
        ldr_byte_vector matches[LDR_MEMCHR_VECTOR_BATCH];
        ldr_byte_vector combined;

        LDR_MEMCHR_COUNT(g_ldr_memchr_vector_batch_iterations);
        matches[0] = ldr_byte_vector_equal(
            ldr_byte_vector_load(
                cursor + 0U * LDR_MEMCHR_VECTOR_BYTES), vector_pattern);
        LDR_MEMCHR_COUNT(g_ldr_memchr_vector_loads);
        matches[1] = ldr_byte_vector_equal(
            ldr_byte_vector_load(
                cursor + 1U * LDR_MEMCHR_VECTOR_BYTES), vector_pattern);
        LDR_MEMCHR_COUNT(g_ldr_memchr_vector_loads);
        matches[2] = ldr_byte_vector_equal(
            ldr_byte_vector_load(
                cursor + 2U * LDR_MEMCHR_VECTOR_BYTES), vector_pattern);
        LDR_MEMCHR_COUNT(g_ldr_memchr_vector_loads);
        matches[3] = ldr_byte_vector_equal(
            ldr_byte_vector_load(
                cursor + 3U * LDR_MEMCHR_VECTOR_BYTES), vector_pattern);
        LDR_MEMCHR_COUNT(g_ldr_memchr_vector_loads);
        combined = matches[0] | matches[1] | matches[2] | matches[3];
        LDR_MEMCHR_COUNT(g_ldr_memchr_vector_batch_reductions);
        if (ldr_byte_vector_has_match(combined)) {
            for (size_t i = 0; i < LDR_MEMCHR_VECTOR_BATCH; i++) {
                size_t match = ldr_byte_vector_match_index(matches[i]);

                if (match != LDR_MEMCHR_VECTOR_BYTES)
                    return (void *)(uintptr_t)(
                        cursor + i * LDR_MEMCHR_VECTOR_BYTES + match);
            }
            return NULL;
        }
        cursor += LDR_MEMCHR_VECTOR_BATCH * LDR_MEMCHR_VECTOR_BYTES;
        length -= LDR_MEMCHR_VECTOR_BATCH * LDR_MEMCHR_VECTOR_BYTES;
    }
    /* Align only the scalar-word tail.  This peel stays wholly inside the
     * declared span and is reached after at most one vector-batch remainder,
     * rather than once at the start of every restarted candidate scan. */
    while (length != 0 &&
           ((uintptr_t)cursor & (word_size - 1U)) != 0) {
        LDR_MEMCHR_COUNT(g_ldr_memchr_byte_loads);
        if (*cursor == byte)
            return (void *)(uintptr_t)cursor;
        cursor++;
        length--;
    }
    /* Four independent, in-bounds word probes amortize loop bookkeeping on
     * long no-match spans.  Each probe is still performed in address order,
     * and the batch is entered only when all four words are within length. */
    while (length >= LDR_MEMCHR_WORD_BATCH * word_size) {
        LDR_MEMCHR_COUNT(g_ldr_memchr_batch_iterations);
        LDR_MEMCHR_TEST_WORD(0U * word_size);
        LDR_MEMCHR_TEST_WORD(1U * word_size);
        LDR_MEMCHR_TEST_WORD(2U * word_size);
        LDR_MEMCHR_TEST_WORD(3U * word_size);
        cursor += LDR_MEMCHR_WORD_BATCH * word_size;
        length -= LDR_MEMCHR_WORD_BATCH * word_size;
    }
    while (length >= word_size) {
        LDR_MEMCHR_COUNT(g_ldr_memchr_single_word_iterations);
        LDR_MEMCHR_TEST_WORD(0);
        cursor += word_size;
        length -= word_size;
    }
    while (length != 0) {
        LDR_MEMCHR_COUNT(g_ldr_memchr_byte_loads);
        if (*cursor == byte)
            return (void *)(uintptr_t)cursor;
        cursor++;
        length--;
    }
    return NULL;

confirm_candidate:
    /* The word predicate guarantees at least one exact byte match.  Keep the
     * confirmation bytewise so its first result is independent of endian. */
    for (size_t i = 0; i < word_size; i++) {
        LDR_MEMCHR_COUNT(g_ldr_memchr_byte_loads);
        if (candidate_cursor[i] == byte)
            return (void *)(uintptr_t)(candidate_cursor + i);
    }
    return NULL;

#undef LDR_MEMCHR_TEST_WORD
}

#undef LDR_MEMCHR_COUNT

static size_t ldr_strlen(const char *string)
{
    const volatile unsigned char *start =
        (const volatile unsigned char *)string;
    const volatile unsigned char *cursor = start;

    while (*cursor != '\0')
        cursor++;
    return (size_t)(cursor - start);
}

static int ldr_strcmp(const char *left, const char *right)
{
    const volatile unsigned char *a =
        (const volatile unsigned char *)left;
    const volatile unsigned char *b =
        (const volatile unsigned char *)right;

    while (*a != '\0' && *a == *b) {
        a++;
        b++;
    }
    return *a < *b ? -1 : *a != *b;
}

static int ldr_strncmp(const char *left, const char *right, size_t length)
{
    const volatile unsigned char *a =
        (const volatile unsigned char *)left;
    const volatile unsigned char *b =
        (const volatile unsigned char *)right;

    while (length-- != 0) {
        unsigned char av = *a++;
        unsigned char bv = *b++;

        if (av != bv)
            return av < bv ? -1 : 1;
        if (av == '\0')
            return 0;
    }
    return 0;
}

static char *ldr_strchr(const char *string, int value)
{
    const volatile unsigned char *cursor =
        (const volatile unsigned char *)string;
    unsigned char byte = (unsigned char)value;

    for (;;) {
        unsigned char current = *cursor;

        if (current == byte)
            return (char *)(uintptr_t)cursor;
        if (current == '\0')
            return NULL;
        cursor++;
    }
}

static char *ldr_strrchr(const char *string, int value)
{
    const volatile unsigned char *cursor =
        (const volatile unsigned char *)string;
    const volatile unsigned char *match = NULL;
    unsigned char byte = (unsigned char)value;

    for (;;) {
        unsigned char current = *cursor;

        if (current == byte)
            match = cursor;
        if (current == '\0')
            return (char *)(uintptr_t)match;
        cursor++;
    }
}

/* r_offset is a byte address, not a C alignment promise.  Linkers can emit
 * scalar relocations into packed fields, so every relocation word access
 * must remain defined even when the destination is not uint64_t-aligned. */
typedef uint64_t relocation_unaligned_u64
    __attribute__((__aligned__(1), __may_alias__));

static uint64_t relocation_load_u64(const void *address)
{
    return *(const volatile relocation_unaligned_u64 *)address;
}

static void relocation_store_u64(void *address, uint64_t value)
{
    *(volatile relocation_unaligned_u64 *)address = value;
}

static void relocation_store_u64_pair(void *address,
                                      uint64_t first, uint64_t second)
{
    relocation_store_u64(address, first);
    relocation_store_u64((uint8_t *)address + sizeof(uint64_t), second);
}

