static uint64_t page_floor(uint64_t value)
{
    return value & ~(g_page_size - 1);
}

static int u64_add_checked(uint64_t left, uint64_t right, uint64_t *out)
{
    if (right > UINT64_MAX - left)
        return 0;
    *out = left + right;
    return 1;
}

#if defined(__aarch64__)
static int u64_ranges_overlap_or_overflow(uint64_t first,
                                          uint64_t first_size,
                                          uint64_t second,
                                          uint64_t second_size)
{
    uint64_t first_end;
    uint64_t second_end;

    if (!u64_add_checked(first, first_size, &first_end) ||
        !u64_add_checked(second, second_size, &second_end))
        return 1;
    return first < second_end && second < first_end;
}
#endif

static int u64_mul_checked(uint64_t left, uint64_t right, uint64_t *out)
{
    if (left != 0 && right > UINT64_MAX / left)
        return 0;
    *out = left * right;
    return 1;
}

static int u64_align_up_checked(uint64_t value, uint64_t align,
                                uint64_t *out)
{
    uint64_t mask;

    if (align == 0 || (align & (align - 1)) != 0)
        return 0;
    mask = align - 1;
    if (value > UINT64_MAX - mask)
        return 0;
    *out = (value + mask) & ~mask;
    return 1;
}

/* Smallest result >= value whose low alignment bits equal residue.  ELF TLS
 * uses this congruence, not necessarily a zero-aligned block start. */
static int u64_align_residue_up_checked(uint64_t value, uint64_t align,
                                        uint64_t residue, uint64_t *out)
{
    uint64_t mask;
    uint64_t delta;

    if (align == 0 || (align & (align - 1)) != 0)
        return 0;
    mask = align - 1;
    residue &= mask;
    delta = (residue - (value & mask)) & mask;
    return u64_add_checked(value, delta, out);
}

static int u64_add_i64_checked(uint64_t base, int64_t delta, uint64_t *out)
{
    if (delta >= 0)
        return u64_add_checked(base, (uint64_t)delta, out);

    uint64_t magnitude = (uint64_t)(-(delta + 1)) + 1;
    if (magnitude > base)
        return 0;
    *out = base - magnitude;
    return 1;
}

static int i64_add_u64_checked(int64_t base, uint64_t addend, int64_t *out)
{
    if (base >= 0) {
        if (addend > (uint64_t)(INT64_MAX - base))
            return 0;
        *out = base + (int64_t)addend;
        return 1;
    }

    uint64_t magnitude = (uint64_t)(-(base + 1)) + 1;
    if (addend >= magnitude) {
        uint64_t positive = addend - magnitude;

        if (positive > INT64_MAX)
            return 0;
        *out = (int64_t)positive;
        return 1;
    }

    magnitude -= addend;
    if (magnitude == (uint64_t)INT64_MAX + 1) {
        *out = INT64_MIN;
        return 1;
    }
    *out = -(int64_t)magnitude;
    return 1;
}

static int i64_add_checked(int64_t left, int64_t right, int64_t *out)
{
    if ((right > 0 && left > INT64_MAX - right) ||
        (right < 0 && left < INT64_MIN - right))
        return 0;
    *out = left + right;
    return 1;
}

