static int x86_64_modrm_end(const uint8_t *code, size_t len,
                            size_t modrm_pos, size_t *end_out);
static int x86_64_musl_gap_safe(const uint8_t *code, size_t begin,
                                size_t end, unsigned int flag_reg,
                                int preserve_flags);
