static int musl_defined_function_view(const struct loaded_obj *obj,
                                      const char *name, size_t minimum,
                                      size_t maximum, const uint8_t **code_out,
                                      size_t *length_out)
{
    const Elf64_Sym *sym = NULL;
    void *address;
    void *file_address;
    size_t full_length;
    size_t length;

    if (unique_default_exported_symbol(obj, name, &sym) !=
            UNIQUE_DEFAULT_SYMBOL_FOUND ||
        ELF64_ST_TYPE(sym->st_info) != STT_FUNC ||
        sym->st_shndx == SHN_UNDEF || sym->st_shndx >= SHN_LORESERVE ||
        sym->st_size < minimum || sym->st_size > SIZE_MAX)
        return 0;
    full_length = (size_t)sym->st_size;
    length = full_length > maximum ? maximum : full_length;
    if (!loaded_obj_vaddr_pointer(obj, sym->st_value, full_length, PF_X,
                                  &address) ||
        !loaded_obj_file_vaddr_pointer(
            obj, sym->st_value, full_length, &file_address) ||
        file_address != address)
        return 0;
    *code_out = address;
    *length_out = length;
    return 1;
}

static int musl_target_executable_address(const struct loaded_obj *obj,
                                          uintptr_t address, size_t length)
{
    void *checked;

    if (address < obj->base || address - obj->base > INT64_MAX)
        return 0;
    return loaded_obj_signed_offset_pointer(
        obj, (int64_t)(address - obj->base), length, PF_X, &checked);
}

/* A code reference to a writable slot is not enough to establish the object
 * it will contain once relocations run.  Tie target-contract GOT loads to the
 * exact target dynsym entry and its unique GLOB_DAT relocation. */
static int musl_got_slot_relocates_to_symbol(
    const struct loaded_obj *obj, uintptr_t slot,
    const Elf64_Sym *symbol)
{
    uintptr_t symbol_address;
    uintptr_t table_address;
    size_t table_bytes;
    uint64_t symbol_index;
    uint64_t offset;
    unsigned int matches = 0;

    if (!obj->dynsym || !symbol || slot < obj->base)
        return 0;
    symbol_address = (uintptr_t)symbol;
    table_address = (uintptr_t)obj->dynsym;
    table_bytes = (size_t)obj->dynsym_count * sizeof(Elf64_Sym);
    if (symbol_address < table_address ||
        symbol_address - table_address >= table_bytes ||
        (symbol_address - table_address) % sizeof(Elf64_Sym) != 0)
        return 0;
    symbol_index =
        (uint64_t)((symbol_address - table_address) / sizeof(Elf64_Sym));
    offset = (uint64_t)(slot - obj->base);

    for (enum loaded_rela_table table = LOADED_RELA_DYNAMIC;
         table < LOADED_RELA_TABLE_COUNT; table++) {
        size_t count = loaded_rela_table_count(obj, table);

        for (size_t i = 0; i < count; i++) {
            Elf64_Rela relocation;
            const Elf64_Rela *rel = &relocation;

            if (!loaded_rela_read(obj, table, i, &relocation))
                return 0;
            if (rel->r_offset != offset)
                continue;
            if (ELF64_R_TYPE(rel->r_info) != ARCH_RELOC_GLOB_DAT ||
                ELF64_R_SYM(rel->r_info) != symbol_index ||
                rel->r_addend != 0)
                return 0;
            matches++;
        }
    }
    return matches == 1;
}

#if defined(__x86_64__)
static int x86_64_direct_call_target(const uint8_t *code, size_t length,
                                     size_t offset, uintptr_t *target_out)
{
    uint64_t target;

    if (offset + 5 > length || code[offset] != 0xe8 ||
        !u64_add_i64_checked((uintptr_t)(code + offset + 5),
                             read_i32_le(code + offset + 1), &target) ||
        target > UINTPTR_MAX)
        return 0;
    *target_out = (uintptr_t)target;
    return 1;
}

static int x86_64_exact_return_stub(const struct loaded_obj *obj,
                                    uintptr_t address)
{
    const uint8_t *code = (const uint8_t *)address;
    size_t offset = 0;

    if (!musl_target_executable_address(obj, address, 5))
        return 0;
    /* Permit only the standard CET landing pad and single-byte NOP padding
     * before RET.  A branch, call, or data access would make __init_tls
     * observable and therefore unsafe to skip/re-enter. */
    if (memcmp(code, "\xf3\x0f\x1e\xfa", 4) == 0)
        offset = 4;
    while (offset < 4 && code[offset] == 0x90)
        offset++;
    return code[offset] == 0xc3;
}

struct x86_64_musl_guard_load {
    size_t end;
    unsigned int reg;
};

static int x86_64_musl_stack_move(const uint8_t *code, size_t len,
                                  size_t i, int load,
                                  unsigned int *reg_out, size_t *off_out,
                                  size_t *end_out)
{
    uint8_t rex;
    uint8_t modrm;
    unsigned int base;

    if (i + 3 > len || (code[i] & 0xf8) != 0x48 ||
        code[i + 1] != (load ? 0x8b : 0x89) ||
        !decode_x86_64_mem_disp(
            code, len, i, 2, off_out, &base) || base != 4 ||
        !x86_64_modrm_end(code, len, i + 2, end_out))
        return 0;
    rex = code[i];
    modrm = code[i + 2];
    *reg_out = ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);
    return 1;
}

static int x86_64_musl_only_nops(const uint8_t *code,
                                  size_t begin, size_t end)
{
    if (begin > end)
        return 0;
    for (size_t i = begin; i < end; i++)
        if (code[i] != 0x90)
            return 0;
    return 1;
}

static int x86_64_musl_callee_saved(unsigned int reg);

/* A frame-pointer spill keeps a volatile guard address across a call in
 * compiler builds which retain RBP.  Bound the slot by the actual frame
 * allocation, and require the save/restore and argument move around one
 * direct call.  No inference from a libc release or deployment name is
 * needed. */
static int x86_64_musl_frame_guard_reaches_clear(
    const struct loaded_obj *obj, const uint8_t *code, size_t len,
    size_t load_end, unsigned int guard_reg, size_t clear)
{
    size_t prologue = 0;
    size_t frame_end;
    size_t frame_size;
    size_t spill;
    size_t call;
    size_t call_end;
    uintptr_t target;
    uint8_t modrm;
    int displacement;

    if (len >= 4 && memcmp(code, "\xf3\x0f\x1e\xfa", 4) == 0)
        prologue = 4;
    if (prologue + 8 > load_end || load_end > clear || clear > len ||
        memcmp(code + prologue, "\x55\x48\x89\xe5\x48\x83\xec", 7) != 0)
        return 0;
    frame_size = code[prologue + 7];
    frame_end = prologue + 8;
    /* Entry RSP is eight bytes below a 16-byte boundary.  PUSH RBP aligns
     * it, so the exact straight-line call path below needs an allocation
     * which preserves that SysV call-site alignment. */
    if (frame_size < sizeof(uintptr_t) || frame_size >= 128 ||
        (frame_size & 15) != 0)
        return 0;

    /* Before the relocation-proven guard load, admit only padding and the
     * entropy-input test/forward branch.  Neither changes RBP or RSP. */
    for (size_t pos = frame_end; pos < load_end - 7;) {
        if (code[pos] == 0x90) {
            pos++;
        } else if (pos + 5 <= load_end - 7 &&
                   memcmp(code + pos, "\x48\x85\xff\x74", 4) == 0 &&
                   (int8_t)code[pos + 4] > 0 &&
                   (size_t)(uint8_t)code[pos + 4] <= len - pos - 5 &&
                   pos + 5 + code[pos + 4] >= clear) {
            pos += 5;
        } else {
            return 0;
        }
    }
    if (guard_reg == 4 || guard_reg == 5)
        return 0;
    for (spill = load_end; spill + 4 <= clear; spill++) {
        if ((code[spill] & 0xfb) != 0x48 || code[spill + 1] != 0x89 ||
            !x86_64_musl_gap_safe(code, load_end, spill, guard_reg, 0) ||
            !x86_64_musl_gap_safe(code, load_end, spill, 5, 0) ||
            !x86_64_musl_gap_safe(code, load_end, spill, 4, 0))
            continue;
        modrm = code[spill + 2];
        displacement = (int8_t)code[spill + 3];
        if ((modrm & 0xc7) != 0x45 ||
            (((modrm >> 3) & 7) | ((code[spill] & 4) ? 8 : 0)) != guard_reg ||
            displacement > -(int)sizeof(uintptr_t) ||
            (size_t)-displacement > frame_size)
            continue;
        call = spill + 4;
        /* Move the saved guard pointer into memcpy's destination argument.
         * Register-only argument setup cannot overwrite the saved slot. */
        if (call + 3 <= clear &&
            code[call] == (uint8_t)(0x48 | (guard_reg >= 8 ? 4 : 0)) &&
            code[call + 1] == 0x89 &&
            code[call + 2] == (uint8_t)(0xc7 | ((guard_reg & 7) << 3))) {
            call += 3;
        } else if (spill < load_end + 3 ||
                   code[spill - 3] != (uint8_t)(0x48 | (guard_reg >= 8 ? 4 : 0)) ||
                   code[spill - 2] != 0x89 ||
                   code[spill - 1] != (uint8_t)(0xc7 | ((guard_reg & 7) << 3))) {
            /* Scheduling the argument move immediately before the spill
             * is equivalent: the proven frame store cannot change RDI. */
            continue;
        }
        /* Linkers may retain the address-size prefix when relaxing a GOT
         * call.  It does not change a relative near call in 64-bit mode. */
        if (call < clear && code[call] == 0x67)
            call++;
        if (!x86_64_direct_call_target(code, clear, call, &target) ||
            !musl_target_executable_address(obj, target, 1))
            continue;
        call_end = call + 5;
        if (call_end + 4 > clear ||
            code[call_end] != code[spill] || code[call_end + 1] != 0x8b ||
            code[call_end + 2] != modrm ||
            code[call_end + 3] != code[spill + 3] ||
            !x86_64_musl_gap_safe(
                code, call_end + 4, clear, guard_reg, 0))
            continue;
        return 1;
    }
    return 0;
}

/* Establish that the register used by guard[1] = 0 still carries the
 * relocation-proven __stack_chk_guard address.  Compilers may keep it live
 * in an ABI-preserved register or spill it across the entropy-copy call;
 * both shapes are admitted only through their exact call/data-flow proof. */
static int x86_64_musl_guard_reaches_clear(
    const struct loaded_obj *obj, const uint8_t *code, size_t len,
    size_t load_end, unsigned int guard_reg, size_t clear)
{
    if (load_end > clear)
        return 0;
    if (x86_64_musl_gap_safe(
            code, load_end, clear, guard_reg, 0))
        return 1;
    if (x86_64_musl_frame_guard_reaches_clear(
            obj, code, len, load_end, guard_reg, clear))
        return 1;

    /* The System V x86-64 ABI also permits a compiler to keep the guard
     * address live in a callee-saved register across the entropy-copy call.
     * Admit that shape only when the bytes on both sides of one direct,
     * in-object call are fully decoded and proven not to clobber the guard.
     * This deliberately excludes volatile registers, indirect calls,
     * out-of-image targets, and paths containing more than one call. */
    if (x86_64_musl_callee_saved(guard_reg)) {
        unsigned int call_paths = 0;

        for (size_t call = load_end; call + 5 <= clear; call++) {
            uintptr_t target;

            if (code[call] != 0xe8 ||
                !x86_64_musl_gap_safe(
                    code, load_end, call, guard_reg, 0) ||
                !x86_64_direct_call_target(code, len, call, &target) ||
                !musl_target_executable_address(obj, target, 1) ||
                !x86_64_musl_gap_safe(
                    code, call + 5, clear, guard_reg, 0))
                continue;
            call_paths++;
        }
        if (call_paths == 1)
            return 1;
    }

    for (size_t spill = load_end;
         spill + 3 <= clear && spill <= load_end + 64; spill++) {
        unsigned int spill_reg;
        size_t spill_off;
        size_t spill_end;

        if (!x86_64_musl_stack_move(
                code, len, spill, 0, &spill_reg, &spill_off, &spill_end) ||
            spill_reg != guard_reg ||
            !x86_64_musl_gap_safe(
                code, load_end, spill, guard_reg, 0))
            continue;
        for (size_t call = spill_end;
             call + 5 <= clear && call <= spill_end + 16; call++) {
            uintptr_t target;

            if (!x86_64_musl_only_nops(code, spill_end, call) ||
                !x86_64_direct_call_target(code, len, call, &target) ||
                !musl_target_executable_address(obj, target, 1))
                continue;
            for (size_t reload = call + 5;
                 reload + 3 <= clear && reload <= call + 21; reload++) {
                unsigned int reload_reg;
                size_t reload_off;
                size_t reload_end;

                if (!x86_64_musl_only_nops(code, call + 5, reload) ||
                    !x86_64_musl_stack_move(
                        code, len, reload, 1, &reload_reg, &reload_off,
                        &reload_end) || reload_reg != guard_reg ||
                    reload_off != spill_off ||
                    !x86_64_musl_gap_safe(
                        code, reload_end, clear, guard_reg, 0))
                    continue;
                return 1;
            }
        }
    }
    return 0;
}

/* Decode one ordered guard-value -> thread-pointer -> TCB-store chain.  The
 * gap decoder rejects branches, calls, unknown instructions, and writes to
 * either live register, so matches cannot be assembled from different basic
 * blocks or from values whose provenance was clobbered. */
static int x86_64_musl_guard_copy_chain(
    const uint8_t *code, size_t len, size_t ready,
    unsigned int guard_reg, size_t *matched_offset, int *have_match)
{
    size_t value_limit = ready + 32 < len ? ready + 32 : len;

    for (size_t value = ready; value + 3 <= value_limit; value++) {
        uint8_t value_rex = code[value];
        size_t value_offset;
        size_t value_end;
        unsigned int value_reg;
        unsigned int value_base;

        if ((value_rex & 0xf8) != 0x48 || code[value + 1] != 0x8b ||
            !decode_x86_64_mem_disp(
                code, len, value, 2, &value_offset, &value_base) ||
            !x86_64_modrm_end(code, len, value + 2, &value_end) ||
            value_offset != 0 || value_base != guard_reg ||
            !x86_64_musl_gap_safe(
                code, ready, value, guard_reg, 0))
            continue;
        value_reg = ((code[value + 2] >> 3) & 7) |
                    ((value_rex & 4) ? 8 : 0);

        size_t tp_limit = value_end + 32 < len ? value_end + 32 : len;
        for (size_t tp = value_end; tp + 9 <= tp_limit; tp++) {
            uint8_t tp_rex;
            unsigned int tp_reg;

            if (code[tp] != 0x64 || (code[tp + 1] & 0xf8) != 0x48 ||
                code[tp + 2] != 0x8b ||
                (code[tp + 3] & 0xc7) != 0x04 || code[tp + 4] != 0x25 ||
                read_u32_le(code + tp + 5) != 0 ||
                !x86_64_musl_gap_safe(
                    code, value_end, tp, value_reg, 0))
                continue;
            tp_rex = code[tp + 1];
            tp_reg = ((code[tp + 3] >> 3) & 7) |
                     ((tp_rex & 4) ? 8 : 0);
            if (tp_reg == value_reg)
                continue;

            size_t store_begin = tp + 9;
            size_t store_limit =
                store_begin + 40 < len ? store_begin + 40 : len;
            for (size_t store = store_begin;
                 store + 3 <= store_limit; store++) {
                uint8_t store_rex = code[store];
                size_t off;
                size_t store_end;
                unsigned int base;
                unsigned int source;

                if ((store_rex & 0xf8) != 0x48 ||
                    code[store + 1] != 0x89 ||
                    !decode_x86_64_mem_disp(
                        code, len, store, 2, &off, &base) ||
                    !x86_64_modrm_end(
                        code, len, store + 2, &store_end) ||
                    base != tp_reg)
                    continue;
                source = ((code[store + 2] >> 3) & 7) |
                         ((store_rex & 4) ? 8 : 0);
                if (source != value_reg ||
                    !x86_64_musl_gap_safe(
                        code, store_begin, store, value_reg, 0) ||
                    !x86_64_musl_gap_safe(
                        code, store_begin, store, tp_reg, 0))
                    continue;
                (void)store_end;
                if (*have_match && *matched_offset != off)
                    return -1;
                *matched_offset = off;
                *have_match = 1;
            }
        }
    }
    return 0;
}

static int x86_64_forward_conditional_branch(
    const uint8_t *code, size_t len, size_t offset,
    size_t *end_out, size_t *target_out)
{
    size_t end;
    int64_t displacement;

    if (offset >= len)
        return 0;
    if (code[offset] >= 0x70 && code[offset] <= 0x7f) {
        if (offset + 2 > len)
            return 0;
        end = offset + 2;
        displacement = (int8_t)code[offset + 1];
    } else if (offset + 6 <= len && code[offset] == 0x0f &&
               code[offset + 1] >= 0x80 && code[offset + 1] <= 0x8f) {
        end = offset + 6;
        displacement = read_i32_le(code + offset + 2);
    } else {
        return 0;
    }
    if (displacement <= 0 || (uint64_t)displacement >= len - end)
        return 0;
    *end_out = end;
    *target_out = end + (size_t)displacement;
    return 1;
}

static int x86_64_forward_unconditional_branch(
    const uint8_t *code, size_t len, size_t offset,
    size_t *end_out, size_t *target_out)
{
    size_t end;
    int64_t displacement;

    if (offset >= len)
        return 0;
    if (code[offset] == 0xeb) {
        if (offset + 2 > len)
            return 0;
        end = offset + 2;
        displacement = (int8_t)code[offset + 1];
    } else if (code[offset] == 0xe9) {
        if (offset + 5 > len)
            return 0;
        end = offset + 5;
        displacement = read_i32_le(code + offset + 1);
    } else {
        return 0;
    }
    if (displacement <= 0 || (uint64_t)displacement >= len - end)
        return 0;
    *end_out = end;
    *target_out = end + (size_t)displacement;
    return 1;
}

/* Older compiler builds express init_ssp as an entropy-copy arm and an
 * address-derived fallback arm which converge before copying the guard into
 * the initial TCB.  Prove that small CFG explicitly; accepting either arm
 * in isolation would let unrelated basic blocks manufacture a field match.
 * Return -1 for an ambiguous contract, 0 for no match, and 1 for one match. */
static int x86_64_musl_branched_guard_initialization(
    const struct loaded_obj *obj, const uint8_t *code, size_t len,
    size_t begin, unsigned int guard_reg, size_t *offset_out)
{
    size_t matched_offset = 0;
    unsigned int matches = 0;

    if (!x86_64_musl_callee_saved(guard_reg))
        return 0;
    for (size_t branch = begin; branch + 2 <= len; branch++) {
        size_t branch_end;
        size_t fallback;

        if (!x86_64_forward_conditional_branch(
                code, len, branch, &branch_end, &fallback) ||
            !x86_64_musl_gap_safe(
                code, begin, branch, guard_reg, 0))
            continue;
        for (size_t call = branch_end; call + 5 <= fallback; call++) {
            uintptr_t call_target;

            if (code[call] != 0xe8 ||
                !x86_64_musl_gap_safe(
                    code, branch_end, call, guard_reg, 0) ||
                !x86_64_direct_call_target(
                    code, len, call, &call_target) ||
                !musl_target_executable_address(obj, call_target, 1))
                continue;
            for (size_t jump = call + 5;
                 jump + 2 <= fallback; jump++) {
                size_t jump_end;
                size_t join;
                uint8_t rex;
                uint8_t modrm;
                unsigned int fallback_guard;
                unsigned int value_reg;
                size_t multiply_end;

                if (!x86_64_forward_unconditional_branch(
                        code, len, jump, &jump_end, &join) ||
                    jump_end != fallback || join <= fallback ||
                    !x86_64_musl_gap_safe(
                        code, call + 5, jump, guard_reg, 0) ||
                    fallback + 7 > join)
                    continue;

                rex = code[fallback];
                modrm = code[fallback + 2];
                if ((rex & 0xf8) != 0x48 ||
                    code[fallback + 1] != 0x69 ||
                    (modrm >> 6) != 3 ||
                    (uint32_t)read_i32_le(code + fallback + 3) !=
                        UINT32_C(1103515245))
                    continue;
                fallback_guard =
                    (modrm & 7) | ((rex & 1) ? 8 : 0);
                value_reg =
                    ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);
                if (fallback_guard != guard_reg ||
                    value_reg == guard_reg)
                    continue;
                multiply_end = fallback + 7;

                for (size_t store = multiply_end;
                     store + 3 <= join; store++) {
                    uint8_t store_rex = code[store];
                    size_t store_end;
                    size_t store_offset;
                    unsigned int store_base;
                    unsigned int store_source;
                    size_t candidate_offset = 0;
                    int have_candidate = 0;

                    if ((store_rex & 0xf8) != 0x48 ||
                        code[store + 1] != 0x89 ||
                        !decode_x86_64_mem_disp(
                            code, join, store, 2,
                            &store_offset, &store_base) ||
                        !x86_64_modrm_end(
                            code, join, store + 2, &store_end) ||
                        store_offset != 0 || store_base != guard_reg ||
                        !x86_64_musl_gap_safe(
                            code, multiply_end, store,
                            guard_reg, 0))
                        continue;
                    store_source =
                        ((code[store + 2] >> 3) & 7) |
                        ((store_rex & 4) ? 8 : 0);
                    if (store_source != value_reg ||
                        !x86_64_musl_gap_safe(
                            code, store_end, join, guard_reg, 0))
                        continue;
                    if (x86_64_musl_guard_copy_chain(
                            code, len, join, guard_reg,
                            &candidate_offset, &have_candidate) < 0)
                        return -1;
                    if (!have_candidate)
                        continue;
                    if (matches != 0)
                        return -1;
                    matched_offset = candidate_offset;
                    matches++;
                }
            }
        }
    }
    if (matches != 1)
        return 0;
    *offset_out = matched_offset;
    return 1;
}

/* Some compilers put the fallback arm after the return and jump backwards
 * to the common TCB store. Both arms must produce the same value register,
 * from the same relocation-proven guard, at that exact instruction boundary. */
static int x86_64_musl_backward_guard_join(
    const struct loaded_obj *obj, const uint8_t *code, size_t len,
    const struct x86_64_musl_guard_load *loads, size_t count,
    size_t fallback, size_t store_end, unsigned int value_reg,
    size_t *matched_offset, int *have_match)
{
    size_t jump_end;
    int64_t displacement;
    size_t join;

    if (store_end + 2 > len)
        return 0;
    if (code[store_end] == 0xeb) {
        jump_end = store_end + 2;
        displacement = (int8_t)code[store_end + 1];
    } else if (code[store_end] == 0xe9 && store_end + 5 <= len) {
        jump_end = store_end + 5;
        displacement = read_i32_le(code + store_end + 1);
    } else {
        return 0;
    }
    if (displacement >= 0 || (uint64_t)-displacement > jump_end)
        return 0;
    join = jump_end - (size_t)-displacement;
    if (join >= fallback)
        return 0;
    for (size_t g = 0; g < count; g++) {
        size_t begin = loads[g].end;
        int branch_found = 0;

        if (begin < 7 || begin >= join ||
            !x86_64_musl_callee_saved(loads[g].reg))
            continue;
        for (size_t b = 0; b + 2 <= begin - 7; b++) {
            size_t end, target;

            if (x86_64_forward_conditional_branch(
                    code, len, b, &end, &target) && target == fallback &&
                end == begin - 7)
                branch_found = 1;
        }
        if (!branch_found)
            continue;
        for (size_t v = begin; v + 3 <= join; v++) {
            size_t offset, end;
            unsigned int base, destination;

            if ((code[v] & 0xf8) != 0x48 || code[v + 1] != 0x8b ||
                !decode_x86_64_mem_disp(code, len, v, 2, &offset, &base) ||
                !x86_64_modrm_end(code, len, v + 2, &end) ||
                end != join || offset != 0 || base != loads[g].reg)
                continue;
            destination = ((code[v + 2] >> 3) & 7) |
                          ((code[v] & 4) ? 8 : 0);
            /* This arm must cross the entropy-copy call, not merely keep
             * the address live without ever initializing the guard. */
            if (destination != value_reg ||
                x86_64_musl_gap_safe(code, begin, v, loads[g].reg, 0) ||
                !x86_64_musl_guard_reaches_clear(
                    obj, code, len, begin, loads[g].reg, v))
                continue;
            if (x86_64_musl_guard_copy_chain(
                    code, len, v, loads[g].reg,
                    matched_offset, have_match) < 0)
                return -1;
        }
    }
    return 0;
}

static int decode_x86_64_musl_init_ssp_canary(
    const struct loaded_obj *obj, uintptr_t address, size_t *offset_out)
{
    const uint8_t *code = (const uint8_t *)address;
    const Elf64_Sym *guard = lookup_linear(obj, "__stack_chk_guard");
    void *guard_address;
    struct x86_64_musl_guard_load guard_loads[32];
    size_t guard_load_count = 0;
    size_t matched_offset = 0;
    int have_match = 0;

    if (!guard || ELF64_ST_TYPE(guard->st_info) != STT_OBJECT ||
        guard->st_size != sizeof(uintptr_t) ||
        guard->st_shndx == SHN_UNDEF || guard->st_shndx >= SHN_LORESERVE ||
        !loaded_obj_vaddr_pointer(obj, guard->st_value,
                                  sizeof(uintptr_t), PF_W,
                                  &guard_address) ||
        !musl_target_executable_address(obj, address, 160))
        return 0;
    (void)guard_address;

    for (size_t i = 0; i + 7 <= 160; i++) {
        uint8_t rex = code[i];
        uint8_t modrm;
        uintptr_t slot;
        unsigned int reg;

        if ((rex & 0xf8) != 0x48 || code[i + 1] != 0x8b)
            continue;
        modrm = code[i + 2];
        if ((modrm & 0xc7) != 0x05)
            continue;
        slot = (uintptr_t)(code + i + 7) +
               (intptr_t)read_i32_le(code + i + 3);
        if (!musl_got_slot_relocates_to_symbol(obj, slot, guard))
            continue;
        reg = ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);
        if (guard_load_count ==
            sizeof(guard_loads) / sizeof(guard_loads[0]))
            return 0;
        guard_loads[guard_load_count++] =
            (struct x86_64_musl_guard_load){ i + 7, reg };
    }
    if (!guard_load_count)
        return 0;

    /* Modern musl clears byte one before loading the value copied to the
     * TCB.  Require that order on a single proven execution path. */
    for (size_t g = 0; g < guard_load_count; g++) {
        size_t begin = guard_loads[g].end;
        size_t limit = begin + 96 < 160 ? begin + 96 : 160;

        for (size_t i = begin; i + 4 <= limit; i++) {
            size_t clear = i;
            size_t clear_end;
            uint8_t clear_rex = 0;
            uint8_t modrm;
            unsigned int guard_reg;

            if ((code[clear] & 0xf0) == 0x40)
                clear_rex = code[clear++];
            if (clear + 4 > limit || code[clear] != 0xc6)
                continue;
            modrm = code[clear + 1];
            guard_reg = (modrm & 7) | ((clear_rex & 1) ? 8 : 0);
            clear_end = clear + 4;
            if ((modrm >> 6) != 1 || ((modrm >> 3) & 7) != 0 ||
                code[clear + 2] != 1 || code[clear + 3] != 0 ||
                guard_reg != guard_loads[g].reg ||
                !x86_64_musl_guard_reaches_clear(
                    obj, code, 160, guard_loads[g].end,
                    guard_reg, i))
                continue;
            if (x86_64_musl_guard_copy_chain(
                    code, 160, clear_end, guard_reg,
                    &matched_offset, &have_match) < 0)
                return 0;
        }
    }

    /* musl 1.2.2 predates the cleared-byte hardening.  Admit its fallback
     * initialization only when the target code itself proves the distinctive
     * `guard = &guard * 1103515245` data flow: an exact three-operand IMUL
     * from a relocation-proven guard address followed by a store of that
     * result back through the same address register, followed by the ordered
     * copy chain.  This is structural evidence, not a release exception. */
    for (size_t g = 0; g < guard_load_count; g++) {
        size_t begin = guard_loads[g].end;
        size_t limit = begin + 48 < 160 ? begin + 48 : 160;
        size_t branched_offset;
        int branched = x86_64_musl_branched_guard_initialization(
            obj, code, 160, begin, guard_loads[g].reg,
            &branched_offset);

        if (branched < 0)
            return 0;
        if (branched > 0) {
            if (have_match && matched_offset != branched_offset)
                return 0;
            matched_offset = branched_offset;
            have_match = 1;
        }

        for (size_t i = begin; i + 7 <= limit; i++) {
            uint8_t rex = code[i];
            uint8_t modrm;
            unsigned int guard_reg;
            unsigned int value_reg;

            if ((rex & 0xf8) != 0x48 || code[i + 1] != 0x69 ||
                !x86_64_musl_gap_safe(
                    code, begin, i, guard_loads[g].reg, 0))
                continue;
            modrm = code[i + 2];
            if ((modrm >> 6) != 3 ||
                (uint32_t)read_i32_le(code + i + 3) !=
                    UINT32_C(1103515245))
                continue;
            guard_reg = (modrm & 7) | ((rex & 1) ? 8 : 0);
            value_reg = ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);
            if (guard_reg != guard_loads[g].reg)
                continue;

            for (size_t j = i + 7;
                 j + 3 <= 160 && j <= i + 23; j++) {
                size_t off;
                size_t store_end;
                unsigned int base;
                uint8_t store_rex = code[j];
                unsigned int source;

                if ((store_rex & 0xf8) != 0x48 ||
                    code[j + 1] != 0x89 ||
                    !decode_x86_64_mem_disp(
                        code, 160, j, 2, &off, &base) ||
                    !x86_64_modrm_end(
                        code, 160, j + 2, &store_end) || off != 0 ||
                    base != guard_reg ||
                    !x86_64_musl_gap_safe(
                        code, i + 7, j, guard_reg, 0) ||
                    !x86_64_musl_gap_safe(
                        code, i + 7, j, value_reg, 0))
                    continue;
                source = ((code[j + 2] >> 3) & 7) |
                         ((store_rex & 4) ? 8 : 0);
                if (source != value_reg)
                    continue;
                if (x86_64_musl_backward_guard_join(
                        obj, code, 160, guard_loads, guard_load_count,
                        guard_loads[g].end - 7, store_end, value_reg,
                        &matched_offset, &have_match) < 0)
                    return 0;
                if (x86_64_musl_guard_copy_chain(
                        code, 160, store_end, guard_reg,
                        &matched_offset, &have_match) < 0)
                    return 0;
            }
        }
    }
    if (have_match) {
        *offset_out = matched_offset;
        return 1;
    }
    return 0;
}

static int decode_x86_64_musl_init_libc(
    const struct loaded_obj *obj, uintptr_t *init_out, size_t *canary_out)
{
    const uint8_t *start;
    size_t start_len;
    uintptr_t init = 0;
    unsigned int start_calls = 0;

    if (!musl_defined_function_view(obj, "__libc_start_main", 16, 160,
                                    &start, &start_len)) {
        ldr_dbg("[loader] musl contract: no bounded __libc_start_main\n");
        return 0;
    }
    for (size_t i = 0; i + 5 <= start_len; i++) {
        uintptr_t target;

        if (!x86_64_direct_call_target(start, start_len, i, &target))
            continue;
        if (!musl_target_executable_address(obj, target, 1))
            continue;
        init = target;
        start_calls++;
        i += 4;
    }
    if (start_calls != 1 || !musl_target_executable_address(obj, init, 640)) {
        ldr_dbg_hex("[loader] musl contract: startup call count=",
                    start_calls);
        return 0;
    }

    const uint8_t *code = (const uint8_t *)init;
    uintptr_t init_tls = 0;
    uintptr_t init_ssp = 0;
    size_t init_tls_call = 0;
    unsigned int no_op_calls = 0;

    for (size_t i = 0; i + 5 <= 640; i++) {
        uintptr_t target;

        if (!x86_64_direct_call_target(code, 640, i, &target))
            continue;
        if (!musl_target_executable_address(obj, target, 1))
            continue;
        if (x86_64_exact_return_stub(obj, target)) {
            init_tls = target;
            init_tls_call = i;
            no_op_calls++;
        } else if (init_tls && i > init_tls_call &&
                   i - init_tls_call <= 48 && !init_ssp) {
            init_ssp = target;
            break;
        }
        i += 4;
    }
    if (no_op_calls != 1 || !init_tls || !init_ssp) {
        ldr_dbg_hex("[loader] musl contract: init_tls candidates=",
                    no_op_calls);
        return 0;
    }
    ldr_dbg_hex("[loader] musl contract: init_libc=", init);
    ldr_dbg_hex("[loader] musl contract: init_tls=", init_tls);
    ldr_dbg_hex("[loader] musl contract: init_ssp=", init_ssp);
    if (!decode_x86_64_musl_init_ssp_canary(
            obj, init_ssp, canary_out)) {
        ldr_dbg("[loader] musl contract: SSP canary decoder failed\n");
        return 0;
    }
    *init_out = init;
    return 1;
}
#elif defined(__aarch64__)
static int aarch64_direct_call_target(const uint8_t *code, size_t length,
                                      size_t offset, uintptr_t *target_out)
{
    uint32_t instruction;
    int64_t displacement;

    if (offset + 4 > length || (offset & 3) != 0)
        return 0;
    instruction = read_u32_le(code + offset);
    if ((instruction & 0xfc000000u) != 0x94000000u)
        return 0;
    displacement = (int64_t)(instruction & 0x03ffffffu);
    if (displacement & 0x02000000)
        displacement -= 0x04000000;
    displacement <<= 2;
    *target_out = (uintptr_t)((int64_t)(uintptr_t)(code + offset) +
                              displacement);
    return 1;
}

static int aarch64_exact_return_stub(const struct loaded_obj *obj,
                                     uintptr_t address)
{
    const uint8_t *code = (const uint8_t *)address;
    size_t offset = 0;

    if (!musl_target_executable_address(obj, address, 8))
        return 0;
    if (read_u32_le(code) == 0xd503245fu) /* BTI c */
        offset = 4;
    if (read_u32_le(code + offset) == 0xd65f03c0u)
        return 1;

    /* A frame-pointer-preserving compiler can give even this empty stub
     * a balanced frame and pointer authentication.  Admit only the exact
     * save/restore sequence, with a matching authentication key. */
    if (!musl_target_executable_address(obj, address, offset + 24))
        return 0;
    uint32_t authentication = 0;
    uint32_t first = read_u32_le(code + offset);
    if (first == 0xd503233fu || first == 0xd503237fu) {
        authentication = first + 0x80; /* PACIASP/BSP -> AUTIASP/BSP */
        offset += 4;
    }
    if (read_u32_le(code + offset) != 0xa9bf7bfdu ||
        read_u32_le(code + offset + 4) != 0x910003fdu ||
        read_u32_le(code + offset + 8) != 0xa8c17bfdu)
        return 0;
    offset += 12;
    if (authentication) {
        if (read_u32_le(code + offset) != authentication)
            return 0;
        offset += 4;
    }
    return read_u32_le(code + offset) == 0xd65f03c0u;
}

struct aarch64_musl_guard_load {
    size_t end;
    unsigned int reg;
};

static int aarch64_musl_guard_copy_chain(
    const uint8_t *code, size_t len, size_t path_begin, size_t ready,
    unsigned int guard_reg, size_t self_delta,
    size_t *matched_offset, int *have_match)
{
    size_t value_limit = ready + 32 < len ? ready + 32 : len;

    for (size_t value = ready; value + 4 <= value_limit; value += 4) {
        unsigned int value_reg;
        unsigned int base_reg;
        size_t value_offset;

        if (!aarch64_decode_ldrstr64_unsigned(
                read_u32_le(code + value), 1, &value_reg,
                &base_reg, &value_offset) || value_offset != 0 ||
            base_reg != guard_reg ||
            !aarch64_musl_no_control_flow(code, ready, value) ||
            !aarch64_musl_registers_preserved(
                code, ready, value, UINT32_C(1) << guard_reg))
            continue;

        size_t tp_limit = value + 20 < len ? value + 20 : len;
        for (size_t tp = path_begin;
             tp + 4 <= tp_limit; tp += 4) {
            int tp_reg;

            if (!aarch64_is_mrs_tpidr_el0(
                    read_u32_le(code + tp), &tp_reg) ||
                (unsigned int)tp_reg == guard_reg ||
                (unsigned int)tp_reg == value_reg)
                continue;
            size_t store_begin = value + 4;
            if (tp + 4 > store_begin)
                store_begin = tp + 4;
            size_t store_limit =
                store_begin + 32 < len ? store_begin + 32 : len;
            for (size_t store_pos = store_begin;
                 store_pos + 4 <= store_limit; store_pos += 4) {
                uint32_t store = read_u32_le(code + store_pos);
                int64_t relative;
                size_t candidate;
                if ((store & 0xffe00c00u) != 0xf8000000u ||
                    (int)((store >> 5) & 0x1f) != tp_reg ||
                    (store & 0x1f) != value_reg ||
                    !aarch64_musl_no_control_flow(
                        code, value + 4, store_pos) ||
                    !aarch64_musl_no_control_flow(
                        code, tp + 4, store_pos) ||
                    !aarch64_musl_registers_preserved(
                        code, value + 4, store_pos,
                        UINT32_C(1) << value_reg) ||
                    !aarch64_musl_registers_preserved(
                        code, tp + 4, store_pos,
                        UINT32_C(1) << (unsigned int)tp_reg))
                    continue;
                relative = (store >> 12) & 0x1ff;
                if (relative & 0x100)
                    relative -= 0x200;
                if ((int64_t)self_delta + relative < 0 ||
                    (int64_t)self_delta + relative >=
                        MUSL_THREAD_PROBE_LIMIT)
                    return -1;
                candidate =
                    (size_t)((int64_t)self_delta + relative);
                if (*have_match && *matched_offset != candidate)
                    return -1;
                *matched_offset = candidate;
                *have_match = 1;
            }
        }
    }
    return 0;
}

/* Some compiler builds place one relocation-proven GOT-page calculation
 * before init_ssp's entropy test, then load __stack_chk_guard separately in
 * the seeded and address-derived fallback arms.  The fallback lives after
 * the return and branches backward to the seeded arm's guard-to-TCB copy.
 * Prove that entire small CFG instead of relaxing the linear ADRP-to-LDR
 * rule: both arms and the join must use the same relocated slot, the page
 * base must survive exactly one ABI call, and both arms must converge at the
 * same ordered copy chain.  Return -1 for ambiguity, 0 for no match, and 1
 * for exactly one structural match. */
static int aarch64_musl_branched_guard_initialization(
    const struct loaded_obj *obj, const uint8_t *code, size_t len,
    const Elf64_Sym *guard, size_t self_delta, size_t *offset_out)
{
    size_t matched_offset = 0;
    unsigned int matches = 0;

    if (len < 24)
        return 0;
    for (size_t adrp = 0; adrp + 4 <= len; adrp += 4) {
        unsigned int page_reg;
        uintptr_t page;

        if (!aarch64_decode_musl_adrp(
                (uintptr_t)(code + adrp), read_u32_le(code + adrp),
                &page_reg, &page) || page_reg < 19 || page_reg > 28)
            continue;

        size_t branch_limit = adrp + 32 < len ? adrp + 32 : len;
        for (size_t branch = adrp + 4;
             branch + 4 <= branch_limit; branch += 4) {
            uint32_t branch_insn = read_u32_le(code + branch);
            int64_t fallback_signed;
            size_t fallback;
            size_t call = 0;
            uintptr_t call_target = 0;
            unsigned int call_count = 0;
            size_t seed_load;
            size_t join;
            unsigned int seed_reg;
            unsigned int seed_base;
            size_t got_offset;
            uintptr_t slot;
            unsigned int join_reg;
            unsigned int join_base;
            size_t join_offset;
            unsigned int fallback_reg;
            unsigned int fallback_base;
            size_t fallback_offset;
            uint32_t movz;
            uint32_t movk;
            unsigned int constant_reg;
            uint32_t multiply;
            unsigned int result_reg;
            unsigned int left_reg;
            unsigned int right_reg;
            unsigned int store_reg;
            unsigned int store_base;
            size_t store_offset;
            int64_t fallback_join;
            size_t candidate_offset = 0;
            int have_candidate = 0;

            /* init_ssp's entropy input is a pointer in X0.  Requiring the
             * 64-bit CBZ excludes unrelated compare-and-branch CFGs. */
            if ((branch_insn & 0xff00001fu) != 0xb4000000u ||
                !aarch64_cbz_branch(
                    branch, branch_insn, 0, &fallback_signed) ||
                fallback_signed <= (int64_t)branch ||
                (uint64_t)fallback_signed > len - 24 ||
                !aarch64_musl_no_control_flow(code, 0, branch) ||
                !aarch64_musl_registers_preserved(
                    code, 0, branch, UINT32_C(1)) ||
                !aarch64_musl_no_control_flow(
                    code, adrp + 4, branch) ||
                !aarch64_musl_registers_preserved(
                    code, adrp + 4, branch,
                    UINT32_C(1) << page_reg))
                continue;
            fallback = (size_t)fallback_signed;

            for (size_t pos = branch + 4;
                 pos + 4 <= fallback; pos += 4) {
                uintptr_t target;

                if (!aarch64_direct_call_target(
                        code, len, pos, &target))
                    continue;
                call = pos;
                call_target = target;
                call_count++;
            }
            if (call_count != 1 || call < branch + 8 ||
                !musl_target_executable_address(
                    obj, call_target, 1))
                continue;
            seed_load = call - 4;
            join = call + 4;
            if (join >= fallback || fallback < 4 ||
                read_u32_le(code + fallback - 4) != 0xd65f03c0u ||
                !aarch64_musl_no_control_flow(
                    code, branch + 4, seed_load) ||
                !aarch64_musl_registers_preserved(
                    code, branch + 4, seed_load,
                    UINT32_C(1) << page_reg) ||
                !aarch64_decode_ldrstr64_unsigned(
                    read_u32_le(code + seed_load), 1,
                    &seed_reg, &seed_base, &got_offset) ||
                seed_reg != 0 || seed_base != page_reg ||
                page > UINTPTR_MAX - got_offset)
                continue;
            slot = page + got_offset;
            if (!musl_got_slot_relocates_to_symbol(obj, slot, guard) ||
                !aarch64_decode_ldrstr64_unsigned(
                    read_u32_le(code + join), 1,
                    &join_reg, &join_base, &join_offset) ||
                join_reg != page_reg || join_base != page_reg ||
                join_offset != got_offset ||
                !aarch64_decode_ldrstr64_unsigned(
                    read_u32_le(code + fallback), 1,
                    &fallback_reg, &fallback_base, &fallback_offset) ||
                fallback_reg != 0 || fallback_base != page_reg ||
                fallback_offset != got_offset)
                continue;

            movz = read_u32_le(code + fallback + 4);
            movk = read_u32_le(code + fallback + 8);
            if ((movz & 0xff800000u) != 0xd2800000u ||
                ((movz >> 21) & 3) != 0 ||
                ((movz >> 5) & 0xffff) != 0x4e6d ||
                (movk & 0xff800000u) != 0xf2800000u ||
                ((movk >> 21) & 3) != 1 ||
                ((movk >> 5) & 0xffff) != 0x41c6 ||
                (movz & 0x1f) != (movk & 0x1f))
                continue;
            constant_reg = movz & 0x1f;
            if (constant_reg == 31 || constant_reg == fallback_reg ||
                constant_reg == page_reg)
                continue;

            multiply = read_u32_le(code + fallback + 12);
            if ((multiply & 0xffe0fc00u) != 0x9b007c00u)
                continue;
            result_reg = multiply & 0x1f;
            left_reg = (multiply >> 5) & 0x1f;
            right_reg = (multiply >> 16) & 0x1f;
            if (!((left_reg == constant_reg &&
                   right_reg == fallback_reg) ||
                  (right_reg == constant_reg &&
                   left_reg == fallback_reg)) ||
                result_reg == fallback_reg || result_reg == page_reg)
                continue;

            if (!aarch64_decode_ldrstr64_unsigned(
                    read_u32_le(code + fallback + 16), 0,
                    &store_reg, &store_base, &store_offset) ||
                store_reg != result_reg || store_base != fallback_reg ||
                store_offset != 0 ||
                !aarch64_unconditional_branch(
                    fallback + 20,
                    read_u32_le(code + fallback + 20),
                    &fallback_join) ||
                fallback_join != (int64_t)join ||
                fallback_join >= (int64_t)fallback)
                continue;

            if (aarch64_musl_guard_copy_chain(
                    code, len, join + 4, join + 4, page_reg,
                    self_delta, &candidate_offset,
                    &have_candidate) < 0)
                return -1;
            if (!have_candidate)
                continue;
            if (matches != 0)
                return -1;
            matched_offset = candidate_offset;
            matches++;
        }
    }
    if (matches != 1)
        return 0;
    *offset_out = matched_offset;
    return 1;
}

static int aarch64_musl_fallback_value_to_tcb(
    const uint8_t *code, size_t len, size_t ready, unsigned int value_reg,
    size_t self_delta, size_t *matched_offset, int *have_match)
{
    for (size_t tp = ready; tp + 4 <= len && tp <= ready + 32; tp += 4) {
        int tp_reg;

        if (!aarch64_is_mrs_tpidr_el0(read_u32_le(code + tp), &tp_reg) ||
            (unsigned int)tp_reg == value_reg)
            continue;
        for (size_t pos = tp + 4; pos + 4 <= len && pos <= tp + 32; pos += 4) {
            uint32_t store = read_u32_le(code + pos);
            int64_t relative;
            size_t candidate;

            if ((store & 0xffe00c00u) != 0xf8000000u ||
                ((store >> 5) & 31) != (unsigned int)tp_reg ||
                (store & 31) != value_reg ||
                !aarch64_musl_no_control_flow(code, ready, pos) ||
                !aarch64_musl_registers_preserved(
                    code, ready, pos, UINT32_C(1) << value_reg) ||
                !aarch64_musl_registers_preserved(
                    code, tp + 4, pos, UINT32_C(1) << (unsigned int)tp_reg))
                continue;
            relative = (store >> 12) & 0x1ff;
            if (relative & 0x100)
                relative -= 0x200;
            if ((int64_t)self_delta + relative < 0 ||
                (int64_t)self_delta + relative >= MUSL_THREAD_PROBE_LIMIT)
                return -1;
            candidate = (size_t)((int64_t)self_delta + relative);
            if (*have_match && *matched_offset != candidate)
                return -1;
            *matched_offset = candidate;
            *have_match = 1;
        }
    }
    return 0;
}

static int decode_aarch64_musl_init_ssp_canary(
    const struct loaded_obj *obj, uintptr_t address, size_t self_delta,
    size_t *offset_out)
{
    const uint8_t *code = (const uint8_t *)address;
    const Elf64_Sym *guard = lookup_linear(obj, "__stack_chk_guard");
    void *guard_address;
    struct aarch64_musl_guard_load guard_loads[32];
    size_t guard_load_count = 0;
    size_t matched_offset = 0;
    int have_match = 0;

    if (!guard || ELF64_ST_TYPE(guard->st_info) != STT_OBJECT ||
        guard->st_size != sizeof(uintptr_t) ||
        guard->st_shndx == SHN_UNDEF || guard->st_shndx >= SHN_LORESERVE ||
        !loaded_obj_vaddr_pointer(obj, guard->st_value,
                                  sizeof(uintptr_t), PF_W,
                                  &guard_address) ||
        !musl_target_executable_address(obj, address, 160))
        return 0;
    (void)guard_address;

    {
        size_t branched_offset;
        int branched = aarch64_musl_branched_guard_initialization(
            obj, code, 160, guard, self_delta, &branched_offset);

        if (branched < 0)
            return 0;
        if (branched > 0) {
            matched_offset = branched_offset;
            have_match = 1;
        }
    }

    for (size_t i = 0; i + 4 <= 160; i += 4) {
        unsigned int page_reg;
        uintptr_t page;

        if (!aarch64_decode_musl_adrp((uintptr_t)(code + i),
                                      read_u32_le(code + i),
                                      &page_reg, &page))
            continue;
        for (size_t j = i + 4;
             j + 4 <= 160 && j <= i + 64; j += 4) {
            unsigned int target_reg;
            unsigned int base_reg;
            size_t got_offset;
            uintptr_t slot;

            if (!aarch64_decode_ldrstr64_unsigned(
                    read_u32_le(code + j), 1, &target_reg,
                    &base_reg, &got_offset) || base_reg != page_reg ||
                page > UINTPTR_MAX - got_offset ||
                !aarch64_musl_no_control_flow(code, i + 4, j) ||
                !aarch64_musl_registers_preserved(
                    code, i + 4, j, UINT32_C(1) << page_reg))
                continue;
            slot = page + got_offset;
            if (!musl_got_slot_relocates_to_symbol(obj, slot, guard))
                continue;
            int duplicate = 0;
            for (size_t k = 0; k < guard_load_count; k++)
                if (guard_loads[k].end == j + 4 &&
                    guard_loads[k].reg == target_reg)
                    duplicate = 1;
            if (duplicate)
                continue;
            if (guard_load_count ==
                sizeof(guard_loads) / sizeof(guard_loads[0]))
                return 0;
            guard_loads[guard_load_count++] =
                (struct aarch64_musl_guard_load){ j + 4, target_reg };
        }
    }
    if (!guard_load_count && !have_match)
        return 0;

    for (size_t g = 0; g < guard_load_count; g++) {
        size_t begin = guard_loads[g].end;
        size_t limit = begin + 64 < 160 ? begin + 64 : 160;

        for (size_t i = begin; i + 4 <= limit; i += 4) {
            uint32_t clear = read_u32_le(code + i);
            unsigned int guard_reg;

            if ((clear & 0xffc0001fu) != 0x3900001fu ||
                ((clear >> 10) & 0xfff) != 1)
                continue;
            guard_reg = (clear >> 5) & 0x1f;
            if (guard_reg != guard_loads[g].reg ||
                !aarch64_musl_no_control_flow(code, begin, i) ||
                !aarch64_musl_registers_preserved(
                    code, begin, i, UINT32_C(1) << guard_reg))
                continue;
            if (aarch64_musl_guard_copy_chain(
                    code, 160, begin, i + 4, guard_reg,
                    self_delta, &matched_offset, &have_match) < 0)
                return 0;
        }
    }

    /* musl 1.2.2 has no cleared-byte store.  Prove its fallback assignment
     * from the exact 1103515245 constant materialization, multiply by a
     * relocation-proven guard address, and store back through that address.
     * The multiply, store, and subsequent TCB copy must be one ordered,
     * register-preserving path. */
    for (size_t g = 0; g < guard_load_count; g++) {
        size_t begin = guard_loads[g].end;
        size_t limit = begin + 48 < 160 ? begin + 48 : 160;

        /* Constant materialization may precede the scheduled GOT load. */
        size_t constant_begin = begin >= 12 ? begin - 12 : 0;
        for (size_t i = constant_begin; i + 8 <= limit; i += 4) {
            uint32_t movz = read_u32_le(code + i);
            uint32_t movk = read_u32_le(code + i + 4);
            unsigned int constant_reg;

            if ((movz & 0xff800000u) != 0xd2800000u ||
                ((movz >> 21) & 3) != 0 ||
                ((movz >> 5) & 0xffff) != 0x4e6d ||
                (movk & 0xff800000u) != 0xf2800000u ||
                ((movk >> 21) & 3) != 1 ||
                ((movk >> 5) & 0xffff) != 0x41c6 ||
                (movz & 0x1f) != (movk & 0x1f))
                continue;
            constant_reg = movz & 0x1f;
            if (constant_reg == 31 ||
                constant_reg == guard_loads[g].reg)
                continue;

            for (size_t j = i + 8;
                 j + 4 <= 160 && j <= i + 24; j += 4) {
                uint32_t multiply = read_u32_le(code + j);
                unsigned int result_reg;
                unsigned int left_reg;
                unsigned int right_reg;

                if (j < begin ||
                    (multiply & 0xffe0fc00u) != 0x9b007c00u ||
                    !aarch64_musl_no_control_flow(
                        code, i < begin ? i : begin, j) ||
                    !aarch64_musl_registers_preserved(
                        code, i + 8, j, UINT32_C(1) << constant_reg) ||
                    !aarch64_musl_registers_preserved(
                        code, begin, j, UINT32_C(1) << guard_loads[g].reg))
                    continue;
                result_reg = multiply & 0x1f;
                left_reg = (multiply >> 5) & 0x1f;
                right_reg = (multiply >> 16) & 0x1f;
                if (!((left_reg == constant_reg &&
                       right_reg == guard_loads[g].reg) ||
                      (right_reg == constant_reg &&
                       left_reg == guard_loads[g].reg)) ||
                    result_reg == guard_loads[g].reg)
                    continue;

                for (size_t k = j + 4;
                     k + 4 <= 160 && k <= j + 16; k += 4) {
                    unsigned int value_reg;
                    unsigned int base_reg;
                    size_t value_offset;

                    if (!aarch64_decode_ldrstr64_unsigned(
                            read_u32_le(code + k), 0, &value_reg,
                            &base_reg, &value_offset) ||
                        value_reg != result_reg ||
                        base_reg != guard_loads[g].reg ||
                        value_offset != 0 ||
                        !aarch64_musl_no_control_flow(code, j + 4, k) ||
                        !aarch64_musl_registers_preserved(
                            code, j + 4, k,
                            (UINT32_C(1) << result_reg) |
                            (UINT32_C(1) << guard_loads[g].reg)))
                        continue;

                    /* The stored fallback value may be reused directly;
                     * it need not be loaded back from __stack_chk_guard. */
                    if (aarch64_musl_fallback_value_to_tcb(
                            code, 160, k + 4, result_reg, self_delta,
                            &matched_offset, &have_match) < 0)
                        return 0;
                    if (aarch64_musl_guard_copy_chain(
                            code, 160, k + 4, k + 4,
                            guard_loads[g].reg, self_delta,
                            &matched_offset, &have_match) < 0)
                        return 0;
                    for (size_t h = 0; h < guard_load_count; h++) {
                        if (guard_loads[h].end < k + 4)
                            continue;
                        if (aarch64_musl_guard_copy_chain(
                                code, 160, guard_loads[h].end,
                                guard_loads[h].end, guard_loads[h].reg,
                                self_delta, &matched_offset,
                                &have_match) < 0)
                            return 0;
                    }
                }
            }
        }
    }
    if (have_match) {
        *offset_out = matched_offset;
        return 1;
    }
    return 0;
}

static int decode_aarch64_musl_init_libc(
    const struct loaded_obj *obj, size_t self_delta, uintptr_t *init_out,
    size_t *canary_out)
{
    const uint8_t *start;
    size_t start_len;
    uintptr_t init = 0;
    unsigned int start_calls = 0;

    if (!musl_defined_function_view(obj, "__libc_start_main", 16, 160,
                                    &start, &start_len))
        return 0;
    for (size_t i = 0; i + 4 <= start_len; i += 4) {
        uintptr_t target;

        if (!aarch64_direct_call_target(start, start_len, i, &target))
            continue;
        if (!musl_target_executable_address(obj, target, 1))
            return 0;
        init = target;
        start_calls++;
    }
    if (start_calls != 1 || !musl_target_executable_address(obj, init, 768))
        return 0;

    const uint8_t *code = (const uint8_t *)init;
    uintptr_t init_tls = 0;
    uintptr_t init_ssp = 0;
    size_t init_tls_call = 0;
    unsigned int no_op_calls = 0;

    for (size_t i = 0; i + 4 <= 768; i += 4) {
        uintptr_t target;

        if (!aarch64_direct_call_target(code, 768, i, &target))
            continue;
        if (!musl_target_executable_address(obj, target, 1))
            return 0;
        if (aarch64_exact_return_stub(obj, target)) {
            init_tls = target;
            init_tls_call = i;
            no_op_calls++;
        } else if (init_tls && i > init_tls_call &&
                   i - init_tls_call <= 48 && !init_ssp) {
            init_ssp = target;
            break;
        }
    }
    if (no_op_calls != 1 || !init_tls || !init_ssp ||
        !decode_aarch64_musl_init_ssp_canary(
            obj, init_ssp, self_delta, canary_out))
        return 0;
    *init_out = init;
    return 1;
}
#endif

static uint32_t read_u32_le(const uint8_t *p)
{
    uint32_t v;

    memcpy(&v, p, sizeof(v));
    return v;
}

#define MUSL_PTHREAD_CLONE_FLAGS UINT32_C(0x7d0f00)

static int musl_target_writable_clear_tid(
    const struct loaded_obj *obj, uintptr_t address)
{
    void *checked;

    if ((address & (_Alignof(int) - 1)) != 0 || address < obj->base ||
        address - obj->base > INT64_MAX ||
        !loaded_obj_signed_offset_pointer(
            obj, (int64_t)(address - obj->base), sizeof(int), PF_W,
            &checked))
        return 0;
    return (uintptr_t)checked == address;
}

#if defined(__x86_64__)
static int read_i32_le(const uint8_t *p)
{
    return (int32_t)read_u32_le(p);
}

static int decode_x86_64_musl_errno_offset(const uint8_t *code, size_t len,
                                           size_t *off_out)
{
    for (size_t i = 0; i + 4 <= len; i++) {
        if (code[i] == 0x48 && code[i + 1] == 0x83 && code[i + 2] == 0xc0) {
            *off_out = code[i + 3];
            return *off_out < MUSL_THREAD_PROBE_LIMIT;
        }
        if (i + 6 <= len && code[i] == 0x48 && code[i + 1] == 0x05) {
            int off = read_i32_le(code + i + 2);

            if (off >= 0 && off < MUSL_THREAD_PROBE_LIMIT) {
                *off_out = (size_t)off;
                return 1;
            }
        }
    }
    return 0;
}

static int decode_x86_64_musl_self_delta(const uint8_t *code, size_t len,
                                         size_t *delta_out)
{
    for (size_t i = 0; i + 9 <= len; i++) {
        int displacement;

        if (code[i] != 0x64 || code[i + 1] != 0x48 ||
            code[i + 2] != 0x8b || (code[i + 3] & 0xc7) != 0x04 ||
            code[i + 4] != 0x25)
            continue;
        displacement = read_i32_le(code + i + 5);
        if (displacement > 0 || displacement <= -MUSL_THREAD_PROBE_LIMIT)
            return 0;
        *delta_out = (size_t)-displacement;
        return 1;
    }
    return 0;
}

static int decode_x86_64_musl_uselocale(const uint8_t *code, size_t len,
                                         size_t *locale_out,
                                         uintptr_t *global_out)
{
    size_t load_offset = SIZE_MAX;
    size_t store_offset = SIZE_MAX;
    uintptr_t global = 0;
    unsigned int global_count = 0;

    for (size_t i = 0; i + 7 <= len; i++) {
        if (code[i] == 0x48 && code[i + 1] == 0x8d &&
            (code[i + 2] & 0xc7) == 0x05) {
            uintptr_t target = (uintptr_t)(code + i + 7) +
                               (intptr_t)read_i32_le(code + i + 3);

            if (!global || global == target) {
                global = target;
                global_count++;
            }
        }

        size_t off;
        unsigned int base;

        if (code[i] == 0x48 && code[i + 1] == 0x8b &&
            decode_x86_64_mem_disp(code, len, i, 2, &off, &base) &&
            base == 1)
            load_offset = off;
        if (code[i] == 0x48 && code[i + 1] == 0x89 &&
            decode_x86_64_mem_disp(code, len, i, 2, &off, &base) &&
            base == 1 && ((code[i + 2] >> 3) & 7) == 7)
            store_offset = off;
    }
    if (!global || global_count != 1 || load_offset == SIZE_MAX ||
        load_offset != store_offset)
        return 0;
    *locale_out = load_offset;
    *global_out = global;
    return 1;
}

static int x86_64_code_references_rip_address(const uint8_t *code,
                                               size_t len,
                                               uintptr_t address)
{
    for (size_t i = 0; i + 6 <= len; i++) {
        size_t opcode = i;

        if ((code[opcode] & 0xf0) == 0x40)
            opcode++;
        if (opcode + 6 > len ||
            (code[opcode] != 0x8b && code[opcode] != 0x8d &&
             code[opcode] != 0x89 && code[opcode] != 0x2b &&
             code[opcode] != 0x03) ||
            (code[opcode + 1] & 0xc7) != 0x05)
            continue;
        size_t end = opcode + 6;
        uintptr_t target = (uintptr_t)(code + end) +
                           (intptr_t)read_i32_le(code + end - 4);

        if (target == address)
            return 1;
    }
    return 0;
}

static int decode_x86_64_musl_copy_tls_contract(
    const struct loaded_obj *libc_obj, uintptr_t address,
    uintptr_t libc_base, size_t *pthread_size_out,
    uintptr_t *tls_head_out, uintptr_t *tls_size_out,
    uintptr_t *tls_align_out, uintptr_t *tls_cnt_out)
{
    const uint8_t *code = (const uint8_t *)address;
    const size_t len = 192;
    size_t pthread_size = 0;
    unsigned int size_candidates = 0;
    unsigned int module_fields = 0;
    uintptr_t tls_head;
    uintptr_t tls_size;
    uintptr_t tls_align;
    uintptr_t tls_cnt;

    if (!musl_target_executable_address(libc_obj, address, len) ||
        libc_base > UINTPTR_MAX - g_musl_layout->libc_tls_head ||
        libc_base > UINTPTR_MAX - g_musl_layout->libc_tls_size ||
        libc_base > UINTPTR_MAX - g_musl_layout->libc_tls_align ||
        libc_base > UINTPTR_MAX - g_musl_layout->libc_tls_cnt)
        return 0;
    tls_head = libc_base + g_musl_layout->libc_tls_head;
    tls_size = libc_base + g_musl_layout->libc_tls_size;
    tls_align = libc_base + g_musl_layout->libc_tls_align;
    tls_cnt = libc_base + g_musl_layout->libc_tls_cnt;
    for (size_t i = 0; i + 8 <= len; i++) {
        /* lea disp32(%rdi,%rax), %rax: Variant-II places pthread at
         * mem + libc.tls_size - sizeof(struct pthread). */
        if (code[i] == 0x48 && code[i + 1] == 0x8d &&
            code[i + 2] == 0x84 && code[i + 3] == 0x07) {
            int displacement = read_i32_le(code + i + 4);

            if (displacement < 0 &&
                displacement > -MUSL_THREAD_PROBE_LIMIT) {
                pthread_size = (size_t)-displacement;
                size_candidates++;
            }
        }

        size_t off;
        unsigned int base;

        if ((code[i] == 0x48 || code[i] == 0x4c) &&
            i + 2 < len &&
            (code[i + 1] == 0x8b || code[i + 1] == 0x89 ||
             code[i + 1] == 0x2b || code[i + 1] == 0x03) &&
            decode_x86_64_mem_disp(code, len, i, 2, &off, &base)) {
            if (off == MUSL_TLS_MODULE_NEXT_OFF)
                module_fields |= 1u << 0;
            else if (off == MUSL_TLS_MODULE_IMAGE_OFF)
                module_fields |= 1u << 1;
            else if (off == MUSL_TLS_MODULE_LEN_OFF)
                module_fields |= 1u << 2;
            else if (off == MUSL_TLS_MODULE_OFFSET_OFF)
                module_fields |= 1u << 3;
        }
    }
    if (size_candidates != 1 || module_fields != 0x0f ||
        !x86_64_code_references_rip_address(
            code, len, tls_head) ||
        !x86_64_code_references_rip_address(
            code, len, tls_size) ||
        !x86_64_code_references_rip_address(
            code, len, tls_align) ||
        !x86_64_code_references_rip_address(
            code, len, tls_cnt))
        return 0;
    *pthread_size_out = pthread_size;
    *tls_head_out = tls_head;
    *tls_size_out = tls_size;
    *tls_align_out = tls_align;
    *tls_cnt_out = tls_cnt;
    return 1;
}

static int x86_64_decode_mov64_memory(
    const uint8_t *code, size_t len, size_t i, int load,
    unsigned int *reg_out, unsigned int *base_out, size_t *off_out)
{
    uint8_t rex;
    uint8_t modrm;

    if (i + 3 > len || (code[i] & 0xf8) != 0x48 ||
        code[i + 1] != (load ? 0x8b : 0x89))
        return 0;
    rex = code[i];
    modrm = code[i + 2];
    if ((modrm >> 6) == 3 ||
        !decode_x86_64_mem_disp(code, len, i, 2, off_out, base_out))
        return 0;
    *reg_out = ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);
    return 1;
}

static int x86_64_decode_mov64_register(
    const uint8_t *code, size_t len, size_t i,
    unsigned int *source_out, unsigned int *destination_out)
{
    uint8_t rex;
    uint8_t opcode;
    uint8_t modrm;
    unsigned int reg;
    unsigned int rm;

    if (i + 3 > len || (code[i] & 0xf8) != 0x48)
        return 0;
    rex = code[i];
    opcode = code[i + 1];
    modrm = code[i + 2];
    if ((opcode != 0x89 && opcode != 0x8b) || (modrm >> 6) != 3)
        return 0;
    reg = ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);
    rm = (modrm & 7) | ((rex & 1) ? 8 : 0);
    *source_out = opcode == 0x89 ? reg : rm;
    *destination_out = opcode == 0x89 ? rm : reg;
    return 1;
}

static int x86_64_decode_lea64_field(
    const uint8_t *code, size_t len, size_t i,
    unsigned int *destination_out, unsigned int *base_out, size_t *off_out)
{
    uint8_t rex;
    uint8_t modrm;

    if (i + 3 > len || (code[i] & 0xf8) != 0x48 ||
        code[i + 1] != 0x8d)
        return 0;
    rex = code[i];
    modrm = code[i + 2];
    if ((modrm >> 6) == 3 ||
        !decode_x86_64_mem_disp(code, len, i, 2, off_out, base_out))
        return 0;
    *destination_out =
        ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);
    return 1;
}

static uint32_t x86_64_musl_fs_self_registers(const uint8_t *code,
                                               size_t len)
{
    uint32_t registers = 0;

    for (size_t i = 0; i + 9 <= len; i++) {
        uint8_t rex;
        unsigned int destination;

        if (code[i] != 0x64 || (code[i + 1] & 0xf8) != 0x48 ||
            code[i + 2] != 0x8b || (code[i + 3] & 0xc7) != 0x04 ||
            code[i + 4] != 0x25 || read_u32_le(code + i + 5) != 0)
            continue;
        rex = code[i + 1];
        destination = ((code[i + 3] >> 3) & 7) |
                      ((rex & 4) ? 8 : 0);
        registers |= UINT32_C(1) << destination;
    }
    return registers;
}

static int x86_64_musl_callee_saved(unsigned int reg)
{
    return reg == 3 || reg == 5 || (reg >= 12 && reg <= 15);
}

static int x86_64_musl_copy_return_register(
    const uint8_t *code, size_t len, size_t call,
    unsigned int *register_out)
{
    size_t begin = call + 5;
    size_t end = begin + 64 < len ? begin + 64 : len;

    for (size_t i = begin; i + 3 <= end; i++) {
        unsigned int source;
        unsigned int destination;

        if (!x86_64_decode_mov64_register(
                code, len, i, &source, &destination) || source != 0 ||
            (!x86_64_musl_callee_saved(destination) && destination != 9) ||
            !x86_64_musl_gap_safe(code, begin, i, 0, 0))
            continue;
        *register_out = destination;
        return 1;
    }
    return 0;
}

static int x86_64_musl_vector_field_store(
    const uint8_t *code, size_t len, size_t i,
    unsigned int *base_out, size_t *off_out)
{
    size_t opcode_len;

    if (i + 3 <= len && code[i] == 0x0f && code[i + 1] == 0x11)
        opcode_len = 2;
    else if (i + 4 <= len && (code[i] & 0xf0) == 0x40 &&
             code[i + 1] == 0x0f && code[i + 2] == 0x11)
        opcode_len = 3;
    else
        return 0;
    if ((code[i + opcode_len] >> 6) == 3)
        return 0;
    return decode_x86_64_mem_disp(
        code, len, i, opcode_len, off_out, base_out);
}

/* Decode the narrow SIMD subset which GCC may place between musl's scalar
 * thread-list peer loads and reciprocal stores.  These instructions mutate
 * only XMM registers, so the GPR pointer provenance remains intact.  The
 * two newly admitted forms are register-only deliberately: a memory operand
 * would introduce unrelated data flow into the otherwise closed chain. */
static int x86_64_musl_simd_preserves_gprs(
    const uint8_t *code, size_t len, size_t i, size_t *end_out)
{
    size_t p = i;
    uint8_t rex = 0;
    uint8_t opcode;
    uint8_t modrm;
    size_t end;

    if (p >= len || code[p++] != 0x66)
        return 0;
    if (p < len && (code[p] & 0xf0) == 0x40)
        rex = code[p++];
    if (p + 2 > len || code[p++] != 0x0f)
        return 0;
    opcode = code[p++];
    if (!x86_64_modrm_end(code, len, p, &end))
        return 0;
    modrm = code[p];

    /* MOVDQA/MOVDQU loads and stores were already admitted here. */
    if ((opcode == 0x6f || opcode == 0x7f) && rex == 0) {
        *end_out = end;
        return 1;
    }
    /* MOVQ r64,xmm and PUNPCKLQDQ xmm,xmm touch no GPR destination. */
    if (opcode == 0x6e && (rex & 0xf8) == 0x48 &&
        (modrm >> 6) == 3) {
        *end_out = end;
        return 1;
    }
    if (opcode == 0x6c && (rex == 0 || (rex & 0xf8) == 0x40) &&
        (modrm >> 6) == 3) {
        *end_out = end;
        return 1;
    }
    return 0;
}

static int x86_64_musl_list_geometry(
    const uint8_t *code, size_t len, size_t *prev_out, size_t *next_out)
{
    uint32_t self_registers = x86_64_musl_fs_self_registers(code, len);
    size_t prev = SIZE_MAX;
    size_t next = SIZE_MAX;
    unsigned int matches = 0;

    if (!self_registers)
        return 0;
    for (size_t i = 0; i + 3 <= len; i++) {
        unsigned int first_reg;
        unsigned int self_reg;
        size_t first_off;
        size_t first_end;

        if (!x86_64_decode_mov64_memory(
                code, len, i, 1, &first_reg, &self_reg, &first_off) ||
            !(self_registers & (UINT32_C(1) << self_reg)) ||
            !x86_64_musl_callee_saved(self_reg) ||
            first_reg == self_reg ||
            !x86_64_modrm_end(code, len, i + 2, &first_end))
            continue;
        for (size_t j = first_end;
             j + 3 <= len && j <= first_end + 32; j++) {
                unsigned int second_reg;
                unsigned int second_base;
                size_t second_off;
                size_t second_end;
                size_t low;
                size_t high;
                unsigned int provenance[16] = { 0 };
                unsigned int reciprocal_stores = 0;
                size_t scan;
                size_t scan_limit;

                if (!x86_64_decode_mov64_memory(
                        code, len, j, 1, &second_reg, &second_base,
                        &second_off) || second_base != self_reg ||
                    first_reg == second_reg ||
                    second_reg == self_reg ||
                    first_off == second_off ||
                    !x86_64_modrm_end(
                        code, len, j + 2, &second_end) ||
                    !x86_64_musl_gap_safe(
                        code, first_end, j, self_reg, 0) ||
                    !x86_64_musl_gap_safe(
                        code, first_end, j, first_reg, 0))
                    continue;
                low = first_off < second_off ? first_off : second_off;
                high = first_off < second_off ? second_off : first_off;
                if (low >= MUSL_THREAD_PROBE_LIMIT ||
                    high != low + sizeof(uintptr_t))
                    continue;

                /* 1/2 are pointers loaded from prev/next; 3 is self. */
                provenance[self_reg] = 3;
                provenance[first_reg] = first_off == low ? 1 : 2;
                provenance[second_reg] = second_off == low ? 1 : 2;
                scan = second_end;
                scan_limit = scan + 64 < len ? scan + 64 : len;
                while (scan < scan_limit && reciprocal_stores != 3) {
                    unsigned int reg;
                    unsigned int base;
                    size_t off;
                    size_t insn_end;

                    if (code[scan] == 0x90) {
                        scan++;
                        continue;
                    }
                    if (x86_64_musl_simd_preserves_gprs(
                            code, scan_limit, scan, &insn_end)) {
                        scan = insn_end;
                        continue;
                    }
                    if (x86_64_decode_mov64_memory(
                            code, len, scan, 1, &reg, &base, &off) &&
                        x86_64_modrm_end(
                            code, len, scan + 2, &insn_end)) {
                        unsigned int source_kind = provenance[base];

                        if (source_kind == 3 && off == low)
                            provenance[reg] = 1;
                        else if (source_kind == 3 && off == high)
                            provenance[reg] = 2;
                        else
                            provenance[reg] = 0;
                        scan = insn_end;
                        continue;
                    }
                    if (x86_64_decode_mov64_memory(
                            code, len, scan, 0, &reg, &base, &off) &&
                        x86_64_modrm_end(
                            code, len, scan + 2, &insn_end)) {
                        if (provenance[reg] == 1 &&
                            provenance[base] == 2 && off == low)
                            reciprocal_stores |= 1u;
                        if (provenance[reg] == 2 &&
                            provenance[base] == 1 && off == high)
                            reciprocal_stores |= 2u;
                        scan = insn_end;
                        continue;
                    }
                    unsigned int source;
                    unsigned int destination;

                    if (x86_64_decode_mov64_register(
                            code, len, scan, &source, &destination)) {
                        provenance[destination] = provenance[source];
                        scan += 3;
                        continue;
                    }
                    /* A branch, call, return, unknown instruction, or
                     * unmodelled clobber ends this candidate path. */
                    break;
                }
                if (reciprocal_stores != 3)
                    continue;
                if (matches && (prev != low || next != high))
                    return 0;
                prev = low;
                next = high;
                matches++;
        }
    }
    if (!matches)
        return 0;
    *prev_out = prev;
    *next_out = next;
    return 1;
}

struct x86_64_musl_clone_instruction {
    size_t end;
    uint32_t writes;
    int changes_stack;
    int writes_memory;
};

/* musl's assembly __clone wrapper consumes its seventh C argument from the
 * caller's stack and moves it into Linux x86-64's fourth syscall argument,
 * R10.  Proving this wrapper is what makes the pushed word a kernel
 * CLONE_CHILD_CLEARTID address rather than merely an arbitrary helper arg. */
static int x86_64_musl_clone_wrapper(
    const struct loaded_obj *libc_obj, uintptr_t address)
{
    static const uint8_t prefix[] = {
        0x31, 0xc0,                         /* xor %eax,%eax */
        0xb0, 0x38,                         /* mov $SYS_clone,%al */
        0x49, 0x89, 0xfb,                   /* mov %rdi,%r11 */
        0x48, 0x89, 0xd7,                   /* mov %rdx,%rdi */
        0x4c, 0x89, 0xc2,                   /* mov %r8,%rdx */
        0x4d, 0x89, 0xc8,                   /* mov %r9,%r8 */
        0x4c, 0x8b, 0x54, 0x24, 0x08,       /* mov 8(%rsp),%r10 */
        0x4d, 0x89, 0xd9,                   /* mov %r11,%r9 */
        0x48, 0x83, 0xe6, 0xf0,             /* and $-16,%rsi */
        0x48, 0x83, 0xee, 0x08,             /* sub $8,%rsi */
        0x48, 0x89, 0x0e,                   /* mov %rcx,(%rsi) */
        0x0f, 0x05                          /* syscall */
    };
    const uint8_t *code = (const uint8_t *)address;
    size_t offset = 0;

    if (!musl_target_executable_address(
            libc_obj, address, sizeof(prefix) + 4))
        return 0;
    if (read_u32_le(code) == UINT32_C(0xfa1e0ff3)) /* ENDBR64 */
        offset = 4;
    return musl_target_executable_address(
               libc_obj, address + offset, sizeof(prefix)) &&
           memcmp(code + offset, prefix, sizeof(prefix)) == 0;
}

/* Decode only the straight-line scalar subset emitted for musl's final
 * __clone argument setup.  Unknown instructions and all control flow fail
 * closed, so each accepted assignment has a single instruction-boundary
 * path to the call. */
static int x86_64_musl_clone_instruction(
    const uint8_t *code, size_t len, size_t start,
    struct x86_64_musl_clone_instruction *decoded)
{
    size_t p = start;
    uint8_t rex = 0;
    uint8_t opcode;

    if (start >= len)
        return 0;
    decoded->writes = 0;
    decoded->changes_stack = 0;
    decoded->writes_memory = 0;
    if ((code[p] & 0xf0) == 0x40) {
        rex = code[p++];
        if (p >= len)
            return 0;
    }
    opcode = code[p++];

    if (opcode == 0x90 && rex == 0) {
        decoded->end = p;
        return 1;
    }
    if (opcode >= 0x50 && opcode <= 0x57) {
        decoded->changes_stack = 1;
        decoded->end = p;
        return 1;
    }
    if (opcode >= 0xb8 && opcode <= 0xbf) {
        size_t immediate = (rex & 8) ? 8 : 4;
        unsigned int destination =
            (opcode - 0xb8) | ((rex & 1) ? 8 : 0);

        if (immediate > len - p)
            return 0;
        decoded->writes = UINT32_C(1) << destination;
        decoded->end = p + immediate;
        return 1;
    }

    if (opcode == 0xc6 || opcode == 0xc7) {
        size_t end;
        size_t immediate = opcode == 0xc6 ? 1 : 4;
        uint8_t modrm;

        if (!x86_64_modrm_end(code, len, p, &end) || immediate > len - end)
            return 0;
        modrm = code[p];
        if (((modrm >> 3) & 7) != 0)
            return 0;
        if ((modrm >> 6) == 3) {
            unsigned int destination = (modrm & 7) | ((rex & 1) ? 8 : 0);
            if (opcode == 0xc6 && !rex && destination >= 4)
                destination -= 4; /* AH/CH/DH/BH alias the low four registers. */
            decoded->writes = 1u << destination;
        } else
            decoded->writes_memory = 1;
        decoded->end = end + immediate;
        return 1;
    }

    if (opcode == 0x0f) {
        size_t end;
        uint8_t secondary;
        uint8_t modrm;
        unsigned int destination;

        if (p >= len)
            return 0;
        secondary = code[p++];
        if (!x86_64_modrm_end(code, len, p, &end))
            return 0;
        modrm = code[p];
        if (secondary >= 0x90 && secondary <= 0x9f) { /* SETcc */
            if ((modrm >> 6) == 3) {
                destination = (modrm & 7) | ((rex & 1) ? 8 : 0);
                if (!rex && destination >= 4)
                    destination -= 4;
                decoded->writes = 1u << destination;
            } else
                decoded->writes_memory = 1;
            decoded->end = end;
            return 1;
        }
        if (secondary == 0xba && end < len && ((modrm >> 3) & 7) >= 4) {
            if (((modrm >> 3) & 7) != 4) { /* BTS/BTR/BTC, not BT */
                if ((modrm >> 6) == 3)
                    decoded->writes = 1u << ((modrm & 7) | ((rex & 1) ? 8 : 0));
                else
                    decoded->writes_memory = 1;
            }
            decoded->end = end + 1;
            return 1;
        }
        if (secondary < 0x40 || secondary > 0x4f)
            return 0;
        destination = ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);
        decoded->writes = UINT32_C(1) << destination;
        decoded->end = end;
        return 1;
    }

    if (opcode == 0x83 || opcode == 0x81) {
        size_t end;
        size_t immediate = opcode == 0x83 ? 1 : 4;
        uint8_t modrm;
        unsigned int operation;

        if (!x86_64_modrm_end(code, len, p, &end) ||
            immediate > len - end)
            return 0;
        modrm = code[p];
        operation = (modrm >> 3) & 7;
        if ((modrm >> 6) == 3) {
            unsigned int destination =
                (modrm & 7) | ((rex & 1) ? 8 : 0);

            if (operation != 7)
                decoded->writes = UINT32_C(1) << destination;
            if (destination == 4 && (operation == 0 || operation == 5))
                decoded->changes_stack = 1;
        } else if (operation != 7) {
            decoded->writes_memory = 1;
        }
        decoded->end = end + immediate;
        return 1;
    }

    if (opcode == 0x89 || opcode == 0x8b || opcode == 0x8d ||
        opcode == 0x31 || opcode == 0x29 || opcode == 0x21 ||
        opcode == 0x39 || opcode == 0x85) {
        size_t end;
        uint8_t modrm;
        unsigned int mod;

        if (!x86_64_modrm_end(code, len, p, &end))
            return 0;
        modrm = code[p];
        mod = modrm >> 6;
        if (opcode == 0x8b || opcode == 0x8d) {
            unsigned int destination =
                ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);

            decoded->writes = UINT32_C(1) << destination;
        } else if ((opcode == 0x89 || opcode == 0x31 ||
                    opcode == 0x29 || opcode == 0x21) && mod == 3) {
            unsigned int destination =
                (modrm & 7) | ((rex & 1) ? 8 : 0);

            decoded->writes = UINT32_C(1) << destination;
        } else if ((opcode == 0x89 || opcode == 0x31 ||
                    opcode == 0x29 || opcode == 0x21) && mod != 3) {
            decoded->writes_memory = 1;
        }
        decoded->end = end;
        return 1;
    }
    return 0;
}

static int x86_64_musl_clone_gap(
    const uint8_t *code, size_t len, size_t begin, size_t end,
    uint32_t protected, int forbid_stack_and_memory)
{
    size_t cursor = begin;

    while (cursor < end) {
        struct x86_64_musl_clone_instruction instruction;

        if (!x86_64_musl_clone_instruction(
                code, len, cursor, &instruction) ||
            instruction.end <= cursor || instruction.end > end ||
            (instruction.writes & protected) != 0 ||
            (forbid_stack_and_memory &&
             (instruction.changes_stack || (instruction.writes & (1u << 4)) ||
              instruction.writes_memory)))
            return 0;
        cursor = instruction.end;
    }
    return cursor == end;
}

static int x86_64_musl_rip_lea(
    const uint8_t *code, size_t len, size_t i,
    unsigned int *destination_out, uintptr_t *address_out)
{
    uint8_t rex;
    uint8_t modrm;
    uintptr_t next;
    int displacement;

    if (i + 7 > len || (code[i] & 0xf8) != 0x48 ||
        (code[i] & 3) != 0 || code[i + 1] != 0x8d ||
        (code[i + 2] & 0xc7) != 0x05)
        return 0;
    rex = code[i];
    modrm = code[i + 2];
    next = (uintptr_t)(code + i + 7);
    displacement = read_i32_le(code + i + 3);
    if ((displacement >= 0 &&
         next > UINTPTR_MAX - (uintptr_t)displacement) ||
        (displacement < 0 &&
         next < (uintptr_t)(-(int64_t)displacement)))
        return 0;
    *destination_out =
        ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);
    *address_out = displacement >= 0
        ? next + (uintptr_t)displacement
        : next - (uintptr_t)(-(int64_t)displacement);
    return 1;
}

/* Return the signed displacement of a direct RBP-relative operand. */
static int x86_64_musl_frame_operand(const uint8_t *code, size_t len,
                                     size_t start, int *offset)
{
    size_t p = start;
    uint8_t rex = 0;
    unsigned int mod;

    if (p >= len)
        return 0;
    if ((code[p] & 0xf0) == 0x40)
        rex = code[p++];
    if (p >= len || (rex & 1))
        return 0;
    if (code[p++] == 0x0f)
        p++;
    if (p >= len || (code[p] & 7) != 5)
        return 0;
    mod = code[p++] >> 6;
    if (mod == 1 && p < len)
        *offset = (int8_t)code[p];
    else if (mod == 2 && len - p >= 4)
        *offset = read_i32_le(code + p);
    else
        return 0;
    return 1;
}

static size_t x86_64_musl_fixed_frame_size(const uint8_t *code, size_t len)
{
    size_t p = 0, size = 0;

    if (len < 32)
        return 0;
    if (memcmp(code, "\xf3\x0f\x1e\xfa", 4) == 0)
        p = 4;
    if (code[p++] != 0x55)
        return 0;
    if (memcmp(code + p, "\x66\x0f\xef\xc0", 4) == 0)
        p += 4; /* independent vector zeroing scheduled in the prologue */
    if (memcmp(code + p, "\x48\x89\xe5", 3) != 0)
        return 0;
    p += 3;
    while (p + 2 < len && p < 48) {
        if (code[p] == 0x53 || code[p] == 0x56 || code[p] == 0x57) {
            p++;
        } else if (code[p] == 0x41 && code[p + 1] >= 0x54 &&
                   code[p + 1] <= 0x57) {
            p += 2;
        } else {
            break;
        }
        size += 8;
    }
    if (p + 7 <= len && memcmp(code + p, "\x48\x81\xec", 3) == 0) {
        uint32_t allocation = read_u32_le(code + p + 3);
        if (allocation > MUSL_THREAD_PROBE_LIMIT - size)
            return 0;
        return size + allocation;
    }
    return 0;
}

/* Both successors of every branch must reach the same use with the protected
 * registers intact. Calls are allowed only while the pointer is in its
 * private frame slot, never while a volatile register is the authority. */
static int x86_64_musl_pointer_path(
    const struct loaded_obj *obj, const uint8_t *code, size_t len,
    size_t pc, size_t end, uint32_t protected, int frame_slot,
    int allow_calls, unsigned int depth, unsigned int *budget)
{
    if (depth > 8)
        return 0;
    while (pc != end) {
        struct x86_64_musl_clone_instruction instruction;
        size_t next = 0;
        int64_t displacement = 0;
        int conditional = 0;
        uintptr_t target;

        if (!*budget || pc >= len)
            return 0;
        --*budget;
        if (pc + 2 <= len && (code[pc] == 0xeb ||
                              (code[pc] >= 0x70 && code[pc] <= 0x7f))) {
            next = pc + 2;
            displacement = (int8_t)code[pc + 1];
            conditional = code[pc] != 0xeb;
        } else if (pc + 5 <= len && code[pc] == 0xe9) {
            next = pc + 5;
            displacement = read_i32_le(code + pc + 1);
        } else if (pc + 6 <= len && code[pc] == 0x0f &&
                   code[pc + 1] >= 0x80 && code[pc + 1] <= 0x8f) {
            next = pc + 6;
            displacement = read_i32_le(code + pc + 2);
            conditional = 1;
        }
        if (next) {
            int64_t destination = (int64_t)next + displacement;
            if (destination < 0 || (uint64_t)destination >= len ||
                (conditional && !x86_64_musl_pointer_path(
                    obj, code, len, next, end, protected, frame_slot,
                    allow_calls, depth + 1, budget)))
                return 0;
            pc = (size_t)destination;
            continue;
        }
        if (x86_64_direct_call_target(code, len, pc, &target)) {
            if (!allow_calls || !musl_target_executable_address(obj, target, 1))
                return 0;
            pc += 5;
            continue;
        }
        if (!x86_64_musl_clone_instruction(code, len, pc, &instruction) ||
            instruction.end <= pc || (instruction.writes & protected))
            return 0;
        if (instruction.writes & (1u << 4)) {
            /* Extra outgoing argument space can only move RSP down. */
            if (pc + 4 > len || code[pc] != 0x48 || code[pc + 2] != 0xec ||
                !((code[pc + 1] == 0x83 && (int8_t)code[pc + 3] >= 0) ||
                  (code[pc + 1] == 0x81 && pc + 7 <= len &&
                   read_i32_le(code + pc + 3) >= 0)))
                return 0;
        }
        if (frame_slot && instruction.writes_memory) {
            int offset;
            if (x86_64_musl_frame_operand(code, len, pc, &offset) &&
                (int64_t)offset < (int64_t)frame_slot + 8 &&
                (int64_t)offset + 8 > frame_slot)
                return 0;
        }
        pc = instruction.end;
    }
    return 1;
}

static int x86_64_musl_spilled_tls_argument(
    const struct loaded_obj *obj, const uint8_t *code, size_t len,
    size_t copy_call, size_t clone_call)
{
    size_t frame = x86_64_musl_fixed_frame_size(code, len);

    if (!frame || copy_call >= clone_call)
        return 0;
    for (size_t move = copy_call + 5; move + 3 <= clone_call &&
         move <= copy_call + 64; move++) {
        unsigned int source, destination;

        if (!x86_64_decode_mov64_register(code, len, move, &source, &destination) ||
            source != 0 || destination != 9 ||
            !x86_64_musl_gap_safe(code, copy_call + 5, move, 0, 0))
            continue;
        for (size_t spill = move + 3; spill + 4 <= clone_call; spill++) {
            int slot;
            size_t spill_end;
            unsigned int budget = 256;

            if (code[spill] != 0x4c || code[spill + 1] != 0x89 ||
                ((code[spill + 2] >> 3) & 7) != 1 ||
                !x86_64_musl_frame_operand(code, len, spill, &slot) ||
                slot > -8 || slot < -(int)frame ||
                !x86_64_modrm_end(code, len, spill + 2, &spill_end) ||
                !x86_64_musl_pointer_path(obj, code, len, move + 3, spill,
                    (1u << 9) | (1u << 5) | (1u << 4), 0, 0, 0, &budget))
                continue;
            for (size_t reload = spill_end; reload + 4 <= clone_call; reload++) {
                int loaded_slot;
                size_t reload_end;

                if (code[reload] != 0x4c || code[reload + 1] != 0x8b ||
                    ((code[reload + 2] >> 3) & 7) != 1 ||
                    !x86_64_musl_frame_operand(code, len, reload, &loaded_slot) ||
                    loaded_slot != slot ||
                    !x86_64_modrm_end(code, len, reload + 2, &reload_end))
                    continue;
                budget = 256;
                if (x86_64_musl_pointer_path(obj, code, len, spill_end, reload,
                        (1u << 5) | (1u << 4), slot, 1, 0, &budget) &&
                    x86_64_musl_pointer_path(obj, code, len, reload_end, clone_call,
                        (1u << 9) | (1u << 5), 0, 0, 0, &budget))
                    return 1;
            }
        }
    }
    return 0;
}

static int x86_64_musl_pushed_ctid_gap(
    const uint8_t *code, size_t len, size_t begin, size_t end, int spilled_tls)
{
    size_t frame = spilled_tls ? x86_64_musl_fixed_frame_size(code, len) : 0;

    for (size_t pc = begin; pc < end;) {
        struct x86_64_musl_clone_instruction instruction;
        int offset;

        if (!x86_64_musl_clone_instruction(code, len, pc, &instruction) ||
            instruction.end <= pc || instruction.end > end ||
            instruction.changes_stack ||
            (instruction.writes & ((1u << 4) | (1u << 5))))
            return 0;
        if (instruction.writes_memory &&
            (!frame || code[pc] != 0x4c || code[pc + 1] != 0x89 ||
             ((code[pc + 2] >> 3) & 7) != 1 ||
             !x86_64_musl_frame_operand(code, len, pc, &offset) ||
             offset > -8 || offset < -(int)frame))
            return 0;
        pc = instruction.end;
    }
    return 1;
}

static int decode_x86_64_musl_clone_ctid(
    const struct loaded_obj *libc_obj, const uint8_t *code, size_t len,
    unsigned int new_reg, size_t copy_call, size_t tid_offset, uintptr_t *ctid_out)
{
    uintptr_t matched = 0;
    unsigned int matching_calls = 0;

    for (size_t call = 0; call + 5 <= len; call++) {
        uintptr_t target;
        size_t begin;
        unsigned int tls_moves = 0;
        unsigned int flag_moves = 0;
        unsigned int ptid_moves = 0;
        uintptr_t call_ctid = 0;
        unsigned int ctid_pushes = 0;

        if (!x86_64_direct_call_target(code, len, call, &target) ||
            !x86_64_musl_clone_wrapper(libc_obj, target))
            continue;
        if (new_reg == 9 &&
            x86_64_musl_spilled_tls_argument(libc_obj, code, len, copy_call, call))
            tls_moves = 1;
        begin = call > 160 ? call - 160 : 0;
        for (size_t i = begin; i + 3 <= call; i++) {
            unsigned int source;
            unsigned int destination;

            if (x86_64_decode_mov64_register(
                    code, call, i, &source, &destination) &&
                source == new_reg && destination == 9 &&
                x86_64_musl_clone_gap(
                    code, len, i + 3, call, UINT32_C(1) << 9, 0))
                tls_moves++;

            if (i + 5 <= call && code[i] == 0xba &&
                read_u32_le(code + i + 1) == MUSL_PTHREAD_CLONE_FLAGS &&
                x86_64_musl_clone_gap(
                    code, len, i + 5, call, UINT32_C(1) << 2, 0))
                flag_moves++;

            unsigned int address_reg;
            unsigned int base_reg;
            size_t field_offset;

            if (x86_64_decode_lea64_field(
                    code, call, i, &address_reg, &base_reg,
                    &field_offset) && address_reg == 8 &&
                base_reg == new_reg && field_offset == tid_offset) {
                size_t instruction_end;

                if (x86_64_modrm_end(
                        code, call, i + 2, &instruction_end) &&
                    x86_64_musl_clone_gap(
                        code, len, instruction_end, call,
                        UINT32_C(1) << 8, 0))
                    ptid_moves++;
            }

            uintptr_t address;

            if (!x86_64_musl_rip_lea(
                    code, call, i, &address_reg, &address) ||
                address_reg == 2 || address_reg == 4 ||
                address_reg == 8 || address_reg == 9 ||
                !musl_target_writable_clear_tid(libc_obj, address))
                continue;
            for (size_t push = i + 7; push < call; push++) {
                unsigned int pushed_reg;
                size_t push_end;

                if ((code[push] & 0xf0) == 0x40) {
                    if (push + 2 > call || code[push + 1] < 0x50 ||
                        code[push + 1] > 0x57)
                        continue;
                    pushed_reg = (code[push + 1] - 0x50) |
                                 ((code[push] & 1) ? 8 : 0);
                    push_end = push + 2;
                } else {
                    if (code[push] < 0x50 || code[push] > 0x57)
                        continue;
                    pushed_reg = code[push] - 0x50;
                    push_end = push + 1;
                }
                if (pushed_reg != address_reg ||
                    !x86_64_musl_clone_gap(
                        code, len, i + 7, push,
                        UINT32_C(1) << address_reg, 0) ||
                    !x86_64_musl_pushed_ctid_gap(
                        code, len, push_end, call, new_reg == 9 && tls_moves == 1))
                    continue;
                if (call_ctid && call_ctid != address)
                    return 0;
                call_ctid = address;
                ctid_pushes++;
            }
        }
        if (tls_moves != 1 || flag_moves != 1 || ptid_moves != 1 ||
            ctid_pushes != 1 || !call_ctid)
            continue;
        if (matched && matched != call_ctid)
            return 0;
        matched = call_ctid;
        matching_calls++;
    }
    if (matching_calls != 1 || !matched)
        return 0;
    *ctid_out = matched;
    return 1;
}

static int decode_x86_64_musl_pthread_geometry(
    const struct loaded_obj *libc_obj, const uint8_t *create,
    size_t create_len, const uint8_t *exit_code, size_t exit_len,
    uintptr_t libc_base, size_t canary_offset, size_t tid_offset,
    uintptr_t *copy_tls_out, size_t *pthread_size_out,
    size_t *prev_out, size_t *next_out, size_t *sysinfo_out,
    size_t *robust_out, uintptr_t *thread_list_lock_out,
    uintptr_t *tls_head_out,
    uintptr_t *tls_size_out, uintptr_t *tls_align_out,
    uintptr_t *tls_cnt_out)
{
    uintptr_t copy_tls = 0;
    size_t copy_call = 0;
    size_t pthread_size = 0;
    unsigned int copy_candidates = 0;
    unsigned int new_reg = UINT_MAX;
    uint32_t old_registers =
        x86_64_musl_fs_self_registers(create, create_len);
    uint32_t exit_self_registers =
        x86_64_musl_fs_self_registers(exit_code, exit_len);
    int self_store = 0;
    size_t robust = SIZE_MAX;
    size_t copied[2] = { SIZE_MAX, SIZE_MAX };
    unsigned int copied_count = 0;
    size_t prev = SIZE_MAX;
    size_t next = SIZE_MAX;
    unsigned int list_init_mask = 0;
    unsigned int list_backref_mask = 0;
    int exit_robust = 0;
    int have_list_geometry;

    for (size_t i = 0; i + 5 <= create_len; i++) {
        uintptr_t target;
        size_t candidate_size;
        unsigned int candidate_reg;

        if (!x86_64_direct_call_target(create, create_len, i, &target) ||
            !musl_target_executable_address(libc_obj, target, 1) ||
            !decode_x86_64_musl_copy_tls_contract(
                libc_obj, target, libc_base, &candidate_size,
                tls_head_out, tls_size_out, tls_align_out,
                tls_cnt_out) ||
            !x86_64_musl_copy_return_register(
                create, create_len, i, &candidate_reg))
            continue;
        copy_tls = target;
        copy_call = i;
        pthread_size = candidate_size;
        new_reg = candidate_reg;
        copy_candidates++;
        i += 4;
    }
    have_list_geometry = x86_64_musl_list_geometry(
        exit_code, exit_len, &prev, &next);
    if (copy_candidates != 1 || new_reg == UINT_MAX || !old_registers ||
        !exit_self_registers || !have_list_geometry) {
        ldr_dbg_hex("[loader] musl geometry: copy candidates=",
                    copy_candidates);
        ldr_dbg_hex("[loader] musl geometry: old self registers=",
                    old_registers);
        ldr_dbg_hex("[loader] musl geometry: exit self registers=",
                    exit_self_registers);
        ldr_dbg_hex("[loader] musl geometry: list geometry=",
                    have_list_geometry);
        return 0;
    }
    if (!decode_x86_64_musl_clone_ctid(
            libc_obj, create, create_len, new_reg, copy_call,
            tid_offset, thread_list_lock_out)) {
        ldr_dbg("[loader] musl geometry: clone ctid contract\n");
        return 0;
    }

    for (size_t i = 0; i + 3 <= create_len; i++) {
        unsigned int reg;
        unsigned int base;
        size_t off;

        if (x86_64_decode_mov64_memory(
                create, create_len, i, 0, &reg, &base, &off)) {
            if (reg == new_reg && base == new_reg && off == 0)
                self_store = 1;
            if (base == new_reg && off == prev)
                list_init_mask |= 1u;
            if (base == new_reg && off == next)
                list_init_mask |= 2u;
            if (reg == new_reg && base != new_reg && off == prev)
                list_backref_mask |= 1u;
            if (reg == new_reg && base != new_reg && off == next)
                list_backref_mask |= 2u;
        }

        unsigned int vector_base;
        size_t vector_off;

        if (x86_64_musl_vector_field_store(
                create, create_len, i, &vector_base, &vector_off) &&
            vector_base == new_reg && vector_off == prev &&
            next == prev + sizeof(uintptr_t))
            list_init_mask |= 3u;

        unsigned int address_reg;
        unsigned int address_base;
        size_t address_off;

        if (x86_64_decode_lea64_field(
                create, create_len, i, &address_reg, &address_base,
                &address_off) && address_base == new_reg &&
            address_off < MUSL_THREAD_PROBE_LIMIT) {
            size_t end = i + 32 < create_len ? i + 32 : create_len;

            for (size_t j = i + 3; j + 3 <= end; j++) {
                if (!x86_64_decode_mov64_memory(
                        create, create_len, j, 0, &reg, &base, &off) ||
                    reg != address_reg || base != new_reg ||
                    off != address_off)
                    continue;
                if (robust != SIZE_MAX && robust != address_off) {
                    ldr_dbg_hex(
                        "[loader] musl geometry: conflicting robust=",
                        address_off);
                    return 0;
                }
                robust = address_off;
            }
        }

        if (x86_64_decode_mov64_memory(
                create, create_len, i, 1, &reg, &base, &off) &&
            (old_registers & (UINT32_C(1) << base)) &&
            off < MUSL_THREAD_PROBE_LIMIT && off != prev && off != next) {
            size_t end = i + 24 < create_len ? i + 24 : create_len;

            for (size_t j = i + 3; j + 3 <= end; j++) {
                unsigned int store_reg;
                unsigned int store_base;
                size_t store_off;

                if (!x86_64_decode_mov64_memory(
                        create, create_len, j, 0, &store_reg,
                        &store_base, &store_off) || store_reg != reg ||
                    store_base != new_reg || store_off != off)
                    continue;
                if (copied[0] == off || copied[1] == off)
                    continue;
                if (copied_count >= 2) {
                    ldr_dbg_hex(
                        "[loader] musl geometry: extra copied field=", off);
                    return 0;
                }
                copied[copied_count++] = off;
            }
        }
    }

    if (robust != SIZE_MAX) {
        for (size_t i = 0; i + 3 <= exit_len; i++) {
            unsigned int reg;
            unsigned int base;
            size_t off;

            if ((x86_64_decode_mov64_memory(
                     exit_code, exit_len, i, 1, &reg, &base, &off) ||
                 x86_64_decode_lea64_field(
                     exit_code, exit_len, i, &reg, &base, &off)) &&
                (exit_self_registers & (UINT32_C(1) << base)) &&
                off == robust) {
                exit_robust = 1;
                break;
            }
        }
    }

    if (!self_store || robust == SIZE_MAX || copied_count != 2 ||
        list_init_mask != 3 || list_backref_mask != 3 || !exit_robust ||
        (copied[0] != canary_offset && copied[1] != canary_offset)) {
        ldr_dbg_hex("[loader] musl geometry: self store=", self_store);
        ldr_dbg_hex("[loader] musl geometry: robust=", robust);
        ldr_dbg_hex("[loader] musl geometry: copied fields=",
                    copied_count);
        ldr_dbg_hex("[loader] musl geometry: list init mask=",
                    list_init_mask);
        ldr_dbg_hex("[loader] musl geometry: list backref mask=",
                    list_backref_mask);
        ldr_dbg_hex("[loader] musl geometry: exit robust=", exit_robust);
        ldr_dbg_hex("[loader] musl geometry: canary offset=",
                    canary_offset);
        return 0;
    }
    *copy_tls_out = copy_tls;
    *pthread_size_out = pthread_size;
    *prev_out = prev;
    *next_out = next;
    *sysinfo_out = copied[0] == canary_offset ? copied[1] : copied[0];
    *robust_out = robust;
    return 1;
}

static int decode_x86_64_musl_dtv_offset(const uint8_t *code, size_t len,
                                         size_t *off_out)
{
    for (size_t i = 0; i + 4 <= len; i++) {
        if (code[i] != 0x48 || code[i + 1] != 0x8b)
            continue;

        if ((code[i + 2] & 0xc7) == 0x40) {
            *off_out = code[i + 3];
            return *off_out < MUSL_THREAD_PROBE_LIMIT;
        }
        if (i + 7 <= len && (code[i + 2] & 0xc7) == 0x80) {
            int off = read_i32_le(code + i + 3);

            if (off >= 0 && off < MUSL_THREAD_PROBE_LIMIT) {
                *off_out = (size_t)off;
                return 1;
            }
        }
    }
    return 0;
}

static int decode_x86_64_mem_disp(const uint8_t *code, size_t len,
                                  size_t i, size_t opcode_len,
                                  size_t *off_out, unsigned int *base_out)
{
    uint8_t modrm;
    uint8_t rex = 0;
    unsigned int mod;
    unsigned int base;
    size_t displacement;
    int off;

    if (i + opcode_len >= len)
        return 0;
    if (opcode_len > 1 && (code[i] & 0xf0) == 0x40)
        rex = code[i];
    modrm = code[i + opcode_len];
    mod = modrm >> 6;
    if (mod > 2)
        return 0;
    displacement = i + opcode_len + 1;
    if ((modrm & 7) == 4) {
        uint8_t sib;

        if (displacement >= len)
            return 0;
        sib = code[displacement++];
        /* Accept the RSP/R12 encoding only when the SIB has no index.  An
         * indexed address is not a direct struct pthread field access. */
        if (((sib >> 3) & 7) != 4 || (mod == 0 && (sib & 7) == 5))
            return 0;
        base = (sib & 7) | ((rex & 1) ? 8 : 0);
    } else {
        /* mod=0, r/m=5 is RIP-relative, not a zero-offset field. */
        if (mod == 0 && (modrm & 7) == 5)
            return 0;
        base = (modrm & 7) | ((rex & 1) ? 8 : 0);
    }
    if (mod == 0) {
        off = 0;
    } else if (mod == 1) {
        if (displacement + 1 > len)
            return 0;
        off = (int8_t)code[displacement];
    } else {
        if (displacement + 4 > len)
            return 0;
        off = read_i32_le(code + displacement);
    }
    if (off < 0 || off >= MUSL_THREAD_PROBE_LIMIT)
        return 0;
    *off_out = (size_t)off;
    *base_out = base;
    return 1;
}

static uint32_t x86_64_musl_self_registers(const uint8_t *code, size_t len)
{
    uint32_t registers = 1u << 7; /* first argument: RDI */
    size_t limit = len < 32 ? len : 32;

    /* GCC and Clang preserve pthread_kill's first argument in a callee-saved
     * register in the prologue.  Recognize only direct 64-bit register moves
     * from RDI; do not infer provenance from arbitrary later loads. */
    for (size_t i = 0; i + 3 <= limit; i++) {
        uint8_t rex = code[i];
        uint8_t opcode = code[i + 1];
        uint8_t modrm = code[i + 2];
        unsigned int source;
        unsigned int destination;

        if ((rex & 0xf8) != 0x48 ||
            (opcode != 0x89 && opcode != 0x8b) ||
            (modrm >> 6) != 3)
            continue;
        if (opcode == 0x89) {
            source = ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);
            destination = (modrm & 7) | ((rex & 1) ? 8 : 0);
        } else {
            source = (modrm & 7) | ((rex & 1) ? 8 : 0);
            destination = ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);
        }
        if (source == 7)
            registers |= 1u << destination;
    }
    return registers;
}

/* pthread_kill loads the target thread's tid immediately before its tkill
 * syscall.  Decode the closest displaced 32-bit load rather than assuming
 * that tid precedes errno in struct pthread (it did not in musl 1.1.x). */
static int decode_x86_64_musl_tid_offset(const uint8_t *code, size_t len,
                                         size_t *off_out)
{
    uint32_t self_registers = x86_64_musl_self_registers(code, len);

    for (size_t i = 0; i + 7 <= len; i++) {
        uint32_t nr;
        size_t begin;
        size_t candidate = 0;
        int found = 0;

        if (code[i] != 0xb8 || code[i + 5] != 0x0f || code[i + 6] != 0x05)
            continue;
        nr = read_u32_le(code + i + 1);
        if (nr != SYS_tkill && nr != SYS_tgkill)
            continue;

        begin = i > 48 ? i - 48 : 0;
        for (size_t j = begin; j < i; j++) {
            size_t off;
            unsigned int base;

            if (code[j] == 0x8b &&
                decode_x86_64_mem_disp(code, i, j, 1, &off, &base) &&
                (self_registers & (1u << base))) {
                candidate = off;
                found = 1;
            } else if (j + 1 < i && (code[j] & 0xf0) == 0x40 &&
                       (code[j + 1] == 0x8b || code[j + 1] == 0x63) &&
                       decode_x86_64_mem_disp(code, i, j, 2, &off, &base) &&
                       (self_registers & (1u << base))) {
                candidate = off;
                found = 1;
            }
        }
        if (found) {
            *off_out = candidate;
            return 1;
        }
    }

    return 0;
}

/* Old musl pthread_detach stores its detached marker directly; newer musl
 * transitions a state machine with cmpxchg.  Both expose the field offset. */
static int decode_x86_64_musl_detach_offset(const uint8_t *code, size_t len,
                                            size_t *off_out,
                                            int *initial_out)
{
    for (size_t i = 0; i + 3 <= len; i++) {
        size_t off;
        unsigned int base;
        size_t disp_len;
        size_t imm_pos;

        if (code[i] != 0xc7 || (code[i + 1] & 7) != 7 ||
            (code[i + 1] >> 6) < 1 || (code[i + 1] >> 6) > 2 ||
            !decode_x86_64_mem_disp(code, len, i, 1, &off, &base) ||
            base != 7)
            continue;
        disp_len = (code[i + 1] >> 6) == 1 ? 1 : 4;
        imm_pos = i + 2 + disp_len;
        if (imm_pos + sizeof(uint32_t) <= len &&
            read_u32_le(code + imm_pos) == 2) {
            *off_out = off;
            /* The old boolean field starts clear; detach writes 2. */
            *initial_out = 0;
            return 1;
        }
    }

    for (size_t i = 0; i + 4 <= len; i++) {
        size_t off;
        unsigned int base;

        if (code[i] == 0xf0 && code[i + 1] == 0x0f &&
            code[i + 2] == 0xb1 &&
            (code[i + 3] & 7) == 7 &&
            (code[i + 3] >> 6) >= 1 && (code[i + 3] >> 6) <= 2 &&
            decode_x86_64_mem_disp(code, len, i, 3, &off, &base) &&
            base == 7 && off == g_musl_layout->thread_detach) {
            *off_out = off;
            /* State-machine musl transitions JOINABLE (2) to DETACHED. */
            *initial_out = 2;
            return 1;
        }
    }

    /* musl 1.1.19 first advances the pthread argument to exitlock and
     * subsequently stores the detached marker through a negative disp8.
     * Decode that complete, register-preserving sequence; neither operand
     * alone is evidence for the detached field. */
    for (size_t i = 0; i + 7 <= len; i++) {
        uint32_t addend;

        if (code[i] != 0x48 || code[i + 1] != 0x81 ||
            code[i + 2] != 0xc7)
            continue;
        addend = read_u32_le(code + i + 3);
        for (size_t j = i + 7; j + 7 <= len && j <= i + 32; j++) {
            int64_t off;

            if (code[j] != 0xc7 || code[j + 1] != 0x47 ||
                read_u32_le(code + j + 3) != 2)
                continue;
            off = (int64_t)addend + (int8_t)code[j + 2];
            if (off >= 0 && off < MUSL_THREAD_PROBE_LIMIT) {
                *off_out = (size_t)off;
                *initial_out = 0;
                return 1;
            }
        }
    }
    return 0;
}
#endif

#if defined(__aarch64__)
static int aarch64_is_mrs_tpidr_el0(uint32_t insn, int *rt)
{
    if ((insn & 0xffffffe0u) != 0xd53bd040u)
        return 0;
    *rt = (int)(insn & 0x1f);
    return 1;
}

static int aarch64_decode_addsub_imm(uint32_t insn, int rn, int rd,
                                     int64_t *imm_out)
{
    uint64_t imm;

    if ((insn & 0x80000000u) == 0 || (insn & 0x20000000u) != 0 ||
        (insn & 0x1f000000u) != 0x11000000u)
        return 0;
    if ((int)((insn >> 5) & 0x1f) != rn || (int)(insn & 0x1f) != rd)
        return 0;

    imm = (insn >> 10) & 0xfff;
    if ((insn >> 22) & 1)
        imm <<= 12;
    if (imm >= MUSL_THREAD_PROBE_LIMIT * 8)
        return 0;

    *imm_out = (insn & 0x40000000u) ? -(int64_t)imm : (int64_t)imm;
    return 1;
}

static int aarch64_decode_ldr64_unsigned(uint32_t insn, int rn,
                                         size_t *off_out)
{
    size_t off;

    if ((insn & 0xffc00000u) != 0xf9400000u)
        return 0;
    if ((int)((insn >> 5) & 0x1f) != rn)
        return 0;

    off = ((insn >> 10) & 0xfff) * sizeof(uint64_t);
    if (off >= MUSL_THREAD_PROBE_LIMIT)
        return 0;
    *off_out = off;
    return 1;
}

static int aarch64_decode_ldur64_signed(uint32_t insn, int rn,
                                        int64_t *off_out)
{
    int64_t off;

    if ((insn & 0xffe00c00u) != 0xf8400000u)
        return 0;
    if ((int)((insn >> 5) & 0x1f) != rn)
        return 0;

    off = (insn >> 12) & 0x1ff;
    if (off & 0x100)
        off -= 0x200;
    if (off <= -(int64_t)MUSL_THREAD_PROBE_LIMIT ||
        off >= (int64_t)MUSL_THREAD_PROBE_LIMIT)
        return 0;
    *off_out = off;
    return 1;
}

static int aarch64_musl_registers_preserved(const uint8_t *code,
                                             size_t begin, size_t end,
                                             uint32_t protected);
static int aarch64_musl_no_control_flow(const uint8_t *code,
                                         size_t begin, size_t end);

static int decode_aarch64_musl_self_delta(const uint8_t *code, size_t len,
                                          size_t *delta_out)
{
    for (size_t i = 0; i + 4 <= len; i += 4) {
        uint32_t insn = read_u32_le(code + i);
        int rt;

        if (!aarch64_is_mrs_tpidr_el0(insn, &rt))
            continue;
        for (size_t j = i + 4; j + 4 <= len; j += 4) {
            int64_t imm;

            if (!aarch64_musl_no_control_flow(code, i + 4, j) ||
                !aarch64_musl_registers_preserved(
                    code, i + 4, j, 1u << rt))
                break;
            if (read_u32_le(code + j) == 0xd65f03c0u && rt == 0) {
                *delta_out = 0;
                return 1;
            }
            if (aarch64_decode_addsub_imm(read_u32_le(code + j), rt, 0, &imm) &&
                imm <= 0) {
                *delta_out = (size_t)-imm;
                return *delta_out < MUSL_THREAD_PROBE_LIMIT;
            }
        }
    }
    return 0;
}

static int decode_aarch64_musl_tp_relative(const uint8_t *code, size_t len,
                                           int64_t *tp_rel_out)
{
    for (size_t i = 0; i + 8 <= len; i += 4) {
        uint32_t insn = read_u32_le(code + i);
        int rt;

        if (!aarch64_is_mrs_tpidr_el0(insn, &rt))
            continue;
        for (size_t j = i + 4; j + 4 <= len; j += 4) {
            if (!aarch64_musl_no_control_flow(code, i + 4, j) ||
                !aarch64_musl_registers_preserved(
                    code, i + 4, j, 1u << rt))
                break;
            if (aarch64_decode_addsub_imm(read_u32_le(code + j), rt, 0,
                                          tp_rel_out))
                return 1;
        }
    }
    return 0;
}

static int decode_aarch64_musl_dtv_offset(const uint8_t *code, size_t len,
                                          size_t self_delta,
                                          size_t *off_out)
{
    for (size_t i = 0; i + 8 <= len; i += 4) {
        uint32_t insn = read_u32_le(code + i);
        int rt;

        if (!aarch64_is_mrs_tpidr_el0(insn, &rt))
            continue;
        for (size_t j = i + 4; j + 4 <= len && j <= i + 24; j += 4) {
            size_t tp_off;
            int64_t tp_rel;

            if (aarch64_decode_ldr64_unsigned(read_u32_le(code + j), rt, &tp_off) &&
                self_delta + tp_off < MUSL_THREAD_PROBE_LIMIT) {
                *off_out = self_delta + tp_off;
                return 1;
            }
            if (aarch64_decode_ldur64_signed(read_u32_le(code + j), rt, &tp_rel) &&
                (int64_t)self_delta + tp_rel >= 0 &&
                (int64_t)self_delta + tp_rel < MUSL_THREAD_PROBE_LIMIT) {
                *off_out = (size_t)((int64_t)self_delta + tp_rel);
                return 1;
            }
        }
    }
    return 0;
}

static uint32_t aarch64_musl_self_registers(const uint8_t *code, size_t len)
{
    uint32_t registers = 1u; /* first argument: X0 */
    size_t limit = len < 32 ? len : 32;

    for (size_t i = 0; i + 4 <= limit; i += 4) {
        uint32_t insn = read_u32_le(code + i);
        unsigned int source;
        unsigned int destination;

        /* MOV Xd, Xm is the ORR Xd, XZR, Xm alias. */
        if ((insn & 0xffe0ffe0u) == 0xaa0003e0u) {
            source = (insn >> 16) & 0x1f;
            destination = insn & 0x1f;
            if (source == 0)
                registers |= 1u << destination;
            continue;
        }

        /* Some compilers spell the same prologue copy as ADD Xd, X0, #0. */
        if ((insn & 0xffffffe0u) == 0x91000000u) {
            destination = insn & 0x1f;
            registers |= 1u << destination;
        }
    }
    return registers;
}

/* pthread_kill's inline tkill consumes a tid loaded through the pthread
 * argument (X0 or its prologue copy).  Requiring both that provenance and
 * the syscall number prevents a stack/local load from becoming an offset. */
static int decode_aarch64_musl_tid_offset(const uint8_t *code, size_t len,
                                          size_t *off_out)
{
    uint32_t self_registers = aarch64_musl_self_registers(code, len);

    for (size_t i = 0; i + 4 <= len; i += 4) {
        size_t candidate = 0;
        int found = 0;
        int has_tkill_number = 0;
        size_t begin;

        if (read_u32_le(code + i) != 0xd4000001u) /* svc #0 */
            continue;
        begin = i > 64 ? i - 64 : 0;
        for (size_t j = begin; j < i; j += 4) {
            uint32_t insn = read_u32_le(code + j);
            size_t off;
            unsigned int base;

            if ((insn & 0x7f800000u) == 0x52800000u &&
                (insn & 0x1f) == 8 &&
                (((insn >> 5) & 0xffff) == SYS_tkill ||
                 ((insn >> 5) & 0xffff) == SYS_tgkill))
                has_tkill_number = 1;

            if ((insn & 0xffc00000u) != 0xb9400000u &&
                (insn & 0xffc00000u) != 0xb9800000u)
                continue;
            base = (insn >> 5) & 0x1f;
            if (!(self_registers & (1u << base)))
                continue;
            off = ((insn >> 10) & 0xfff) * sizeof(uint32_t);
            if (off >= MUSL_THREAD_PROBE_LIMIT)
                continue;
            candidate = off;
            found = 1;
        }
        if (found && has_tkill_number) {
            *off_out = candidate;
            return 1;
        }
    }
    return 0;
}

/* Return the GPRs definitely written by an instruction used in the admitted
 * pthread_detach streams.  Unknown instructions fail closed in the data-flow
 * checks below rather than being assumed harmless. */
static int aarch64_musl_gpr_writes(uint32_t insn, uint32_t *writes_out)
{
    uint32_t writes = 0;

#define RECORD_WRITE(reg_)                                                  \
    do {                                                                    \
        unsigned int record_reg = (reg_);                                   \
        if (record_reg != 31)                                               \
            writes |= 1u << record_reg;                                     \
    } while (0)

    /* Direct and conditional branches, compare-and-branch, barriers, and
     * exact branch-target-identification landing pads do not write a GPR. */
    if ((insn & 0xfc000000u) == 0x14000000u ||
        (insn & 0xff000010u) == 0x54000000u ||
        (insn & 0x7e000000u) == 0x34000000u ||
        (insn & 0x7e000000u) == 0x36000000u ||
        (insn & 0xfffffc1fu) == 0xd65f0000u ||
        (insn & 0xffffffe0u) == 0x4f000400u || /* MOVI Vd.4S,#0 */
        insn == 0xd503201fu || insn == 0xd5033bbfu ||
        insn == 0xd503241fu || insn == 0xd503245fu ||
        insn == 0xd503249fu || insn == 0xd50324dfu) {
        *writes_out = 0;
        return 1;
    }

    /* The stack pointer-authentication prologue/epilogue forms update LR.
     * Classify only their exact encodings so an unknown HINT remains a
     * fail-closed provenance boundary. */
    if (insn == 0xd503233fu || insn == 0xd503237fu ||
        insn == 0xd50323bfu || insn == 0xd50323ffu) {
        RECORD_WRITE(30);
        *writes_out = writes;
        return 1;
    }

    /* ADR/ADRP, add/subtract immediate or register, logical register aliases
     * (including MOV), and MOVN/MOVZ/MOVK all write Rd.  The register form
     * matters to provenance checks even when it updates an unrelated
     * callee-saved register between two contract operations. */
    if ((insn & 0x1f000000u) == 0x10000000u ||
        (insn & 0x1f000000u) == 0x11000000u ||
        (insn & 0x1f000000u) == 0x0b000000u ||
        (insn & 0x1f000000u) == 0x0a000000u ||
        (insn & 0x1f800000u) == 0x12800000u ||
        (insn & 0x1fe00000u) == 0x1a800000u) { /* CSEL family */
        RECORD_WRITE(insn & 0x1f);
        *writes_out = writes;
        return 1;
    }

    /* Exact 64-bit MUL alias used by musl's legacy SSP fallback. */
    if ((insn & 0xffe0fc00u) == 0x9b007c00u) {
        RECORD_WRITE(insn & 0x1f);
        *writes_out = writes;
        return 1;
    }

    /* Exclusive load/store.  STLXR writes its status register Rs; LDAXR
     * writes Rt. */
    if ((insn & 0xfffffc00u) == 0x885ffc00u) {
        RECORD_WRITE(insn & 0x1f);
        *writes_out = writes;
        return 1;
    }
    if ((insn & 0xffe0fc00u) == 0x8800fc00u) {
        RECORD_WRITE((insn >> 16) & 0x1f);
        *writes_out = writes;
        return 1;
    }

    /* Unsigned-offset and unscaled single-register loads/stores. */
    if ((insn & 0x3b000000u) == 0x39000000u) {
        if (insn & (1u << 22))
            RECORD_WRITE(insn & 0x1f);
        *writes_out = writes;
        return 1;
    }
    if ((insn & 0x3b000000u) == 0x38000000u) {
        if (insn & (1u << 22))
            RECORD_WRITE(insn & 0x1f);
        /* Treat every indexed form conservatively as base writeback. */
        if (((insn >> 10) & 3) != 0)
            RECORD_WRITE((insn >> 5) & 0x1f);
        *writes_out = writes;
        return 1;
    }

    /* Load/store pair.  Offset mode (bits 24:23 == 2) has no writeback. */
    if ((insn & 0x3a000000u) == 0x28000000u) {
        if (insn & (1u << 22)) {
            RECORD_WRITE(insn & 0x1f);
            RECORD_WRITE((insn >> 10) & 0x1f);
        }
        if ((insn & 0x01800000u) != 0x01000000u)
            RECORD_WRITE((insn >> 5) & 0x1f);
        *writes_out = writes;
        return 1;
    }

    /* A system-register read writes Rt. */
    if ((insn & 0xfff00000u) == 0xd5300000u) {
        RECORD_WRITE(insn & 0x1f);
        *writes_out = writes;
        return 1;
    }

#undef RECORD_WRITE
    return 0;
}

static int aarch64_musl_registers_preserved(const uint8_t *code,
                                             size_t begin, size_t end,
                                             uint32_t protected)
{
    if ((begin & 3) != 0 || (end & 3) != 0 || begin > end)
        return 0;
    for (size_t i = begin; i < end; i += 4) {
        uint32_t writes;

        if (!aarch64_musl_gpr_writes(read_u32_le(code + i), &writes) ||
            (writes & protected) != 0)
            return 0;
    }
    return 1;
}

static int aarch64_musl_is_control_flow(uint32_t insn)
{
    return (insn & 0xfc000000u) == 0x14000000u ||
           (insn & 0xfc000000u) == 0x94000000u ||
           (insn & 0xff000010u) == 0x54000000u ||
           (insn & 0x7e000000u) == 0x34000000u ||
           (insn & 0x7e000000u) == 0x36000000u ||
           (insn & 0xfffffc1fu) == 0xd61f0000u ||
           (insn & 0xfffffc1fu) == 0xd63f0000u ||
           (insn & 0xfffffc1fu) == 0xd65f0000u;
}

static int aarch64_musl_no_control_flow(const uint8_t *code,
                                         size_t begin, size_t end)
{
    if ((begin & 3) != 0 || (end & 3) != 0 || begin > end)
        return 0;
    for (size_t i = begin; i < end; i += 4)
        if (aarch64_musl_is_control_flow(read_u32_le(code + i)))
            return 0;
    return 1;
}

static int aarch64_unconditional_branch(size_t pos, uint32_t insn,
                                         int64_t *target_out)
{
    int64_t imm;

    if ((insn & 0xfc000000u) != 0x14000000u)
        return 0;
    imm = insn & 0x03ffffffu;
    if (imm & (1 << 25))
        imm -= 1 << 26;
    *target_out = (int64_t)pos + imm * 4;
    return 1;
}

/* Prove that source still contains pthread_detach's original X0 argument at
 * the exact use site. Direct register copies survive only a fully decoded,
 * call-free prefix; any later write invalidates that provenance. */
static int aarch64_musl_arg0_at(const uint8_t *code, size_t use,
                                unsigned int source, int allow_volatile)
{
    uint32_t valid = 1u;

    if ((use & 3) != 0 || source >= 31 ||
        (!allow_volatile && source != 0 && (source < 19 || source > 28)))
        return 0;
    for (size_t i = 0; i < use; i += 4) {
        uint32_t insn = read_u32_le(code + i);
        uint32_t writes;
        unsigned int copy_destination = 31;

        /* Prologue provenance is deliberately linear.  The admitted copies
         * precede control flow; proving that a branch reaches a later copy
         * would require a full CFG and is not private-layout evidence. */
        if (aarch64_musl_is_control_flow(insn))
            return 0;
        if ((insn & 0xffffffe0u) == 0xaa0003e0u &&
            (valid & 1u) != 0) {
            unsigned int destination = insn & 0x1f;

            if (destination != 31 &&
                (allow_volatile || (destination >= 19 && destination <= 28)))
                copy_destination = destination;
        }
        if (!aarch64_musl_gpr_writes(insn, &writes))
            return 0;
        valid &= ~writes;
        if (copy_destination != 31)
            valid |= 1u << copy_destination;
    }
    return (valid & (1u << source)) != 0;
}

static int aarch64_decode_movz_u32(uint32_t insn, unsigned int reg,
                                   uint32_t *value_out)
{
    unsigned int shift_words;

    if (!value_out || reg == 31 ||
        (insn & UINT32_C(0x7f800000)) != UINT32_C(0x52800000) ||
        (insn & 31U) != reg)
        return 0;
    shift_words = (insn >> 21) & 3U;
    /* The 32-bit MOVZ encoding admits shifts 0 and 16 only. */
    if (shift_words > 1U)
        return 0;
    *value_out = ((insn >> 5) & UINT32_C(0xffff)) <<
                 (shift_words * 16U);
    return 1;
}

static int aarch64_is_movz_value(uint32_t insn, unsigned int reg,
                                  unsigned int value)
{
    uint32_t decoded;

    return aarch64_decode_movz_u32(insn, reg, &decoded) &&
           decoded == value;
}

static int aarch64_musl_constant_at(const uint8_t *code, size_t use,
                                    unsigned int reg, unsigned int value)
{
    size_t begin = use > 64 ? use - 64 : 0;

    if (reg == 31)
        return 0;
    for (size_t i = begin; i < use; i += 4) {
        if (aarch64_is_movz_value(read_u32_le(code + i), reg, value) &&
            aarch64_musl_no_control_flow(code, 0, i) &&
            aarch64_musl_no_control_flow(code, i + 4, use) &&
            aarch64_musl_registers_preserved(
                code, i + 4, use, 1u << reg))
            return 1;
    }
    return 0;
}

static int aarch64_cond_branch(size_t pos, uint32_t insn,
                               unsigned int *cond_out, int64_t *target_out)
{
    int64_t imm;

    if ((insn & 0xff000010u) != 0x54000000u)
        return 0;
    imm = (insn >> 5) & 0x7ffff;
    if (imm & (1 << 18))
        imm -= 1 << 19;
    *cond_out = insn & 0xf;
    *target_out = (int64_t)pos + imm * 4;
    return 1;
}

static int aarch64_cbz_branch(size_t pos, uint32_t insn,
                              unsigned int expected_reg,
                              int64_t *target_out)
{
    int64_t imm;

    /* Accept W/X CBZ, but not CBNZ. */
    if ((insn & 0x7f000000u) != 0x34000000u ||
        (insn & 0x1f) != expected_reg)
        return 0;
    imm = (insn >> 5) & 0x7ffff;
    if (imm & (1 << 18))
        imm -= 1 << 19;
    *target_out = (int64_t)pos + imm * 4;
    return 1;
}

static int aarch64_cbnz_branch(size_t pos, uint32_t insn,
                               unsigned int expected_reg,
                               int64_t *target_out)
{
    int64_t imm;

    /* Accept W/X CBNZ, but not CBZ. */
    if ((insn & 0x7f000000u) != 0x35000000u ||
        (insn & 0x1f) != expected_reg)
        return 0;
    imm = (insn >> 5) & 0x7ffff;
    if (imm & (1 << 18))
        imm -= 1 << 19;
    *target_out = (int64_t)pos + imm * 4;
    return 1;
}

static int aarch64_musl_fallthrough_returns(const uint8_t *code,
                                             size_t begin, size_t len)
{
    size_t end = len;

    if ((begin & 3) != 0 || begin >= len)
        return 0;
    if (end - begin > 32)
        end = begin + 32;
    for (size_t i = begin; i + 4 <= end; i += 4) {
        uint32_t insn = read_u32_le(code + i);
        uint32_t writes;

        if (insn == 0xd65f03c0u) /* RET X30 */
            return 1;
        if (aarch64_musl_is_control_flow(insn) ||
            !aarch64_musl_gpr_writes(insn, &writes))
            return 0;
    }
    return 0;
}

static int aarch64_musl_forward_value(const uint8_t *code, size_t load,
                                      size_t branch, unsigned int value_reg)
{
    for (size_t i = 0; i < load; i += 4) {
        if (aarch64_is_movz_value(read_u32_le(code + i), value_reg, 3) &&
            aarch64_musl_no_control_flow(code, 0, i) &&
            aarch64_musl_no_control_flow(code, i + 4, branch) &&
            aarch64_musl_registers_preserved(
                code, i + 4, branch, 1u << value_reg))
            return 1;
    }
    return 0;
}

static int aarch64_musl_loop_value(const uint8_t *code,
                                   size_t initial_branch, size_t load,
                                   size_t compare_branch,
                                   unsigned int value_reg)
{
    for (size_t i = 0; i < initial_branch; i += 4) {
        if (aarch64_is_movz_value(read_u32_le(code + i), value_reg, 3) &&
            aarch64_musl_no_control_flow(code, 0, i) &&
            aarch64_musl_no_control_flow(code, i + 4, initial_branch) &&
            aarch64_musl_registers_preserved(
                code, i + 4, initial_branch, 1u << value_reg) &&
            aarch64_musl_registers_preserved(
                code, load, compare_branch, 1u << value_reg))
            return 1;
    }
    return 0;
}

/* As on x86-64, old pthread_detach directly stores a detached marker while
 * modern implementations use an exclusive state transition. */

static int decode_aarch64_musl_detach_offset(const uint8_t *code, size_t len,
                                             size_t *off_out,
                                             int *initial_out)
{
    /* A compiler may rematerialize &thread->detach_state independently at
     * the exclusive load and store, and consume the load's address register
     * as its result. Prove the complete small retry loop and both address
     * calculations, rather than requiring identical physical registers. */
    for (size_t b = 0; b + 32 <= len; b += 4) {
        uint32_t store_add = read_u32_le(code + b + 4);
        uint32_t store = read_u32_le(code + b + 8);
        uint32_t load_add = read_u32_le(code + b + 16);
        uint32_t load = read_u32_le(code + b + 20);
        uint32_t compare = read_u32_le(code + b + 24);
        unsigned int source = (store_add >> 5) & 31;
        unsigned int store_base = store_add & 31;
        unsigned int load_base = load_add & 31;
        unsigned int value = store & 31;
        unsigned int status = (store >> 16) & 31;
        unsigned int loaded = load & 31;
        unsigned int condition;
        int64_t initial, retry, done;
        size_t offset = (store_add >> 10) & 0xfff;

        if ((store_add & 0xffc00000u) != 0x91000000u ||
            (load_add & ~UINT32_C(31)) != (store_add & ~UINT32_C(31)) ||
            source == 31 || store_base == 31 || load_base == 31 ||
            value == 31 || status == 31 || loaded == 31 ||
            source == value || status == value || loaded == value ||
            offset >= MUSL_THREAD_PROBE_LIMIT ||
            (store & 0xffe0fc00u) != 0x8800fc00u ||
            ((store >> 5) & 31) != store_base ||
            (load & 0xfffffc00u) != 0x885ffc00u ||
            ((load >> 5) & 31) != load_base ||
            compare != (UINT32_C(0x7100081f) | (loaded << 5)) ||
            !aarch64_unconditional_branch(b, read_u32_le(code + b), &initial) ||
            initial != (int64_t)b + 16 ||
            !aarch64_cbz_branch(b + 12, read_u32_le(code + b + 12), status, &done) ||
            done <= (int64_t)b + 28 || (uint64_t)done >= len ||
            !aarch64_cond_branch(b + 28, read_u32_le(code + b + 28), &condition, &retry) ||
            condition != 0 || retry != (int64_t)b + 4 ||
            !aarch64_musl_arg0_at(code, b, source, 1) ||
            !aarch64_musl_loop_value(code, b, b + 16, b + 28, value) ||
            !aarch64_musl_registers_preserved(
                code, b + 4, b + 32, (1u << source) | (1u << value)))
            continue;
        *off_out = offset;
        *initial_out = 2;
        return 1;
    }

    for (size_t i = 0; i + 4 <= len; i += 4) {
        uint32_t mov = read_u32_le(code + i);
        unsigned int value_reg;

        value_reg = mov & 0x1f;
        if (!aarch64_is_movz_value(mov, value_reg, 2))
            continue;
        for (size_t j = i + 4; j + 4 <= len && j <= i + 16; j += 4) {
            uint32_t store = read_u32_le(code + j);
            unsigned int base_reg = (store >> 5) & 0x1f;
            size_t off;

            if ((store & 0xffc00000u) != 0xb9000000u ||
                base_reg == 31 || (store & 0x1f) != value_reg ||
                !aarch64_musl_arg0_at(code, j, base_reg, 0) ||
                !aarch64_musl_constant_at(code, j, value_reg, 2))
                continue;
            off = ((store >> 10) & 0xfff) * sizeof(uint32_t);
            if (off < MUSL_THREAD_PROBE_LIMIT) {
                *off_out = off;
                *initial_out = 0;
                return 1;
            }
        }
    }

    for (size_t i = 0; i + 8 <= len; i += 4) {
        uint32_t add = read_u32_le(code + i);
        unsigned int source_reg;
        unsigned int address_reg;
        uint64_t off;

        if ((add & 0xff000000u) != 0x91000000u)
            continue;
        source_reg = (add >> 5) & 0x1f;
        address_reg = add & 0x1f;
        if (address_reg == 31 ||
            !aarch64_musl_arg0_at(code, i, source_reg, 0))
            continue;
        off = (add >> 10) & 0xfff;
        if ((add >> 22) & 1)
            off <<= 12;
        if (off >= MUSL_THREAD_PROBE_LIMIT)
            continue;
        /* Stack-protected builds may interleave their canary prologue with
         * the detach transition (one hardened fixture places LDAXR 56 bytes
         * after the address calculation).  Keep admission fail-closed by requiring
         * the complete JOINABLE (2) -> DETACHED (3) exclusive sequence. */
        for (size_t j = i + 4; j + 4 <= len && j <= i + 80; j += 4) {
            uint32_t load = read_u32_le(code + j);
            unsigned int loaded_reg;

            if ((load & 0xfffffc00u) != 0x885ffc00u ||
                ((load >> 5) & 0x1f) != address_reg)
                continue;
            loaded_reg = load & 0x1f;
            if (loaded_reg == 31 || loaded_reg == address_reg)
                continue;

            for (size_t k = j + 4; k + 4 <= len && k <= j + 16; k += 4) {
                uint32_t compare = read_u32_le(code + k);
                size_t branch_pos = k + 4;
                unsigned int condition;
                int64_t branch_target;

                if (k != j + 4 ||
                    (compare & 0xff00001fu) != 0x7100001fu ||
                    ((compare >> 5) & 0x1f) != loaded_reg ||
                    ((compare >> 10) & 0xfff) != 2 ||
                    ((compare >> 22) & 1) != 0 ||
                    branch_pos + 4 > len ||
                    !aarch64_cond_branch(
                        branch_pos, read_u32_le(code + branch_pos),
                        &condition, &branch_target) ||
                    (condition != 0 && condition != 1))
                    continue;

                for (size_t m = i + 4;
                     m + 4 <= len && m <= j + 24; m += 4) {
                    uint32_t store = read_u32_le(code + m);
                    unsigned int status_reg;
                    unsigned int value_reg;

                    if ((store & 0xffe0fc00u) != 0x8800fc00u ||
                        ((store >> 5) & 0x1f) != address_reg)
                        continue;
                    status_reg = (store >> 16) & 0x1f;
                    value_reg = store & 0x1f;
                    if (status_reg == 31 || value_reg == 31 ||
                        status_reg == address_reg ||
                        status_reg == value_reg)
                        continue;

                    /* B.NE skips a following store when the state is not
                     * JOINABLE.  B.EQ either loops back to a preceding store
                     * or, in older GCC output, jumps forward over the
                     * non-joinable tail-call path to the store. */
                    if (condition == 1) {
                        if (m != branch_pos + 4 ||
                            branch_target <= (int64_t)m ||
                            !aarch64_musl_no_control_flow(
                                code, i + 4, j) ||
                            !aarch64_musl_registers_preserved(
                                code, i + 4, j, 1u << address_reg) ||
                            !aarch64_musl_forward_value(
                                code, j, branch_pos, value_reg))
                            continue;
                    } else {
                        int64_t initial_target;
                        int64_t cbz_target;

                        /* Older GCC output puts STLXR after the non-joinable
                         * tail-call path.  Prove both CFG edges: B.EQ must
                         * land exactly on STLXR, while the branch immediately
                         * before it must leave this bounded pthread_detach
                         * view.  The following CBNZ must retry the exact LDAXR
                         * using STLXR's status register. */
                        if (m >= branch_pos + 4 && m + 8 <= len &&
                            branch_target == (int64_t)m &&
                            loaded_reg != value_reg &&
                            aarch64_unconditional_branch(
                                m - 4, read_u32_le(code + m - 4),
                                &initial_target) &&
                            (initial_target < 0 ||
                             (uint64_t)initial_target >= (uint64_t)len) &&
                            aarch64_cbnz_branch(
                                m + 4, read_u32_le(code + m + 4),
                                status_reg, &cbz_target) &&
                            cbz_target == (int64_t)j &&
                            aarch64_musl_fallthrough_returns(
                                code, m + 8, len) &&
                            aarch64_musl_no_control_flow(
                                code, i + 4, j) &&
                            aarch64_musl_registers_preserved(
                                code, i + 4, branch_pos,
                                1u << address_reg) &&
                            aarch64_musl_forward_value(
                                code, j, branch_pos, value_reg)) {
                            *off_out = (size_t)off;
                            *initial_out = 2;
                            return 1;
                        }

                        if (m < 4 || m + 8 != j ||
                            branch_target != (int64_t)m ||
                            loaded_reg == value_reg ||
                            !aarch64_unconditional_branch(
                                m - 4, read_u32_le(code + m - 4),
                                &initial_target) ||
                            initial_target != (int64_t)j ||
                            !aarch64_cbz_branch(
                                m + 4, read_u32_le(code + m + 4),
                                status_reg, &cbz_target) ||
                            cbz_target <= (int64_t)j ||
                            !aarch64_musl_no_control_flow(
                                code, i + 4, m - 4) ||
                            !aarch64_musl_registers_preserved(
                                code, i + 4, m - 4,
                                1u << address_reg) ||
                            !aarch64_musl_registers_preserved(
                                code, m, j, 1u << address_reg) ||
                            !aarch64_musl_loop_value(
                                code, m - 4, j, branch_pos, value_reg))
                            continue;
                    }

                    *off_out = (size_t)off;
                    *initial_out = 2;
                    return 1;
                }
            }
        }
    }
    return 0;
}
#endif

#if defined(__x86_64__)
static int x86_64_modrm_end(const uint8_t *code, size_t len,
                            size_t modrm_pos, size_t *end_out)
{
    uint8_t modrm;
    unsigned int mod;
    unsigned int rm;
    size_t end;

    if (modrm_pos >= len)
        return 0;
    modrm = code[modrm_pos];
    mod = modrm >> 6;
    rm = modrm & 7;
    end = modrm_pos + 1;
    if (mod == 3) {
        *end_out = end;
        return 1;
    }
    if (rm == 4) {
        uint8_t sib;

        if (end >= len)
            return 0;
        sib = code[end++];
        if (mod == 0 && (sib & 7) == 5)
            end += 4;
    } else if (mod == 0 && rm == 5) {
        end += 4;
    }
    if (mod == 1)
        end++;
    else if (mod == 2)
        end += 4;
    if (end > len)
        return 0;
    *end_out = end;
    return 1;
}

/* Conservatively prove that the instructions between a flag load and its
 * test preserve the loaded register.  Only prologue operations present in
 * the admitted musl 1.1.x builds are decoded; calls and unknown instructions
 * fail closed. */
static int x86_64_musl_gap_safe(const uint8_t *code, size_t begin,
                                size_t end, unsigned int flag_reg,
                                int preserve_flags)
{
    size_t i = begin;

    while (i < end) {
        uint8_t rex = 0;
        size_t opcode_pos = i;
        uint8_t opcode;
        size_t insn_end;

        if (code[i] == 0x90) {
            i++;
            continue;
        }
        /* mov %fs:disp32, %r64 (stack-canary or thread-pointer load) */
        if (i + 9 <= end && code[i] == 0x64 &&
            (code[i + 1] == 0x48 || code[i + 1] == 0x4c) &&
            code[i + 2] == 0x8b &&
            (code[i + 3] & 0xc7) == 0x04 && code[i + 4] == 0x25) {
            unsigned int destination =
                ((code[i + 3] >> 3) & 7) |
                ((code[i + 1] & 4) ? 8 : 0);

            if (destination == flag_reg)
                return 0;
            i += 9;
            continue;
        }
        if ((code[opcode_pos] & 0xf0) == 0x40) {
            rex = code[opcode_pos++];
            if (opcode_pos >= end)
                return 0;
        }
        opcode = code[opcode_pos++];

        if (opcode >= 0xb8 && opcode <= 0xbf) {
            unsigned int destination =
                (opcode - 0xb8) | ((rex & 1) ? 8 : 0);
            size_t immediate_size = (rex & 8) ? 8 : 4;

            if (destination == flag_reg ||
                immediate_size > end - opcode_pos)
                return 0;
            i = opcode_pos + immediate_size;
            continue;
        }

        if (opcode == 0x0f) {
            if (opcode_pos >= end || code[opcode_pos++] != 0x29 ||
                !x86_64_modrm_end(code, end, opcode_pos, &insn_end))
                return 0;
            i = insn_end;
            continue;
        }

        if (opcode != 0x89 && opcode != 0x8b && opcode != 0x31 &&
            opcode != 0xc7)
            return 0;
        if (opcode == 0x31 && preserve_flags)
            return 0;
        if (!x86_64_modrm_end(code, end, opcode_pos, &insn_end))
            return 0;

        uint8_t modrm = code[opcode_pos];
        unsigned int mod = modrm >> 6;
        unsigned int destination;

        if (opcode == 0x8b) {
            destination = ((modrm >> 3) & 7) | ((rex & 4) ? 8 : 0);
            if (destination == flag_reg)
                return 0;
        } else if (mod == 3) {
            destination = (modrm & 7) | ((rex & 1) ? 8 : 0);
            if (destination == flag_reg)
                return 0;
        }
        if (opcode == 0xc7) {
            if (((modrm >> 3) & 7) != 0 || 4 > end - insn_end)
                return 0;
            insn_end += 4;
        }
        i = insn_end;
    }
    return i == end;
}

/* Old musl releases load the two struct __libc thread-state words into a
 * register and branch on a subsequent `test reg, reg`.  Newer builds compare
 * the RIP-relative memory operand directly.  Decode the old form only when
 * the complete load/test/zero-branch data-use pattern is present. */
static int decode_x86_64_musl_flag_load(const uint8_t *code, size_t len,
                                        size_t i, uintptr_t *addr_out,
                                        size_t *end_out)
{
    size_t insn_len;
    unsigned int reg;
    uint64_t target;

    if (i + 6 <= len && code[i] == 0x8b &&
        (code[i + 1] & 0xc7) == 0x05) {
        insn_len = 6;
        reg = (code[i + 1] >> 3) & 7;
    } else if (i + 7 <= len && code[i] == 0x44 && code[i + 1] == 0x8b &&
               (code[i + 2] & 0xc7) == 0x05) {
        insn_len = 7;
        reg = ((code[i + 2] >> 3) & 7) + 8;
    } else {
        return 0;
    }

    if (!u64_add_i64_checked(
            (uint64_t)(uintptr_t)(code + i + insn_len),
            read_i32_le(code + i + insn_len - sizeof(uint32_t)), &target) ||
        target > UINTPTR_MAX)
        return 0;

    for (size_t j = i + insn_len;
         j <= i + insn_len + 64 && j < len; j++) {
        size_t test_len;
        size_t test_end;

        if (reg < 8 && j + 2 <= len && code[j] == 0x85 &&
            code[j + 1] == (uint8_t)(0xc0 | reg | (reg << 3))) {
            test_len = 2;
        } else if (reg >= 8 && j + 3 <= len && code[j] == 0x45 &&
                   code[j + 1] == 0x85 &&
                   code[j + 2] ==
                       (uint8_t)(0xc0 | (reg & 7) | ((reg & 7) << 3))) {
            test_len = 3;
        } else {
            continue;
        }

        if (!x86_64_musl_gap_safe(code, i + insn_len, j, reg, 0))
            continue;
        test_end = j + test_len;
        /* pthread_create skips its thread setup when either flag is zero.
         * Old builds initialize stack arguments between TEST and JE, so
         * prove that every intervening instruction preserves EFLAGS. */
        for (size_t k = test_end;
             k <= test_end + 64 && k < len; k++) {
            size_t branch_len;

            if (k + 6 <= len && code[k] == 0x0f && code[k + 1] == 0x84)
                branch_len = 6;
            else if (k + 2 <= len && code[k] == 0x74)
                branch_len = 2;
            else
                continue;
            if (!x86_64_musl_gap_safe(code, test_end, k,
                                       UINT_MAX, 1))
                continue;
            *addr_out = (uintptr_t)target;
            *end_out = k + branch_len;
            return 1;
        }
    }
    return 0;
}

static int x86_64_musl_libc_candidate(const struct loaded_obj *libc_obj,
                                      uintptr_t candidate, uintptr_t second,
                                      uintptr_t *addr_out)
{
    void *checked;

    if (candidate > UINTPTR_MAX - g_musl_layout->libc_threaded ||
        second != candidate + g_musl_layout->libc_threaded ||
        candidate < libc_obj->base ||
        candidate - libc_obj->base > INT64_MAX ||
        !loaded_obj_signed_offset_pointer(
            libc_obj, (int64_t)(candidate - libc_obj->base),
            g_musl_layout->libc_size, PF_W, &checked))
        return 0;
    *addr_out = (uintptr_t)checked;
    return 1;
}

static int decode_x86_64_musl_libc_addr(const struct loaded_obj *libc_obj,
                                        const uint8_t *code, size_t len,
                                        uintptr_t *addr_out,
                                        uintptr_t *can_do_out,
                                        size_t *flag_width_out)
{
    uint8_t cmp_opcode = g_musl_layout->libc_flag_width == 1 ? 0x80 : 0x83;

    for (size_t i = 0; i + 7 <= len; i++) {
        uintptr_t first;

        if (code[i] != cmp_opcode || code[i + 1] != 0x3d ||
            code[i + 6] != 0)
            continue;
        first = (uintptr_t)(code + i + 7) +
                (intptr_t)read_i32_le(code + i + 2);
        if (first < libc_obj->base + g_musl_layout->libc_can_do_threads)
            continue;
        uintptr_t candidate = first - g_musl_layout->libc_can_do_threads;

        for (size_t j = i + 7; j + 7 <= len && j <= i + 160; j++) {
            uintptr_t second;

            if (code[j] != cmp_opcode || code[j + 1] != 0x3d ||
                code[j + 6] != 0)
                continue;
            second = (uintptr_t)(code + j + 7) +
                     (intptr_t)read_i32_le(code + j + 2);
            if (x86_64_musl_libc_candidate(libc_obj, candidate, second,
                                           addr_out)) {
                *can_do_out = first;
                *flag_width_out =
                    cmp_opcode == 0x80 ? sizeof(uint8_t) : sizeof(uint32_t);
                return 1;
            }
        }
    }

    if (g_musl_layout->libc_flag_width != sizeof(uint32_t))
        return 0;

    for (size_t i = 0; i < len; i++) {
        uintptr_t first;
        size_t first_end;

        if (!decode_x86_64_musl_flag_load(code, len, i, &first,
                                           &first_end) ||
            first < libc_obj->base +
                        g_musl_layout->libc_can_do_threads)
            continue;
        uintptr_t candidate =
            first - g_musl_layout->libc_can_do_threads;

        for (size_t j = first_end;
             j < len && j <= first_end + 160; j++) {
            uintptr_t second;
            size_t second_end;

            if (decode_x86_64_musl_flag_load(code, len, j, &second,
                                              &second_end) &&
                x86_64_musl_libc_candidate(libc_obj, candidate, second,
                                           addr_out)) {
                *can_do_out = first;
                *flag_width_out = sizeof(uint32_t);
                return 1;
            }
        }
    }
    return 0;
}
#elif defined(__aarch64__)
static int aarch64_decode_musl_adrp(uintptr_t pc, uint32_t insn,
                                    unsigned int *rd_out,
                                    uintptr_t *page_out)
{
    int64_t imm;

    if ((insn & 0x9f000000u) != 0x90000000u)
        return 0;
    imm = (int64_t)((((uint64_t)insn >> 5) & 0x7ffffu) << 2 |
                    (((uint64_t)insn >> 29) & 3));
    if (imm & (1 << 20))
        imm -= (1 << 21);
    imm <<= 12;
    *rd_out = insn & 0x1f;
    *page_out = (uintptr_t)((int64_t)(pc & ~(uintptr_t)0xfff) + imm);
    return 1;
}

static int aarch64_decode_add_address(uint32_t insn,
                                      unsigned int base_reg,
                                      uintptr_t page,
                                      unsigned int *rd_out,
                                      uintptr_t *address_out)
{
    uint64_t addend;

    if ((insn & 0xff000000u) != 0x91000000u ||
        ((insn >> 5) & 0x1f) != base_reg)
        return 0;
    addend = (insn >> 10) & 0xfff;
    if ((insn >> 22) & 1)
        addend <<= 12;
    if (page > UINTPTR_MAX - addend)
        return 0;
    *rd_out = insn & 0x1f;
    *address_out = page + addend;
    return 1;
}

static int aarch64_decode_ldrstr64_unsigned(uint32_t insn, int load,
                                            unsigned int *rt_out,
                                            unsigned int *rn_out,
                                            size_t *off_out)
{
    uint32_t expected = load ? 0xf9400000u : 0xf9000000u;

    if ((insn & 0xffc00000u) != expected)
        return 0;
    *rt_out = insn & 0x1f;
    *rn_out = (insn >> 5) & 0x1f;
    *off_out = ((insn >> 10) & 0xfff) * sizeof(uint64_t);
    return 1;
}

static int aarch64_decode_ldp64_offset(uint32_t insn, int load,
                                       unsigned int *rt_out,
                                       unsigned int *rt2_out,
                                       unsigned int *rn_out,
                                       size_t *off_out)
{
    uint32_t expected = load ? 0xa9400000u : 0xa9000000u;
    int64_t offset;

    if ((insn & 0xffc00000u) != expected)
        return 0;
    offset = (insn >> 15) & 0x7f;
    if (offset & 0x40)
        offset -= 0x80;
    offset *= (int64_t)sizeof(uint64_t);
    if (offset < 0 || offset >= MUSL_THREAD_PROBE_LIMIT)
        return 0;
    *rt_out = insn & 0x1f;
    *rt2_out = (insn >> 10) & 0x1f;
    *rn_out = (insn >> 5) & 0x1f;
    *off_out = (size_t)offset;
    return 1;
}

static int decode_aarch64_musl_uselocale(
    const struct loaded_obj *libc_obj, const uint8_t *code, size_t len,
    size_t self_delta, size_t *locale_out, uintptr_t *global_out)
{
    int tp_reg = -1;
    int self_reg = -1;
    size_t tp_ready = SIZE_MAX;
    size_t self_ready = SIZE_MAX;
    size_t loaded_locale = SIZE_MAX;
    size_t stored_locale = SIZE_MAX;
    uintptr_t global = 0;
    unsigned int global_uses = 0;

    for (size_t i = 0; i + 4 <= len; i += 4) {
        uint32_t insn = read_u32_le(code + i);
        int candidate_tp;
        int64_t relative;

        if (aarch64_is_mrs_tpidr_el0(insn, &candidate_tp)) {
            if (tp_reg >= 0 && tp_reg != candidate_tp)
                return 0;
            tp_reg = candidate_tp;
            tp_ready = i + 4;
            continue;
        }
        if (tp_reg >= 0 &&
            aarch64_decode_ldur64_signed(insn, tp_reg, &relative) &&
            relative + (int64_t)self_delta >= 0 &&
            relative + (int64_t)self_delta < MUSL_THREAD_PROBE_LIMIT &&
            aarch64_musl_no_control_flow(code, tp_ready, i) &&
            aarch64_musl_registers_preserved(
                code, tp_ready, i,
                UINT32_C(1) << (unsigned int)tp_reg)) {
            size_t candidate =
                (size_t)(relative + (int64_t)self_delta);

            if (loaded_locale != SIZE_MAX && loaded_locale != candidate)
                return 0;
            loaded_locale = candidate;
        }
        /* Some compilers use STUR directly through TP instead of first
         * materializing struct pthread.  Require the same signed field as
         * the load, the X0 locale argument, and preserved TP provenance. */
        if (tp_reg >= 0 && (insn & 0xffe00c1fu) == 0xf8000000u &&
            aarch64_decode_ldur64_signed(
                insn | UINT32_C(0x00400000), tp_reg, &relative) &&
            relative + (int64_t)self_delta >= 0 &&
            relative + (int64_t)self_delta < MUSL_THREAD_PROBE_LIMIT &&
            aarch64_musl_registers_preserved(
                code, tp_ready, i, UINT32_C(1) << (unsigned int)tp_reg)) {
            size_t candidate = (size_t)(relative + (int64_t)self_delta);

            if (stored_locale != SIZE_MAX && stored_locale != candidate)
                return 0;
            stored_locale = candidate;
        }
        if (tp_reg >= 0 && self_reg < 0) {
            int64_t delta;

            for (int rd = 0; rd < 31; rd++) {
                if (aarch64_decode_addsub_imm(insn, tp_reg, rd, &delta) &&
                    delta == -(int64_t)self_delta && rd != 0 &&
                    aarch64_musl_no_control_flow(
                        code, tp_ready, i) &&
                    aarch64_musl_registers_preserved(
                        code, tp_ready, i,
                        UINT32_C(1) << (unsigned int)tp_reg)) {
                    self_reg = rd;
                    self_ready = i + 4;
                    break;
                }
            }
        }

        unsigned int rt;
        unsigned int rn;
        size_t off;

        /* Older compiler output first derives struct pthread from TP and
         * then loads the old locale through that same register.  This is
         * equivalent to the direct signed TP-relative load above only when
         * the TP-to-self path is linear, the self register is still live,
         * and every observed load/store offset agrees. */
        if (self_reg >= 0 &&
            aarch64_decode_ldrstr64_unsigned(
                insn, 1, &rt, &rn, &off) &&
            rn == (unsigned int)self_reg &&
            off < MUSL_THREAD_PROBE_LIMIT &&
            aarch64_musl_no_control_flow(code, self_ready, i) &&
            aarch64_musl_registers_preserved(
                code, self_ready, i,
                UINT32_C(1) << (unsigned int)self_reg)) {
            if (loaded_locale != SIZE_MAX && loaded_locale != off)
                return 0;
            loaded_locale = off;
        }

        if (self_reg >= 0 &&
            aarch64_decode_ldrstr64_unsigned(
                insn, 0, &rt, &rn, &off) &&
            rn == (unsigned int)self_reg && rt == 0 &&
            off < MUSL_THREAD_PROBE_LIMIT &&
            aarch64_musl_registers_preserved(
                code, self_ready, i,
                UINT32_C(1) << (unsigned int)self_reg)) {
            if (stored_locale != SIZE_MAX && stored_locale != off)
                return 0;
            stored_locale = off;
        }

        unsigned int page_reg;
        uintptr_t page;

        if (!aarch64_decode_musl_adrp((uintptr_t)(code + i), insn,
                                      &page_reg, &page))
            continue;
        for (size_t j = i + 4; j + 4 <= len; j += 4) {
            unsigned int rd;
            uintptr_t address;

            if (!aarch64_decode_add_address(
                    read_u32_le(code + j), page_reg, page, &rd,
                    &address))
                continue;
            if (address < libc_obj->base ||
                !loaded_obj_contains(libc_obj, address,
                                     sizeof(uintptr_t)))
                continue;
            if (!global)
                global = address;
            if (global != address)
                return 0;
            global_uses++;
        }
    }
    if (tp_reg < 0 || loaded_locale == SIZE_MAX ||
        loaded_locale != stored_locale || !global || global_uses < 2)
        return 0;
    *locale_out = loaded_locale;
    *global_out = global;
    return 1;
}

static int decode_aarch64_musl_copy_tls_contract(
    const struct loaded_obj *libc_obj, uintptr_t address,
    uintptr_t libc_base, size_t *pthread_size_out, size_t *dtv_out,
    uintptr_t *tls_head_out, uintptr_t *tls_size_out,
    uintptr_t *tls_align_out, uintptr_t *tls_cnt_out)
{
    const uint8_t *code = (const uint8_t *)address;
    const size_t len = 192;
    unsigned int libc_reg = 31;
    unsigned int module_reg = 31;
    unsigned int pthread_reg = 31;
    size_t pthread_size = 0;
    size_t dtv = SIZE_MAX;
    unsigned int libc_pairs = 0;
    unsigned int module_fields = 0;
    int saw_return = 0;
    int saw_pthread_advance = 0;
    uintptr_t tls_head = 0;
    uintptr_t tls_size = 0;
    uintptr_t tls_align = 0;
    uintptr_t tls_cnt = 0;

    if (!musl_target_executable_address(libc_obj, address, len))
        return 0;
    for (size_t i = 0; i + 4 <= len; i += 4) {
        uint32_t insn = read_u32_le(code + i);

        if (insn == 0xd65f03c0u)
            saw_return = 1;

        /* MOVN Xd,#(size-1) is the canonical materialization of -size. */
        if ((insn & 0xff800000u) == 0x92800000u &&
            ((insn >> 21) & 3) == 0) {
            size_t candidate = ((insn >> 5) & 0xffff) + 1;

            if (candidate > 0 && candidate < MUSL_THREAD_PROBE_LIMIT) {
                if (pthread_size && pthread_size != candidate)
                    return 0;
                pthread_size = candidate;
            }
        }

        unsigned int page_reg;
        uintptr_t page;

        if (aarch64_decode_musl_adrp((uintptr_t)(code + i), insn,
                                     &page_reg, &page)) {
            for (size_t j = i + 4; j + 4 <= len && j <= i + 32;
                 j += 4) {
                unsigned int rd;
                uintptr_t target;

                if (aarch64_decode_add_address(
                        read_u32_le(code + j), page_reg, page, &rd,
                        &target) && target == libc_base)
                    libc_reg = rd;
            }
        }

        unsigned int rt;
        unsigned int rt2;
        unsigned int rn;
        size_t off;

        if (libc_reg != 31 &&
            aarch64_decode_ldp64_offset(
                insn, 1, &rt, &rt2, &rn, &off) && rn == libc_reg) {
            if (off == g_musl_layout->libc_tls_head) {
                if (libc_base > UINTPTR_MAX - off - sizeof(uintptr_t))
                    return 0;
                if (module_reg != 31 && module_reg != rt)
                    return 0;
                module_reg = rt;
                tls_head = libc_base + off;
                tls_size = tls_head + sizeof(uintptr_t);
                libc_pairs |= 1u;
            } else if (off == g_musl_layout->libc_tls_align) {
                if (libc_base > UINTPTR_MAX - off - sizeof(uintptr_t))
                    return 0;
                /* LDP covers align and cnt as a single proven pair. */
                tls_align = libc_base + off;
                tls_cnt = tls_align + sizeof(uintptr_t);
                libc_pairs |= 6u;
            }
        }
        if (libc_reg != 31 &&
            aarch64_decode_ldrstr64_unsigned(
                insn, 1, &rt, &rn, &off) && rn == libc_reg) {
            if (libc_base > UINTPTR_MAX - off)
                return 0;
            if (off == g_musl_layout->libc_tls_align) {
                tls_align = libc_base + off;
                libc_pairs |= 2u;
            } else if (off == g_musl_layout->libc_tls_cnt) {
                tls_cnt = libc_base + off;
                libc_pairs |= 4u;
            }
        }

        if (module_reg != 31) {
            if (aarch64_decode_ldrstr64_unsigned(
                    insn, 1, &rt, &rn, &off) && rn == module_reg) {
                if (off == MUSL_TLS_MODULE_NEXT_OFF)
                    module_fields |= 1u;
                else if (off == MUSL_TLS_MODULE_IMAGE_OFF)
                    module_fields |= 2u;
                else if (off == MUSL_TLS_MODULE_LEN_OFF)
                    module_fields |= 4u;
                else if (off == MUSL_TLS_MODULE_OFFSET_OFF)
                    module_fields |= 8u;
            }
            if (aarch64_decode_ldp64_offset(
                    insn, 1, &rt, &rt2, &rn, &off) &&
                rn == module_reg && off == MUSL_TLS_MODULE_IMAGE_OFF)
                module_fields |= 6u;
        }

        /* copy_tls returns the new pthread in X0 after advancing its working
         * pointer by exactly sizeof(struct pthread). */
        if (pthread_size && (insn & 0xffc00000u) == 0x91000000u &&
            ((insn >> 5) & 0x1f) != 31 &&
            (((insn >> 10) & 0xfff) << (((insn >> 22) & 1) ? 12 : 0)) ==
                pthread_size) {
            pthread_reg = (insn >> 5) & 0x1f;
            saw_pthread_advance = 1;
        }
        if (pthread_reg != 31 &&
            aarch64_decode_ldrstr64_unsigned(
                insn, 0, &rt, &rn, &off) && rn == pthread_reg &&
            off < MUSL_THREAD_PROBE_LIMIT)
            dtv = off;
    }
    if (!saw_return || !saw_pthread_advance || !pthread_size ||
        libc_pairs != 7u || module_fields != 0x0fu ||
        dtv == SIZE_MAX || !tls_head || !tls_size || !tls_align ||
        !tls_cnt)
        return 0;
    *pthread_size_out = pthread_size;
    *dtv_out = dtv;
    *tls_head_out = tls_head;
    *tls_size_out = tls_size;
    *tls_align_out = tls_align;
    *tls_cnt_out = tls_cnt;
    return 1;
}

/* musl's AArch64 __clone wrapper moves the call site's X6 into Linux's X4
 * clone ctid argument before issuing SYS_clone.  Requiring this assembly
 * prefix binds the hidden writable global below to kernel clear-child-tid
 * ownership, rather than to an arbitrary sixth helper argument. */
static int aarch64_musl_clone_wrapper(
    const struct loaded_obj *libc_obj, uintptr_t address)
{
    static const uint32_t prefix[] = {
        UINT32_C(0x927cec21), /* and x1,x1,#-16 */
        UINT32_C(0xa9bf0c20), /* stp x0,x3,[x1,#-16]! */
        UINT32_C(0x2a0203e0), /* mov w0,w2 (flags) */
        UINT32_C(0xaa0403e2), /* mov x2,x4 (ptid) */
        UINT32_C(0xaa0503e3), /* mov x3,x5 (TLS) */
        UINT32_C(0xaa0603e4), /* mov x4,x6 (ctid) */
        UINT32_C(0xd2801b88), /* mov x8,#SYS_clone */
        UINT32_C(0xd4000001), /* svc #0 */
    };
    const uint8_t *code = (const uint8_t *)address;
    size_t offset = 0;

    if (!musl_target_executable_address(
            libc_obj, address, sizeof(prefix) + sizeof(uint32_t)))
        return 0;
    if ((read_u32_le(code) & UINT32_C(0xffffff3f)) ==
        UINT32_C(0xd503241f)) /* BTI */
        offset = sizeof(uint32_t);
    return musl_target_executable_address(
               libc_obj, address + offset, sizeof(prefix)) &&
           memcmp(code + offset, prefix, sizeof(prefix)) == 0;
}

static int aarch64_musl_clone_add(
    uint32_t insn, unsigned int new_reg, unsigned int destination,
    size_t expected)
{
    size_t addend;

    if ((insn & UINT32_C(0xff000000)) != UINT32_C(0x91000000) ||
        ((insn >> 5) & 0x1f) != new_reg ||
        (insn & 0x1f) != destination)
        return 0;
    addend = (insn >> 10) & 0xfff;
    if ((insn >> 22) & 1)
        addend <<= 12;
    return addend == expected;
}

static int decode_aarch64_musl_clone_ctid(
    const struct loaded_obj *libc_obj, const uint8_t *code, size_t len,
    unsigned int new_reg, size_t pthread_size, size_t tid_offset,
    uintptr_t *ctid_out)
{
    uintptr_t matched = 0;
    unsigned int matching_calls = 0;

    for (size_t call = 0; call + 4 <= len; call += 4) {
        uintptr_t target;
        size_t begin;
        unsigned int flag_pairs = 0;
        unsigned int tls_adds = 0;
        unsigned int ptid_adds = 0;
        uintptr_t call_ctid = 0;
        unsigned int ctid_addresses = 0;

        if (!aarch64_direct_call_target(code, len, call, &target) ||
            !aarch64_musl_clone_wrapper(libc_obj, target))
            continue;
        begin = call > 160 ? call - 160 : 0;

        for (size_t low = begin; low + 4 <= call; low += 4) {
            uint32_t low_insn = read_u32_le(code + low);

            if ((low_insn & UINT32_C(0xff80001f)) !=
                    UINT32_C(0x52800002) ||
                ((low_insn >> 21) & 3) != 0 ||
                ((low_insn >> 5) & 0xffff) !=
                    (MUSL_PTHREAD_CLONE_FLAGS & 0xffff))
                continue;
            for (size_t high = low + 4;
                 high + 4 <= call && high <= low + 64; high += 4) {
                uint32_t high_insn = read_u32_le(code + high);

                if ((high_insn & UINT32_C(0xff80001f)) !=
                        UINT32_C(0x72800002) ||
                    ((high_insn >> 21) & 3) != 1 ||
                    ((high_insn >> 5) & 0xffff) !=
                        (MUSL_PTHREAD_CLONE_FLAGS >> 16) ||
                    !aarch64_musl_no_control_flow(
                        code, low + 4, high) ||
                    !aarch64_musl_registers_preserved(
                        code, low + 4, high, UINT32_C(1) << 2) ||
                    !aarch64_musl_no_control_flow(
                        code, high + 4, call) ||
                    !aarch64_musl_registers_preserved(
                        code, high + 4, call, UINT32_C(1) << 2))
                    continue;
                flag_pairs++;
            }
        }

        for (size_t i = begin; i + 4 <= call; i += 4) {
            uint32_t insn = read_u32_le(code + i);

            if (aarch64_musl_clone_add(
                    insn, new_reg, 5, pthread_size) &&
                aarch64_musl_no_control_flow(code, i + 4, call) &&
                aarch64_musl_registers_preserved(
                    code, i + 4, call, UINT32_C(1) << 5))
                tls_adds++;
            if (aarch64_musl_clone_add(
                    insn, new_reg, 4, tid_offset) &&
                aarch64_musl_no_control_flow(code, i + 4, call) &&
                aarch64_musl_registers_preserved(
                    code, i + 4, call, UINT32_C(1) << 4))
                ptid_adds++;

            unsigned int page_reg;
            uintptr_t page;

            if (!aarch64_decode_musl_adrp(
                    (uintptr_t)(code + i), insn, &page_reg, &page))
                continue;
            for (size_t add = i + 4;
                 add + 4 <= call && add <= i + 64; add += 4) {
                unsigned int address_reg;
                uintptr_t address;

                if (!aarch64_decode_add_address(
                        read_u32_le(code + add), page_reg, page,
                        &address_reg, &address) || address_reg != 6 ||
                    !aarch64_musl_no_control_flow(code, i + 4, add) ||
                    !aarch64_musl_registers_preserved(
                        code, i + 4, add,
                        UINT32_C(1) << page_reg) ||
                    !aarch64_musl_no_control_flow(
                        code, add + 4, call) ||
                    !aarch64_musl_registers_preserved(
                        code, add + 4, call, UINT32_C(1) << 6) ||
                    !musl_target_writable_clear_tid(libc_obj, address))
                    continue;
                if (call_ctid && call_ctid != address)
                    return 0;
                call_ctid = address;
                ctid_addresses++;
            }
        }
        if (flag_pairs != 1 || tls_adds != 1 || ptid_adds != 1 ||
            ctid_addresses != 1 || !call_ctid)
            continue;
        if (matched && matched != call_ctid)
            return 0;
        matched = call_ctid;
        matching_calls++;
    }
    if (matching_calls != 1 || !matched)
        return 0;
    *ctid_out = matched;
    return 1;
}

/* Recover a saved call result across bounded, decoded scheduling gaps.
 * Stores through X0 do not change it; another call, branch, or write does. */
static int aarch64_musl_call_result_register(
    const uint8_t *code, size_t len, size_t ready, unsigned int *reg_out)
{
    for (size_t pos = ready; pos + 4 <= len && pos < ready + 20; pos += 4) {
        uint32_t move = read_u32_le(code + pos);

        if ((move & 0xffffffe0u) == 0xaa0003e0u && (move & 31) != 31 &&
            aarch64_musl_no_control_flow(code, ready, pos) &&
            aarch64_musl_registers_preserved(code, ready, pos, 1u)) {
            *reg_out = move & 31;
            return 1;
        }
    }
    return 0;
}

static int decode_aarch64_musl_pthread_geometry(
    const struct loaded_obj *libc_obj, const uint8_t *create,
    size_t create_len, const uint8_t *exit_code, size_t exit_len,
    uintptr_t libc_base, uintptr_t global_locale, size_t canary_offset,
    size_t locale_offset, uintptr_t *copy_tls_out,
    size_t *pthread_size_out, size_t *dtv_out, size_t *prev_out,
    size_t *next_out, size_t *sysinfo_out, size_t *robust_out,
    size_t tid_offset, uintptr_t *thread_list_lock_out,
    uintptr_t *tls_head_out, uintptr_t *tls_size_out,
    uintptr_t *tls_align_out, uintptr_t *tls_cnt_out)
{
    uintptr_t copy_tls = 0;
    size_t pthread_size = 0;
    size_t dtv = 0;
    unsigned int copy_candidates = 0;
    unsigned int new_reg = 31;
    int self_store = 0;
    int robust_self_link = 0;
    int canary_copy = 0;
    int sysinfo_copy = 0;
    int locale_store = 0;
    int create_list = 0;
    int exit_list = 0;
    int exit_robust = 0;
    size_t prev = SIZE_MAX;
    size_t next = SIZE_MAX;
    size_t sysinfo = SIZE_MAX;
    size_t robust = SIZE_MAX;

    for (size_t i = 0; i + 4 <= create_len; i += 4) {
        uintptr_t target;

        if (!aarch64_direct_call_target(create, create_len, i, &target) ||
            !musl_target_executable_address(libc_obj, target, 1))
            continue;
        size_t candidate_size;
        size_t candidate_dtv;

        if (!decode_aarch64_musl_copy_tls_contract(
                libc_obj, target, libc_base, &candidate_size,
                &candidate_dtv, tls_head_out, tls_size_out,
                tls_align_out, tls_cnt_out))
            continue;
        if (!aarch64_musl_call_result_register(
                create, create_len, i + 4, &new_reg))
            return 0;
        copy_tls = target;
        pthread_size = candidate_size;
        dtv = candidate_dtv;
        copy_candidates++;
    }
    if (copy_candidates != 1 || new_reg == 31) {
        ldr_dbg_hex("[loader] musl contract: copy_tls candidates=", copy_candidates);
        return 0;
    }
    if (!decode_aarch64_musl_clone_ctid(
            libc_obj, create, create_len, new_reg, pthread_size,
            tid_offset, thread_list_lock_out)) {
        ldr_dbg("[loader] musl contract: clone child-TID decoder failed\n");
        return 0;
    }

    for (size_t i = 0; i + 4 <= create_len; i += 4) {
        uint32_t insn = read_u32_le(create + i);
        unsigned int rt;
        unsigned int rt2;
        unsigned int rn;
        size_t off;

        if (aarch64_decode_ldrstr64_unsigned(
                insn, 0, &rt, &rn, &off) && rn == new_reg &&
            rt == new_reg && off == 0)
            self_store = 1;

        if (aarch64_decode_ldp64_offset(
                insn, 0, &rt, &rt2, &rn, &off) && rn == new_reg &&
            off == g_musl_layout->thread_prev &&
            g_musl_layout->thread_next == off + sizeof(uintptr_t)) {
            create_list++;
            prev = off;
            next = off + sizeof(uintptr_t);
        }
        if (aarch64_decode_ldrstr64_unsigned(
                insn, 0, &rt, &rn, &off) && rt == new_reg &&
            (off == g_musl_layout->thread_prev ||
             off == g_musl_layout->thread_next))
            create_list++;

        if ((insn & 0xffc00000u) == 0x91000000u &&
            ((insn >> 5) & 0x1f) == new_reg) {
            size_t addend = (insn >> 10) & 0xfff;
            unsigned int address_reg = insn & 0x1f;

            if ((insn >> 22) & 1)
                addend <<= 12;
            if (addend == g_musl_layout->thread_robust) {
                for (size_t j = i + 4;
                     j + 4 <= create_len && j <= i + 20; j += 4) {
                    if (aarch64_decode_ldrstr64_unsigned(
                            read_u32_le(create + j), 0, &rt, &rn,
                            &off) && rn == new_reg &&
                        rt == address_reg && off == addend) {
                        robust_self_link = 1;
                        robust = addend;
                    }
                }
            }
        }

        if (aarch64_decode_ldrstr64_unsigned(
                insn, 1, &rt, &rn, &off) && rn != new_reg &&
            (off == canary_offset ||
             off == g_musl_layout->thread_sysinfo)) {
            for (size_t j = i + 4;
                 j + 4 <= create_len && j <= i + 16; j += 4) {
                unsigned int store_rt;
                unsigned int store_rn;
                size_t store_off;

                if (!aarch64_decode_ldrstr64_unsigned(
                        read_u32_le(create + j), 0, &store_rt,
                        &store_rn, &store_off) || store_rn != new_reg ||
                    store_rt != rt || store_off != off)
                    continue;
                if (off == canary_offset)
                    canary_copy = 1;
                else {
                    sysinfo_copy = 1;
                    sysinfo = off;
                }
            }
        }

        unsigned int page_reg;
        uintptr_t page;
        if (aarch64_decode_musl_adrp((uintptr_t)(create + i), insn,
                                     &page_reg, &page)) {
            for (size_t j = i + 4;
                 j + 4 <= create_len && j <= i + 16; j += 4) {
                unsigned int address_reg;
                uintptr_t address;

                if (!aarch64_decode_add_address(
                        read_u32_le(create + j), page_reg, page,
                        &address_reg, &address) ||
                    address != global_locale)
                    continue;
                for (size_t k = j + 4;
                     k + 4 <= create_len && k <= j + 40; k += 4)
                    if (aarch64_decode_ldrstr64_unsigned(
                            read_u32_le(create + k), 0, &rt, &rn,
                            &off) && rn == new_reg &&
                        rt == address_reg &&
                        off == locale_offset)
                        locale_store = 1;
            }
        }
    }

    for (size_t i = 0; i + 4 <= exit_len; i += 4) {
        uint32_t insn = read_u32_le(exit_code + i);
        unsigned int rt;
        unsigned int rt2;
        unsigned int rn;
        size_t off;

        if (aarch64_decode_ldp64_offset(
                insn, 1, &rt, &rt2, &rn, &off) &&
            off == g_musl_layout->thread_prev &&
            g_musl_layout->thread_next == off + sizeof(uintptr_t))
            exit_list++;
        if (aarch64_decode_ldrstr64_unsigned(
                insn, 1, &rt, &rn, &off) &&
            (off == g_musl_layout->thread_prev ||
             off == g_musl_layout->thread_next))
            exit_list++;
        if ((insn & 0xffc00000u) == 0x91000000u &&
            ((insn >> 10) & 0xfff) ==
                g_musl_layout->thread_robust)
            exit_robust = 1;
        if (aarch64_decode_ldrstr64_unsigned(
                insn, 1, &rt, &rn, &off) &&
            off == g_musl_layout->thread_robust)
            exit_robust = 1;
    }

    if (!self_store || !robust_self_link || !canary_copy ||
        !sysinfo_copy || !locale_store || create_list < 2 ||
        exit_list < 2 || !exit_robust || prev == SIZE_MAX ||
        next == SIZE_MAX || sysinfo == SIZE_MAX || robust == SIZE_MAX) {
        ldr_dbg_hex("[loader] musl contract: pthread evidence=",
                    self_store | (robust_self_link << 1) | (canary_copy << 2) |
                    (sysinfo_copy << 3) | (locale_store << 4) |
                    ((create_list >= 2) << 5) | ((exit_list >= 2) << 6) |
                    (exit_robust << 7));
        return 0;
    }
    *copy_tls_out = copy_tls;
    *pthread_size_out = pthread_size;
    *dtv_out = dtv;
    *prev_out = prev;
    *next_out = next;
    *sysinfo_out = sysinfo;
    *robust_out = robust;
    return 1;
}

static int decode_aarch64_musl_libc_addr(const struct loaded_obj *libc_obj,
                                         const uint8_t *code, size_t len,
                                         uintptr_t *addr_out,
                                         uintptr_t *can_do_out,
                                         size_t *flag_width_out)
{
    for (size_t i = 0; i + 4 <= len; i += 4) {
        unsigned int page_reg;
        uintptr_t page;

        if (!aarch64_decode_musl_adrp((uintptr_t)(code + i),
                                      read_u32_le(code + i),
                                      &page_reg, &page))
            continue;
        for (size_t j = i + 4; j + 4 <= len && j <= i + 64; j += 4) {
            uint32_t load = read_u32_le(code + j);
            uintptr_t first;

            if ((load & 0xffc00000u) != 0x39400000u ||
                ((load >> 5) & 0x1f) != page_reg)
                continue;
            first = page + ((load >> 10) & 0xfff);
            if (first < libc_obj->base +
                        g_musl_layout->libc_can_do_threads)
                continue;
            uintptr_t candidate =
                first - g_musl_layout->libc_can_do_threads;

            for (size_t k = j + 4; k + 8 <= len && k <= j + 96; k += 4) {
                uint32_t add = read_u32_le(code + k);
                unsigned int base_reg;
                uint64_t addend;

                if ((add & 0xff000000u) != 0x91000000u ||
                    ((add >> 5) & 0x1f) != page_reg)
                    continue;
                base_reg = add & 0x1f;
                addend = (add >> 10) & 0xfff;
                if ((add >> 22) & 1)
                    addend <<= 12;
                if (page + addend != candidate)
                    continue;
                /* pthread_create may finish its argument setup between the
                 * address calculation and the threaded flag load (musl
                 * 1.2.5 AArch64 places the load 32 bytes later). */
                for (size_t m = k + 4; m + 4 <= len && m <= k + 48;
                     m += 4) {
                    uint32_t second = read_u32_le(code + m);
                    void *checked;

                    if ((second & 0xffc00000u) != 0x39400000u ||
                        ((second >> 5) & 0x1f) != base_reg ||
                        ((second >> 10) & 0xfff) !=
                            g_musl_layout->libc_threaded ||
                        candidate < libc_obj->base ||
                        candidate - libc_obj->base > INT64_MAX ||
                        !loaded_obj_signed_offset_pointer(
                            libc_obj,
                            (int64_t)(candidate - libc_obj->base),
                            g_musl_layout->libc_size, PF_W, &checked))
                        continue;
                    *addr_out = (uintptr_t)checked;
                    *can_do_out = first;
                    *flag_width_out = sizeof(uint8_t);
                    return 1;
                }
            }
        }
    }
    return 0;
}
#endif

static int validate_musl_layout_from_target(const struct loaded_obj *libc_obj)
{
    uintptr_t init_libc = 0;
    uintptr_t global_locale = 0;
    size_t pthread_size = 0;
    size_t canary = 0;
    size_t target_dtv = 0;
    size_t target_prev = 0;
    size_t target_next = 0;
    size_t target_sysinfo = 0;
    size_t target_tid = 0;
    size_t target_errno = 0;
    size_t target_detach = 0;
    size_t target_robust = 0;
    size_t target_locale = 0;
    size_t target_self_delta = 0;
    uintptr_t target_can_do_threads = 0;
    uintptr_t target_thread_list_lock = 0;
    size_t target_flag_width = 0;
    uintptr_t target_tls_head = 0;
    uintptr_t target_tls_size = 0;
    uintptr_t target_tls_align = 0;
    uintptr_t target_tls_cnt = 0;

    g_musl_target_tid_known = 0;
    g_musl_target_errno_known = 0;
    g_musl_target_detach_known = 0;
    g_musl_target_detach_value = g_musl_layout->detach_initial;
#if defined(__x86_64__)
    uint64_t addr;
    size_t off;
    const uint8_t *create_code;
    const uint8_t *exit_code;
    const uint8_t *function_code;
    size_t create_len;
    size_t exit_len;
    size_t function_len;
    uintptr_t copy_tls;

    if (!libc_obj)
        return 0;

    if (!musl_defined_function_view(libc_obj, "pthread_self", 9, 32,
                                    &function_code, &function_len) ||
        !decode_x86_64_musl_self_delta(function_code, function_len,
                                       &target_self_delta) ||
        target_self_delta != g_musl_layout->tp_self_delta) {
        ldr_dbg("[loader] musl target mismatch: pthread self\n");
        return 0;
    }

    if (!decode_x86_64_musl_init_libc(libc_obj, &init_libc, &canary) ||
        canary != g_musl_layout->thread_canary) {
        ldr_dbg_hex("[loader] musl contract: decoded canary=", canary);
        ldr_dbg_hex("[loader] musl contract: expected canary=",
                    g_musl_layout->thread_canary);
        ldr_dbg("[loader] musl target mismatch: libc/SSP startup\n");
        return 0;
    }

    addr = musl_defined_function_addr(libc_obj, "__errno_location");
    if (addr && loaded_obj_contains(libc_obj, (uintptr_t)addr, 32) &&
        decode_x86_64_musl_errno_offset((const uint8_t *)(uintptr_t)addr, 32,
                                        &off) &&
        off == g_musl_layout->thread_errno) {
        g_musl_target_errno_known = 1;
        target_errno = off;
    } else {
        ldr_dbg("[loader] musl profile mismatch: errno\n");
        return 0;
    }

    addr = musl_defined_function_addr(libc_obj, "__tls_get_addr");
    if (addr && loaded_obj_contains(libc_obj, (uintptr_t)addr, 48) &&
        decode_x86_64_musl_dtv_offset((const uint8_t *)(uintptr_t)addr, 48,
                                      &off) &&
        off == g_musl_layout->thread_dtv) {
        target_dtv = off;
    } else {
        ldr_dbg("[loader] musl profile mismatch: DTV\n");
        return 0;
    }

    addr = musl_defined_function_addr(libc_obj, "pthread_kill");
    if (addr && loaded_obj_contains(libc_obj, (uintptr_t)addr, 128) &&
        decode_x86_64_musl_tid_offset((const uint8_t *)(uintptr_t)addr,
                                      128, &off) &&
        off == g_musl_layout->thread_tid) {
        g_musl_target_tid_known = 1;
        target_tid = off;
    } else {
        ldr_dbg("[loader] musl profile mismatch: tid\n");
        return 0;
    }

    addr = musl_defined_function_addr(libc_obj, "pthread_detach");
    if (addr && loaded_obj_contains(libc_obj, (uintptr_t)addr, 128) &&
        decode_x86_64_musl_detach_offset((const uint8_t *)(uintptr_t)addr,
                                         128, &off,
                                         &g_musl_target_detach_value) &&
        off == g_musl_layout->thread_detach &&
        g_musl_target_detach_value == g_musl_layout->detach_initial) {
        g_musl_target_detach_known = 1;
        target_detach = off;
    } else {
        ldr_dbg("[loader] musl profile mismatch: detach state\n");
        return 0;
    }

    if (!musl_defined_function_view(libc_obj, "pthread_create", 256, 2048,
                                    &create_code, &create_len) ||
        !decode_x86_64_musl_libc_addr(
            libc_obj, create_code, create_len,
            &g_musl_libc_addr, &target_can_do_threads,
            &target_flag_width))
    {
        ldr_dbg("[loader] musl profile mismatch: libc state base\n");
        return 0;
    }

    if (!musl_defined_function_view(libc_obj, "uselocale", 24, 128,
                                    &function_code, &function_len) ||
        !decode_x86_64_musl_uselocale(
            function_code, function_len, &target_locale,
            &global_locale) ||
        target_locale != g_musl_layout->thread_locale ||
        global_locale !=
            g_musl_libc_addr + g_musl_layout->libc_global_locale) {
        ldr_dbg("[loader] musl target mismatch: locale contract\n");
        return 0;
    }

    if (!musl_defined_function_view(libc_obj, "pthread_exit", 256, 1024,
                                    &exit_code, &exit_len) ||
        !decode_x86_64_musl_pthread_geometry(
            libc_obj, create_code, create_len, exit_code, exit_len,
            g_musl_libc_addr, canary, target_tid,
            &copy_tls, &pthread_size,
            &target_prev, &target_next, &target_sysinfo,
            &target_robust, &target_thread_list_lock,
            &target_tls_head, &target_tls_size,
            &target_tls_align, &target_tls_cnt)) {
        ldr_dbg("[loader] musl target mismatch: pthread/TLS geometry\n");
        return 0;
    }
    (void)copy_tls;
    if (pthread_size != g_musl_layout->pthread_size ||
        target_prev != g_musl_layout->thread_prev ||
        target_next != g_musl_layout->thread_next ||
        target_sysinfo != g_musl_layout->thread_sysinfo ||
        target_robust != g_musl_layout->thread_robust) {
        ldr_dbg("[loader] musl target mismatch: pthread layout profile\n");
        return 0;
    }
#elif defined(__aarch64__)
    uint64_t addr;
    size_t off;
    const uint8_t *create_code;
    const uint8_t *exit_code;
    const uint8_t *function_code;
    size_t create_len;
    size_t exit_len;
    size_t function_len;
    uintptr_t copy_tls;
    size_t copy_dtv;

    if (!libc_obj)
        return 0;

    addr = musl_defined_function_addr(libc_obj, "pthread_self");
    if (addr && loaded_obj_contains(libc_obj, (uintptr_t)addr, 32) &&
        decode_aarch64_musl_self_delta((const uint8_t *)(uintptr_t)addr, 32,
                                       &off) &&
        off == g_musl_layout->tp_self_delta) {
        target_self_delta = off;
    } else {
        ldr_dbg("[loader] musl profile mismatch: pthread self\n");
        return 0;
    }

    if (!decode_aarch64_musl_init_libc(
            libc_obj, target_self_delta, &init_libc, &canary) ||
        canary != g_musl_layout->thread_canary) {
        ldr_dbg("[loader] musl target mismatch: libc/SSP startup\n");
        return 0;
    }

    addr = musl_defined_function_addr(libc_obj, "__errno_location");
    if (addr && loaded_obj_contains(libc_obj, (uintptr_t)addr, 32)) {
        int64_t tp_rel;

        if (decode_aarch64_musl_tp_relative((const uint8_t *)(uintptr_t)addr, 32, &tp_rel) &&
            tp_rel + (int64_t)target_self_delta >= 0 &&
            tp_rel + (int64_t)target_self_delta < MUSL_THREAD_PROBE_LIMIT) {
            off = (size_t)(tp_rel + (int64_t)target_self_delta);
            if (off == g_musl_layout->thread_errno)
                g_musl_target_errno_known = 1;
        }
    }
    if (!g_musl_target_errno_known) {
        ldr_dbg("[loader] musl profile mismatch: errno\n");
        return 0;
    }
    target_errno = off;

    addr = musl_defined_function_addr(libc_obj, "__tls_get_addr");
    if (addr && loaded_obj_contains(libc_obj, (uintptr_t)addr, 64) &&
        decode_aarch64_musl_dtv_offset((const uint8_t *)(uintptr_t)addr, 64,
                                       target_self_delta, &off) &&
        off == g_musl_layout->thread_dtv) {
        target_dtv = off;
    } else {
        ldr_dbg("[loader] musl profile mismatch: DTV\n");
        return 0;
    }

    addr = musl_defined_function_addr(libc_obj, "pthread_kill");
    if (addr && loaded_obj_contains(libc_obj, (uintptr_t)addr, 128) &&
        decode_aarch64_musl_tid_offset((const uint8_t *)(uintptr_t)addr,
                                       128, &off) &&
        off == g_musl_layout->thread_tid) {
        g_musl_target_tid_known = 1;
        target_tid = off;
    } else {
        ldr_dbg("[loader] musl profile mismatch: tid\n");
        return 0;
    }

    addr = musl_defined_function_addr(libc_obj, "pthread_detach");
    if (addr && loaded_obj_contains(libc_obj, (uintptr_t)addr, 128) &&
        decode_aarch64_musl_detach_offset((const uint8_t *)(uintptr_t)addr,
                                          128, &off,
                                          &g_musl_target_detach_value) &&
        off == g_musl_layout->thread_detach &&
        g_musl_target_detach_value == g_musl_layout->detach_initial) {
        g_musl_target_detach_known = 1;
        target_detach = off;
    } else {
        ldr_dbg("[loader] musl profile mismatch: detach state\n");
        return 0;
    }

    if (!musl_defined_function_view(libc_obj, "pthread_create", 256, 2048,
                                    &create_code, &create_len) ||
        !decode_aarch64_musl_libc_addr(
            libc_obj, create_code, create_len,
            &g_musl_libc_addr, &target_can_do_threads,
            &target_flag_width))
    {
        ldr_dbg("[loader] musl profile mismatch: libc state base\n");
        return 0;
    }

    if (!musl_defined_function_view(libc_obj, "uselocale", 24, 128,
                                    &function_code, &function_len) ||
        !decode_aarch64_musl_uselocale(
            libc_obj, function_code, function_len, target_self_delta,
            &target_locale, &global_locale) ||
        target_locale != g_musl_layout->thread_locale ||
        global_locale !=
            g_musl_libc_addr + g_musl_layout->libc_global_locale) {
        ldr_dbg("[loader] musl target mismatch: locale contract\n");
        return 0;
    }

    if (!musl_defined_function_view(libc_obj, "pthread_exit", 256, 1024,
                                    &exit_code, &exit_len) ||
        !decode_aarch64_musl_pthread_geometry(
            libc_obj, create_code, create_len, exit_code, exit_len,
            g_musl_libc_addr, global_locale, canary, target_locale,
            &copy_tls, &pthread_size, &copy_dtv, &target_prev,
            &target_next, &target_sysinfo, &target_robust, target_tid,
            &target_thread_list_lock,
            &target_tls_head, &target_tls_size, &target_tls_align,
            &target_tls_cnt) ||
        copy_dtv != target_dtv) {
        ldr_dbg("[loader] musl target mismatch: pthread/TLS geometry\n");
        return 0;
    }
    (void)copy_tls;
    if (pthread_size != g_musl_layout->pthread_size ||
        target_prev != g_musl_layout->thread_prev ||
        target_next != g_musl_layout->thread_next ||
        target_sysinfo != g_musl_layout->thread_sysinfo ||
        target_robust != g_musl_layout->thread_robust) {
        ldr_dbg("[loader] musl target mismatch: pthread layout profile\n");
        return 0;
    }
#else
    (void)libc_obj;
    return 0;
#endif
    if (!pthread_size || !global_locale || !target_thread_list_lock ||
        target_dtv + sizeof(uintptr_t) > pthread_size ||
        target_prev + sizeof(uintptr_t) > pthread_size ||
        target_next + sizeof(uintptr_t) > pthread_size ||
        target_sysinfo + sizeof(uintptr_t) > pthread_size ||
        canary + sizeof(uintptr_t) > pthread_size ||
        target_tid + sizeof(int) > pthread_size ||
        target_errno + sizeof(int) > pthread_size ||
        target_detach + sizeof(int) > pthread_size ||
        target_robust + sizeof(uintptr_t) > pthread_size ||
        target_locale + sizeof(uintptr_t) > pthread_size) {
        ldr_dbg("[loader] musl target mismatch: pthread field bounds\n");
        return 0;
    }
    {
        void *checked;
        uintptr_t contract_end;

        if (!g_musl_libc_addr ||
            !u64_add_checked(g_musl_libc_addr,
                             g_musl_layout->libc_size, &contract_end) ||
            contract_end <= g_musl_libc_addr ||
            g_musl_libc_addr < libc_obj->base ||
            g_musl_libc_addr - libc_obj->base > INT64_MAX ||
            !loaded_obj_signed_offset_pointer(
                libc_obj,
                (int64_t)(g_musl_libc_addr - libc_obj->base),
                g_musl_layout->libc_size, PF_W, &checked)) {
            ldr_dbg("[loader] musl target mismatch: libc state range\n");
            return 0;
        }
        if (global_locale < libc_obj->base ||
            global_locale - libc_obj->base > INT64_MAX ||
            !loaded_obj_signed_offset_pointer(
                libc_obj,
                (int64_t)(global_locale - libc_obj->base),
                sizeof(uintptr_t), PF_W, &checked)) {
            ldr_dbg("[loader] musl target mismatch: global locale range\n");
            return 0;
        }
    }
    g_musl_tp_self_delta = target_self_delta;
    g_musl_thread.dtv = target_dtv;
    g_musl_thread.prev = target_prev;
    g_musl_thread.next = target_next;
    g_musl_thread.sysinfo = target_sysinfo;
    g_musl_thread.tid = target_tid;
    g_musl_thread.errno_off = target_errno;
    g_musl_thread.detach_state = target_detach;
    g_musl_thread.robust_head = target_robust;
    g_musl_thread.locale = target_locale;
    g_musl_contract.pthread_size = pthread_size;
    g_musl_contract.canary = canary;
    g_musl_contract.thread_list_lock = target_thread_list_lock;
    g_musl_contract.global_locale = global_locale;
    g_musl_contract.libc_can_do_threads = target_can_do_threads;
    g_musl_contract.libc_tls_head = target_tls_head;
    g_musl_contract.libc_tls_size = target_tls_size;
    g_musl_contract.libc_tls_align = target_tls_align;
    g_musl_contract.libc_tls_cnt = target_tls_cnt;
    g_musl_contract.libc_flag_width = target_flag_width;
    g_target_musl_init_libc = (musl_init_libc_fn)init_libc;
    return 1;
}

static void reset_musl_target_contract_candidate(void)
{
    g_musl_libc_addr = 0;
    g_musl_tp_self_delta = 0;
    g_target_musl_init_libc = NULL;
    memset(&g_musl_thread, 0, sizeof(g_musl_thread));
    memset(&g_musl_contract, 0, sizeof(g_musl_contract));
    g_musl_target_tid_known = 0;
    g_musl_target_errno_known = 0;
    g_musl_target_detach_known = 0;
    g_musl_target_detach_value = 0;
}

static int initialize_musl_target_contract(struct loaded_obj *objs,
                                           int nobj)
{
    const struct loaded_obj *matched = NULL;

    g_target_musl_libc_obj = NULL;
    for (int i = 0; i < nobj; i++) {
        struct loaded_obj *candidate = &objs[i];

        if (!dl_object_is_visible(candidate) ||
            (candidate->flags & (LDR_FLAG_MAIN_EXE | LDR_FLAG_DATA)))
            continue;
        reset_musl_target_contract_candidate();
        if (!validate_musl_layout_from_target(candidate))
            continue;
        if (matched) {
            reset_musl_target_contract_candidate();
            ldr_dbg("[loader] musl target mismatch: ambiguous libc "
                    "contract\n");
            return 0;
        }
        matched = candidate;
    }
    if (!matched) {
        reset_musl_target_contract_candidate();
        return 0;
    }

    /* Candidate probing is intentionally destructive to transient decoder
     * output.  Re-run the sole match to publish only its proven contract. */
    reset_musl_target_contract_candidate();
    if (!validate_musl_layout_from_target(matched))
        return 0;
    g_target_musl_libc_obj = matched;
    return 1;
}

/* ---- dlopen support globals ------------------------------------------ */

/* Global object table — populated by loader_run, extended by my_dlopen. */
static struct loaded_obj g_all_objs[MAX_TOTAL_OBJS];
static int g_nobj;
static void *g_startup_lazy_plt_resolution_mapping;
static size_t g_startup_lazy_plt_resolution_mapping_size;
/* Unlike the live namespace, these startup dispatch records never grow or
 * change after publication. A completed PLT call can therefore inspect its
 * own once-state without reading a concurrently extended object/scope table. */
struct startup_lazy_plt_dispatch {
    struct lazy_plt_resolution *resolutions;
    size_t count;
    uintptr_t first_slot;
};
static struct startup_lazy_plt_dispatch
    g_startup_lazy_plt_dispatch[MAX_TOTAL_OBJS];
static volatile uint32_t g_startup_lazy_plt_dispatch_count;
static int g_global_scope_root = -1;
static uint16_t g_global_scope_indices[MAX_TOTAL_OBJS];
static uint16_t g_global_scope_count;

/* The static bootstrap keeps executing after target handoff: public loader
 * callbacks, VFS shims, and their unwind frames all live in its PT_LOADs.
 * Keep one introspection-only object outside g_all_objs so it can participate
 * in address/unwind APIs without entering target ELF lookup order, DT_NEEDED
 * scopes, constructor order, or TLS module numbering. */
static struct loaded_obj g_bootstrap_introspection_obj;
static const char g_bootstrap_introspection_name[] =
    "[dlfreeze direct loader]";
/* The bootstrap record is published after the startup-visible target graph.
 * Dormant traced objects and objects appended by later dlopen transactions
 * remain after that immutable boundary in every public graph view. */
static int g_bootstrap_publication_boundary;

static void lazy_plt_atfork_child_repair(
    uint32_t parent_process_id, uint32_t parent_tid,
    uint32_t child_process_id, uint32_t child_tid)
{
    uint64_t inherited_owner = LAZY_PLT_RESOLUTION_OWNER(
        parent_process_id, parent_tid);
    uint64_t child_owner = LAZY_PLT_RESOLUTION_OWNER(
        child_process_id, child_tid);

    if (child_process_id == 0 || child_tid == 0 ||
        child_owner == LAZY_PLT_RESOLUTION_DONE)
        loader_exit(127);
    for (int i = 0; i < g_nobj; i++) {
        struct loaded_obj *obj = &g_all_objs[i];

        if (!obj->lazy_plt_resolutions)
            continue;
        for (size_t j = 0; j < obj->jmprel_count; j++) {
            struct lazy_plt_resolution *resolution =
                &obj->lazy_plt_resolutions[j];
            uint64_t state = runtime_atomic_load64(&resolution->state);

            resolution->waiters = 0;
            if (state == 0 || state == LAZY_PLT_RESOLUTION_DONE)
                continue;
            if (parent_process_id != 0 && parent_tid != 0 &&
                state == inherited_owner) {
                runtime_atomic_store64(&resolution->state, child_owner);
            } else {
                resolution->resolver = 0;
                runtime_atomic_store64(&resolution->target, 0);
                runtime_atomic_store64(&resolution->state, 0);
            }
        }
    }
}

/* Immutable TLS metadata for modules published by the direct loader.  A native
 * __tls_get_addr does not enter the loader when the calling thread already
 * has a populated DTV slot; doing so here would put a syscall-based recursive
 * lock on every general/local-dynamic TLS access.  Objects are never unloaded,
 * so a module ID, TLS extent, and any startup-assigned TP-relative offset
 * become immutable at transaction publication.  The signed offset is retained
 * as a publication invariant and is written before the release-published
 * extent + 1.  It is not independent address authority: every fast lookup,
 * including a startup static-TLS module, must first admit the current thread's
 * DTV capacity and populated slot.  Missing slots, unpublished transaction
 * modules, and DTV growth continue through the serialized slow path below. */
struct runtime_tls_fast_entry {
    volatile uint64_t extent_plus_one;
    volatile uint64_t static_tpoff_bits;
};

static struct runtime_tls_fast_entry
    g_runtime_tls_fast[MAX_TOTAL_OBJS + 1];

/* glibc deliberately exposes the main executable as an empty name in its
 * public link_map and dl_iterate_phdr views.  musl exposes the executable
 * path there.  obj->name retains the path for identity, $ORIGIN, diagnostics,
 * and dladdr on both runtimes; argv[0] remains caller-owned process state. */
static const char *dl_public_object_name(const struct loaded_obj *obj)
{
    if (!obj)
        return "";
    if (!g_is_musl_runtime && (obj->flags & LDR_FLAG_MAIN_EXE))
        return "";
    return obj->name ? obj->name : "";
}

/* Rebuild the public link_map chain after an object scope is published.  The
 * link_map objects themselves never move; only their public next/prev links
 * change as append-only dlopen scopes become visible.  Callers hold the
 * runtime loader lock whenever target code can observe this chain. */
static void dl_refresh_public_link_maps(void)
{
    struct link_map *first = NULL;
    struct link_map *previous = NULL;
    int boundary = g_bootstrap_publication_boundary;

    if (boundary < 0 || boundary > g_nobj)
        loader_exit(127);
    for (int group = 0; group < 2; group++) {
        int begin = group == 0 ? 0 : boundary;
        int end = group == 0 ? boundary : g_nobj;

        for (int i = begin; i < end; i++) {
            struct loaded_obj *obj = &g_all_objs[i];
            struct link_map *map = &obj->public_link_map;

            map->l_addr = (ElfW(Addr))obj->base;
            map->l_name = (char *)(uintptr_t)dl_public_object_name(obj);
            map->l_ld = (ElfW(Dyn) *)(uintptr_t)obj->dynamic;
            map->l_next = NULL;
            map->l_prev = NULL;
            if (!obj->visible)
                continue;
            if (!first)
                first = map;
            map->l_prev = previous;
            if (previous)
                previous->l_next = map;
            previous = map;
        }
        if (group == 0 && g_bootstrap_introspection_obj.visible) {
            struct loaded_obj *obj = &g_bootstrap_introspection_obj;
            struct link_map *map = &obj->public_link_map;

            map->l_addr = (ElfW(Addr))obj->base;
            map->l_name = (char *)(uintptr_t)obj->name;
            map->l_ld = (ElfW(Dyn) *)(uintptr_t)obj->dynamic;
            map->l_next = NULL;
            map->l_prev = previous;
            if (!first)
                first = map;
            if (previous)
                previous->l_next = map;
            previous = map;
        }
    }
    g_public_r_debug.r_map = first;
}

static void dl_debug_publication_begin(int state)
{
    g_public_r_debug.r_state = state;
    dlfreeze_dl_debug_state();
}

static void dl_debug_publication_end(void)
{
    dl_refresh_public_link_maps();
    g_public_r_debug.r_state = RT_CONSISTENT;
    dlfreeze_dl_debug_state();
}

static int dl_object_is_visible(const struct loaded_obj *obj)
{
    return obj && obj->visible;
}

static int dl_flags_startup_mapped(uint32_t flags)
{
    if (flags & (LDR_FLAG_INTERP | LDR_FLAG_DATA))
        return 0;
    return !(flags & LDR_FLAG_DLOPEN) ||
           (flags & LDR_FLAG_DLOPEN_EARLY);
}

/* Per-object metadata for dlopen'd objects (used by protect_object) */
static struct dlfrz_lib_meta g_dl_metas[MAX_TOTAL_OBJS];

static int dl_object_table_index(const struct loaded_obj *obj, int nobj,
                                 int *index_out)
{
    uintptr_t address = (uintptr_t)obj;
    uintptr_t start = (uintptr_t)&g_all_objs[0];
    uintptr_t end;
    uintptr_t delta;

    if (!obj || nobj < 0 || nobj > MAX_TOTAL_OBJS)
        return 0;
    end = (uintptr_t)&g_all_objs[nobj];
    if (address < start || address >= end)
        return 0;
    delta = address - start;
    if (delta % sizeof(g_all_objs[0]) != 0)
        return 0;
    *index_out = (int)(delta / sizeof(g_all_objs[0]));
    return 1;
}

/* GNU PLT0 publishes a link_map pointer in GOT[1].  Keep that observable ABI
 * identity equal to the link_map returned by dlinfo/dladdr1, while recovering
 * the enclosing private object without dereferencing an untrusted token. */
static int dl_public_link_map_object(void *token, int nobj,
                                     struct loaded_obj **obj_out,
                                     int *index_out)
{
    uintptr_t address = (uintptr_t)token;
    const size_t offset = offsetof(struct loaded_obj, public_link_map);
    struct loaded_obj *obj;
    int index;

    if (!token || !obj_out || address < offset)
        return 0;
    obj = (struct loaded_obj *)(address - offset);
    if (!dl_object_table_index(obj, nobj, &index) ||
        token != (void *)(uintptr_t)&obj->public_link_map)
        return 0;
    *obj_out = obj;
    if (index_out)
        *index_out = index;
    return 1;
}

static int dl_add_dependency_edge(struct loaded_obj *requester,
                                  struct loaded_obj *dependency, int nobj,
                                  int first_loaded_as_dependency)
{
    int requester_index;
    int dependency_index;

    if (!dl_object_table_index(requester, nobj, &requester_index) ||
        !dl_object_table_index(dependency, nobj, &dependency_index))
        return -1;
    for (uint16_t i = 0; i < requester->needed_count; i++)
        if (requester->needed_indices[i] == (uint16_t)dependency_index)
            return 0;
    if (requester->needed_count >= MAX_TOTAL_OBJS)
        return -1;
    requester->needed_indices[requester->needed_count++] =
        (uint16_t)dependency_index;
    requester->lookup_scope_valid = 0;
    /* musl's needed_by identity is assigned only when an object is first
     * loaded as a dependency.  A later edge to an already-loaded shared
     * child must not change the native first-parent search ancestry. */
    if (first_loaded_as_dependency &&
        requester_index != dependency_index &&
        !(dependency->flags & LDR_FLAG_MAIN_EXE) &&
        !dependency->needed_by_valid) {
        dependency->needed_by_index = (uint16_t)requester_index;
        dependency->needed_by_valid = 1;
    }
    return 0;
}

static int dl_build_lookup_scope(struct loaded_obj *root, int nobj)
{
    uint8_t seen[MAX_TOTAL_OBJS];
    int root_index;
    uint16_t cursor = 0;

    if (!dl_object_table_index(root, nobj, &root_index))
        return -1;
    memset(seen, 0, sizeof(seen));
    root->lookup_scope_count = 1;
    root->lookup_scope_indices[0] = (uint16_t)root_index;
    seen[root_index] = 1;

    while (cursor < root->lookup_scope_count) {
        uint16_t current_index = root->lookup_scope_indices[cursor++];
        struct loaded_obj *current;

        if (current_index >= nobj)
            goto malformed;
        current = &g_all_objs[current_index];
        if (current->needed_count > MAX_TOTAL_OBJS)
            goto malformed;
        for (uint16_t i = 0; i < current->needed_count; i++) {
            uint16_t dependency_index = current->needed_indices[i];

            if (dependency_index >= nobj)
                goto malformed;
            if (seen[dependency_index])
                continue;
            if (root->lookup_scope_count >= MAX_TOTAL_OBJS)
                goto malformed;
            seen[dependency_index] = 1;
            root->lookup_scope_indices[root->lookup_scope_count++] =
                dependency_index;
        }
    }
    root->lookup_scope_valid = 1;
    return 0;

malformed:
    root->lookup_scope_count = 0;
    root->lookup_scope_valid = 0;
    return -1;
}

static int dl_set_relocation_scope_root(struct loaded_obj *obj,
                                        int root_index, int nobj)
{
    int index;

    if (!dl_object_table_index(obj, nobj, &index) || root_index < 0 ||
        root_index >= nobj)
        return -1;
    (void)index;
    obj->relocation_scope_root = (uint16_t)root_index;
    obj->relocation_scope_root_valid = 1;
    return 0;
}

static int dl_global_scope_contains(uint16_t index)
{
    for (uint16_t i = 0; i < g_global_scope_count; i++)
        if (g_global_scope_indices[i] == index)
            return 1;
    return 0;
}

static int dl_append_lookup_scope_to_global(struct loaded_obj *root,
                                            int nobj)
{
    uint8_t present[MAX_TOTAL_OBJS];
    uint16_t additional = 0;

    if (nobj <= 0 || nobj > MAX_TOTAL_OBJS ||
        g_global_scope_count > MAX_TOTAL_OBJS)
        return -1;
    if (!root->lookup_scope_valid && dl_build_lookup_scope(root, nobj) < 0)
        return -1;
    memset(present, 0, sizeof(present));
    for (uint16_t i = 0; i < g_global_scope_count; i++) {
        uint16_t index = g_global_scope_indices[i];

        if (index >= (uint16_t)nobj)
            return -1;
        present[index] = 1;
    }
    for (uint16_t i = 0; i < root->lookup_scope_count; i++) {
        uint16_t index = root->lookup_scope_indices[i];

        if (index >= (uint16_t)nobj)
            return -1;
        if (!present[index]) {
            present[index] = 1;
            additional++;
        }
    }
    if (additional > MAX_TOTAL_OBJS - g_global_scope_count)
        return -1;

    /* Re-seed the bitmap with the preexisting scope.  The second ordered
     * pass then appends each new object exactly once without repeated scans
     * of the growing global list. */
    memset(present, 0, sizeof(present));
    for (uint16_t i = 0; i < g_global_scope_count; i++)
        present[g_global_scope_indices[i]] = 1;
    for (uint16_t i = 0; i < root->lookup_scope_count; i++) {
        uint16_t index = root->lookup_scope_indices[i];

        if (present[index])
            continue;
        if (g_global_scope_count >= MAX_TOTAL_OBJS)
            return -1;
        present[index] = 1;
        g_global_scope_indices[g_global_scope_count++] = index;
    }
    return 0;
}

static int dl_append_index_to_global(uint16_t index, int nobj)
{
    if (index >= nobj)
        return -1;
    if (dl_global_scope_contains(index))
        return 0;
    if (g_global_scope_count >= MAX_TOTAL_OBJS)
        return -1;
    g_global_scope_indices[g_global_scope_count++] = index;
    return 0;
}

static int dl_append_root_scope_to_order(int root_index, int nobj,
                                         uint16_t *order,
                                         uint16_t *count,
                                         uint8_t *object_seen)
{
    struct loaded_obj *root;

    if (root_index < 0 || root_index >= nobj)
        return -1;
    root = &g_all_objs[root_index];
    if (!root->lookup_scope_valid && dl_build_lookup_scope(root, nobj) < 0)
        return -1;
    for (uint16_t i = 0; i < root->lookup_scope_count; i++) {
        uint16_t index = root->lookup_scope_indices[i];

        if (index >= nobj)
            return -1;
        if (object_seen[index])
            continue;
        if (*count >= MAX_TOTAL_OBJS)
            return -1;
        object_seen[index] = 1;
        order[(*count)++] = index;
    }
    return 0;
}

static int dl_build_root_lookup_order(int root_index, int nobj,
                                      uint16_t *order,
                                      uint16_t *count_out)
{
    uint8_t object_seen[MAX_TOTAL_OBJS];
    uint16_t count = 0;

    *count_out = 0;
    if (nobj <= 0 || nobj > MAX_TOTAL_OBJS)
        return -1;
    memset(object_seen, 0, sizeof(object_seen));
    for (uint16_t i = 0; i < g_global_scope_count; i++) {
        uint16_t index = g_global_scope_indices[i];

        if (index >= nobj)
            return -1;
        if (object_seen[index])
            continue;
        object_seen[index] = 1;
        order[count++] = index;
    }
    if (dl_append_root_scope_to_order(root_index, nobj, order, &count,
                                      object_seen) < 0)
        return -1;
    *count_out = count;
    return 0;
}

static int runtime_tls_template_valid(const struct loaded_obj *obj)
{
    uint64_t align;

    if (!obj || obj->tls.memsz == 0)
        return 0;
    align = obj->tls.align ? obj->tls.align : 1;
    if (obj->tls.filesz > obj->tls.memsz || obj->tls.memsz > SIZE_MAX ||
        obj->tls.vaddr > UINT64_MAX - obj->tls.memsz ||
        (align & (align - 1)) != 0 ||
        (obj->tls.filesz != 0 &&
         !loaded_obj_file_vaddr_pointer(obj, obj->tls.vaddr,
                                        (size_t)obj->tls.filesz, NULL)))
        return 0;
    return 1;
}

static int runtime_tls_mapping_size(const struct loaded_obj *obj,
                                    size_t *mapping_len_out)
{
    uint64_t align;
    uint64_t allocation_size;
    uint64_t map_len_u64;

    if (!runtime_tls_template_valid(obj))
        return 0;
    align = obj->tls.align ? obj->tls.align : 1;
    if (!u64_add_checked(obj->tls.memsz, align - 1, &allocation_size) ||
        !u64_align_up_checked(allocation_size, g_page_size, &map_len_u64) ||
        map_len_u64 == 0 || map_len_u64 > SIZE_MAX)
        return 0;
    *mapping_len_out = (size_t)map_len_u64;
    return 1;
}

static int allocate_runtime_tls_block(const struct loaded_obj *obj,
                                      void **mapping_out,
                                      size_t *mapping_len_out,
                                      uintptr_t *tls_base_out)
{
    uint64_t align;
    uint64_t tls_base_u64;
    uint64_t tls_end;
    uint64_t map_end;
    size_t map_len;
    void *mapping;

    *mapping_out = NULL;
    *mapping_len_out = 0;
    *tls_base_out = 0;
    if (!runtime_tls_mapping_size(obj, &map_len))
        return -1;

    align = obj->tls.align ? obj->tls.align : 1;
    mapping = mmap(NULL, map_len, PROT_READ | PROT_WRITE,
                   MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mapping == MAP_FAILED)
        return -1;
    if (!u64_align_residue_up_checked(
            (uintptr_t)mapping, align, obj->tls.vaddr, &tls_base_u64) ||
        !u64_add_checked(tls_base_u64, obj->tls.memsz, &tls_end) ||
        !u64_add_checked((uintptr_t)mapping, map_len, &map_end) ||
        tls_end > map_end) {
        munmap(mapping, map_len);
        return -1;
    }

    if (obj->tls.filesz != 0) {
        memcpy((void *)(uintptr_t)tls_base_u64,
               (const void *)(uintptr_t)(obj->base + obj->tls.vaddr),
               (size_t)obj->tls.filesz);
    }
    if (obj->tls.memsz > obj->tls.filesz) {
        memset((void *)(uintptr_t)(tls_base_u64 + obj->tls.filesz), 0,
               (size_t)(obj->tls.memsz - obj->tls.filesz));
    }

    *mapping_out = mapping;
    *mapping_len_out = map_len;
    *tls_base_out = (uintptr_t)tls_base_u64;
    return 0;
}

static int glibc_dtv_uses_to_free(void)
{
    /* Direct mode admits only the modern two-pointer DTV generation. */
    return g_glibc_minor >= 34 && g_glibc_minor <= 44;
}

static uintptr_t glibc_static_tls_marker(void)
{
    return 0;
}

static uintptr_t glibc_dynamic_tls_marker(void *allocation)
{
    return (uintptr_t)allocation;
}

/* thread_db proves that each admitted target uses a two-pointer DTV entry and
 * that the value member starts at word zero.  Within the separately bounded
 * glibc 2.34--2.44 contract, the other word is the unaligned allocation
 * pointer (`to_free`).  That meaning is release policy, not a public ABI;
 * future releases are refused until it is revalidated.  PT_TLS first-byte
 * residue remains a static-placement concern; dynamic blocks themselves are
 * zero-mod-p_align. */
static int allocate_glibc_runtime_tls_block(
    const struct loaded_obj *obj, void **allocation_out,
    uintptr_t *tls_base_out)
{
    uint64_t align;
    uint64_t allocation_size_u64;
    uint64_t allocation_end;
    uint64_t tls_base_u64;
    uint64_t tls_end;
    void *allocation;

    *allocation_out = NULL;
    *tls_base_out = 0;
    if (!glibc_dtv_uses_to_free() || !g_target_free || !g_target_malloc ||
        !runtime_tls_template_valid(obj))
        return -1;
    align = obj->tls.align ? obj->tls.align : 1;
    if (!u64_add_checked(obj->tls.memsz, align,
                         &allocation_size_u64) ||
        allocation_size_u64 == 0 || allocation_size_u64 > SIZE_MAX)
        return -1;
    allocation = g_target_malloc((size_t)allocation_size_u64);
    if (!allocation)
        return -1;
    if (!u64_align_up_checked((uintptr_t)allocation, align,
                              &tls_base_u64) ||
        !u64_add_checked((uintptr_t)allocation, allocation_size_u64,
                         &allocation_end) ||
        !u64_add_checked(tls_base_u64, obj->tls.memsz, &tls_end) ||
        tls_end > allocation_end) {
        g_target_free(allocation);
        return -1;
    }

    if (obj->tls.filesz != 0) {
        memcpy((void *)(uintptr_t)tls_base_u64,
               (const void *)(uintptr_t)(obj->base + obj->tls.vaddr),
               (size_t)obj->tls.filesz);
    }
    if (obj->tls.memsz > obj->tls.filesz) {
        memset((void *)(uintptr_t)(tls_base_u64 + obj->tls.filesz), 0,
               (size_t)(obj->tls.memsz - obj->tls.filesz));
    }

    *allocation_out = allocation;
    *tls_base_out = (uintptr_t)tls_base_u64;
    return 0;
}

static int runtime_tls_address(const struct loaded_obj *obj,
                               uintptr_t tls_base, unsigned long offset,
                               void **address_out)
{
    uint64_t address;

    if (!runtime_tls_template_valid(obj) ||
        (uint64_t)offset > obj->tls.memsz ||
        !u64_add_checked(tls_base, (uint64_t)offset, &address) ||
        address > UINTPTR_MAX)
        return 0;
    *address_out = (void *)(uintptr_t)address;
    return 1;
}

static int static_tls_block_address(uintptr_t tp,
                                    const struct loaded_obj *obj,
                                    uint8_t **address_out)
{
    uint64_t magnitude;
    uintptr_t address;

    if (!runtime_tls_template_valid(obj) || obj->tls.tpoff == 0)
        return 0;
    if (obj->tls.tpoff < 0) {
        magnitude = (uint64_t)(-(obj->tls.tpoff + 1)) + 1;
        if (magnitude > tp || magnitude > g_tls_static_extent ||
            obj->tls.memsz > magnitude)
            return 0;
        address = tp - (uintptr_t)magnitude;
    } else {
        uint64_t offset = (uint64_t)obj->tls.tpoff;

        if (offset > g_tls_static_extent ||
            obj->tls.memsz > g_tls_static_extent - offset ||
            offset > UINTPTR_MAX - tp)
            return 0;
        address = tp + (uintptr_t)offset;
    }
    *address_out = (uint8_t *)address;
    return 1;
}

static int discover_tls_template(struct loaded_obj *obj,
                                 const Elf64_Phdr *phdrs,
                                 int phnum)
{
    int found = 0;

    for (int i = 0; i < phnum; i++) {
        uint64_t align;

        if (phdrs[i].p_type != PT_TLS)
            continue;
        if (found)
            return -1;
        found = 1;
        align = phdrs[i].p_align ? phdrs[i].p_align : 1;
        if (phdrs[i].p_filesz > phdrs[i].p_memsz ||
            phdrs[i].p_memsz > SIZE_MAX ||
            phdrs[i].p_vaddr > UINT64_MAX - phdrs[i].p_memsz ||
            (align & (align - 1)) != 0 ||
            (phdrs[i].p_vaddr & (align - 1)) !=
                (phdrs[i].p_offset & (align - 1)) ||
            (phdrs[i].p_filesz != 0 &&
             !loaded_obj_file_vaddr_pointer(obj, phdrs[i].p_vaddr,
                                            (size_t)phdrs[i].p_filesz,
                                            NULL)))
            return -1;
        obj->tls.filesz = phdrs[i].p_filesz;
        obj->tls.memsz = phdrs[i].p_memsz;
        obj->tls.vaddr = phdrs[i].p_vaddr;
        obj->tls.align = align;
    }
    return 0;
}

static int next_tls_modid(size_t *modid_out)
{
    size_t max_modid = 0;

    for (int i = 0; i < g_nobj; i++) {
        if (g_all_objs[i].tls.modid > max_modid)
            max_modid = g_all_objs[i].tls.modid;
    }
    if (max_modid == SIZE_MAX || max_modid >= MAX_TOTAL_OBJS)
        return -1;
    *modid_out = max_modid + 1;
    return 0;
}

/* Lazily install a per-thread DTV slot for a musl-runtime module that
 * was dlopen'd after the calling thread was created.  musl's pthread
 * allocates the static TLS area + DTV at thread creation time and does
 * not know about modules loaded later, so __tls_get_addr finds an empty
 * (or missing) slot.  We grow the DTV as needed and allocate a fresh
 * TLS block initialized from the module's .tdata image.  Forward-
 * declared near stub_tls_get_addr above. */
static void *musl_lazy_install_tls(uintptr_t tp, unsigned long modid,
                                   unsigned long ti_offset)
{
    struct loaded_obj *obj = NULL;
    uintptr_t *new_dtv = NULL;
    size_t new_dtv_bytes = 0;
    void *tls_map = NULL;
    size_t tls_map_len = 0;
    uintptr_t tls_base;
    void *address;

    for (int i = 0; i < g_nobj; i++) {
        if (g_all_objs[i].tls.modid == modid &&
            g_all_objs[i].tls.memsz != 0) {
            obj = &g_all_objs[i];
            break;
        }
    }
    if (!obj)
        tls_runtime_fatal("unknown musl TLS module");
    if (!runtime_tls_template_valid(obj) || modid > MAX_TOTAL_OBJS ||
        (uint64_t)ti_offset > obj->tls.memsz)
        tls_runtime_fatal("invalid musl TLS module or offset");

    uintptr_t *dtv = *(uintptr_t **)musl_thread_dtv_slot(tp);
    size_t cur_slots = dtv ? dtv[0] : 0;
    if (cur_slots > MAX_TOTAL_OBJS)
        tls_runtime_fatal("invalid musl DTV capacity");
    if (!dtv || cur_slots < modid) {
        size_t new_slots = modid;
        uint64_t words;
        uint64_t bytes_u64;

        if (!u64_add_checked(new_slots, 1, &words) ||
            !u64_mul_checked(words, sizeof(uintptr_t), &words) ||
            !u64_align_up_checked(words, g_page_size, &bytes_u64) ||
            bytes_u64 == 0 || bytes_u64 > SIZE_MAX)
            tls_runtime_fatal("musl DTV size overflow");
        new_dtv_bytes = (size_t)bytes_u64;
        new_dtv = mmap(NULL, new_dtv_bytes, PROT_READ | PROT_WRITE,
                       MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_dtv == MAP_FAILED)
            tls_runtime_fatal("cannot grow musl DTV");
        if (dtv)
            memcpy(new_dtv, dtv, (cur_slots + 1) * sizeof(uintptr_t));
        new_dtv[0] = new_slots;
        dtv = new_dtv;
    }

    if (!dtv[modid]) {
        if (allocate_runtime_tls_block(obj, &tls_map, &tls_map_len,
                                       &tls_base) < 0) {
            if (new_dtv)
                munmap(new_dtv, new_dtv_bytes);
            tls_runtime_fatal("cannot allocate musl TLS block");
        }
        dtv[modid] = tls_base;
        if (g_debug) {
            ldr_msg("[tls] musl lazy install ");
            ldr_msg(obj->name ? obj->name : "?");
            ldr_dbg_hex(" mod=", modid);
            ldr_dbg_hex(" blk=", tls_base);
        }
    }
    if (new_dtv)
        *(uintptr_t **)musl_thread_dtv_slot(tp) = new_dtv;

    if (!runtime_tls_address(obj, dtv[modid], ti_offset, &address))
        tls_runtime_fatal("musl TLS address overflow");
    (void)tls_map;
    (void)tls_map_len;
    return address;
}

/* install_glibc_dlopen_tls — allocate a TLS block for a dlopen'd module
 * and install it in the calling thread's DTV.  glibc convention:
 *   tcb->dtv = &raw_dtv[1]   (in dtv_t units, each 2×uintptr_t)
 *   dtv[modid*2]   = pointer to TLS block
 *   dtv[modid*2+1] = is_static (<=2.24) or to_free (>=2.25)
 * Only called for glibc runtime; musl uses install_musl_dlopen_tls. */
static int glibc_dtv_map_size(size_t capacity, size_t *map_size_out)
{
    uint64_t entries;
    uint64_t words;
    uint64_t bytes;

    if (capacity > MAX_TOTAL_OBJS ||
        !u64_add_checked(capacity, 1, &entries) ||
        !u64_mul_checked(entries, 2, &words) ||
        !u64_add_checked(words, 2, &words) ||
        !u64_mul_checked(words, sizeof(uintptr_t), &bytes) ||
        !u64_align_up_checked(bytes, g_page_size, &bytes) ||
        bytes == 0 || bytes > SIZE_MAX)
        return 0;
    *map_size_out = (size_t)bytes;
    return 1;
}

/* dtv[-1].counter is the public capacity word.  The other word in that
 * reserved dtv_t entry is unused by glibc, so bind it to the mmap address
 * as an ownership cookie.  This lets growth and teardown distinguish our
 * mmap-backed vectors from a conservative/foreign DTV without guessing its
 * allocator or calling the target libc after the TP handoff. */
#define GLIBC_DTV_OWNER_XOR ((uintptr_t)UINT64_C(0xd1f2ee7ed7a11c5b))

static uintptr_t glibc_dtv_owner_cookie(const uintptr_t *raw_dtv)
{
    return (uintptr_t)raw_dtv ^ GLIBC_DTV_OWNER_XOR;
}

static void glibc_mark_dtv_owned(uintptr_t *raw_dtv)
{
    raw_dtv[1] = glibc_dtv_owner_cookie(raw_dtv);
}

static int glibc_dtv_is_owned(const uintptr_t *dtv)
{
    const uintptr_t *raw_dtv;

    if (!dtv)
        return 0;
    raw_dtv = dtv - 2;
    return raw_dtv[1] == glibc_dtv_owner_cookie(raw_dtv);
}

static uintptr_t *glibc_allocate_dtv(size_t capacity, size_t *map_size_out)
{
    uintptr_t *raw_dtv;
    size_t map_size;

    if (!glibc_dtv_map_size(capacity, &map_size))
        return NULL;
    raw_dtv = mmap(NULL, map_size, PROT_READ | PROT_WRITE,
                   MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (raw_dtv == MAP_FAILED)
        return NULL;
    raw_dtv[0] = capacity;
    glibc_mark_dtv_owned(raw_dtv);
    if (map_size_out)
        *map_size_out = map_size;
    return raw_dtv + 2;
}

static int glibc_unmap_owned_dtv(uintptr_t *dtv, size_t capacity)
{
    uintptr_t *raw_dtv;
    size_t map_size;

    if (!dtv || !glibc_dtv_is_owned(dtv) ||
        !glibc_dtv_map_size(capacity, &map_size))
        return 0;
    raw_dtv = dtv - 2;
    if (g_page_size == 0 || (uintptr_t)raw_dtv % g_page_size != 0)
        return 0;
    return munmap(raw_dtv, map_size) == 0;
}

static int glibc_dtv_capacity(uintptr_t *dtv, size_t *capacity_out)
{
    size_t capacity;

    if (!dtv) {
        *capacity_out = 0;
        return 1;
    }
    capacity = dtv[-2];
    if (capacity > MAX_TOTAL_OBJS)
        return 0;
    *capacity_out = capacity;
    return 1;
}

static int glibc_static_tls_capacity(size_t *capacity_out)
{
    size_t capacity = 0;

    for (int i = 0; i < g_nobj; i++) {
        const struct loaded_obj *obj = &g_all_objs[i];

        if (obj->tls.memsz == 0 || obj->tls.tpoff == 0)
            continue;
        if (!runtime_tls_template_valid(obj) || obj->tls.modid == 0 ||
            obj->tls.modid > MAX_TOTAL_OBJS)
            return 0;
        if (obj->tls.modid > capacity)
            capacity = obj->tls.modid;
    }
    *capacity_out = capacity;
    return 1;
}

/* Reconstruct static slots from the thread pointer instead of reading them
 * beyond an old DTV's advertised capacity.  Some supported pthread paths can
 * hand us a conservative DTV header; that header remains the only safe bound
 * for copying the old allocation. */
static int glibc_seed_static_tls_slots(uintptr_t tp, uintptr_t *dtv,
                                       size_t capacity)
{
    if (!tp || !dtv)
        return 0;
    for (int i = 0; i < g_nobj; i++) {
        const struct loaded_obj *obj = &g_all_objs[i];
        uint8_t *static_block;

        if (obj->tls.memsz == 0 || obj->tls.tpoff == 0)
            continue;
        if (obj->tls.modid == 0 || obj->tls.modid > capacity ||
            !static_tls_block_address(tp, obj, &static_block))
            return 0;
        dtv[obj->tls.modid * 2] = (uintptr_t)static_block;
        dtv[obj->tls.modid * 2 + 1] = glibc_static_tls_marker();
    }
    return 1;
}

static int glibc_tls_slot_allocated(uintptr_t value)
{
    /* glibc uses TLS_DTV_UNALLOCATED ((void *) -1l) as well as NULL for
     * an empty dynamic slot, depending on which update/teardown path ran. */
    return value != 0 && value != UINTPTR_MAX;
}

static const struct loaded_obj *runtime_tls_object_for_modid(size_t modid)
{
    const struct loaded_obj *found = NULL;

    if (modid == 0 || modid > MAX_TOTAL_OBJS)
        return NULL;
    for (int i = 0; i < g_nobj; i++) {
        const struct loaded_obj *obj = &g_all_objs[i];

        if (obj->tls.memsz == 0 || obj->tls.modid != modid)
            continue;
        if (found)
            return NULL;
        found = obj;
    }
    return found;
}

/* Validate the exact generation-specific allocation geometry before
 * releasing a DTV entry through the target libc. */
static int glibc_dynamic_tls_allocation_valid(size_t modid,
                                               uintptr_t tls_base,
                                               uintptr_t allocation)
{
    const struct loaded_obj *obj = runtime_tls_object_for_modid(modid);
    uint64_t expected_tls_base;
    uint64_t tls_end;
    uint64_t allocation_end;
    uint64_t allocation_size;
    uint64_t align;

    if (!obj || obj->tls.tpoff != 0 || !allocation ||
        !glibc_tls_slot_allocated(tls_base) ||
        !g_target_free)
        return 0;
    align = obj->tls.align ? obj->tls.align : 1;
    if (!glibc_dtv_uses_to_free())
        return 0;
    if (!u64_add_checked(obj->tls.memsz, align, &allocation_size) ||
        !u64_align_up_checked(allocation, align, &expected_tls_base) ||
        expected_tls_base != tls_base ||
        !u64_add_checked(tls_base, obj->tls.memsz, &tls_end) ||
        !u64_add_checked(allocation, allocation_size, &allocation_end) ||
        tls_end > allocation_end)
        return 0;
    return 1;
}

/* Classify one DTV entry using both the target generation and the loader's
 * canonical static/dynamic placement.  Empty entries have no allocation;
 * populated static entries must carry the static marker; populated dynamic
 * entries must carry an allocation that matches their ABI's geometry. */
static int glibc_dtv_entry_allocation(size_t modid, uintptr_t tls_base,
                                      uintptr_t marker,
                                      uintptr_t *allocation_out)
{
    const struct loaded_obj *obj;
    uintptr_t allocation;

    *allocation_out = 0;
    if (!glibc_tls_slot_allocated(tls_base))
        return marker == 0;
    obj = runtime_tls_object_for_modid(modid);
    if (!obj)
        return 0;
    if (obj->tls.tpoff != 0)
        return marker == glibc_static_tls_marker();

    if (!glibc_dtv_uses_to_free() || marker == 0)
        return 0;
    allocation = marker;
    if (!glibc_dynamic_tls_allocation_valid(
            modid, tls_base, allocation))
        return 0;
    *allocation_out = allocation;
    return 1;
}

static int glibc_release_dynamic_tls_slots(uintptr_t *dtv, size_t capacity)
{
    /* Validate the complete vector before changing it, so a corrupt or
     * foreign marker cannot cause a partial teardown followed by reuse. */
    for (size_t slot = 1; slot <= capacity; slot++) {
        uintptr_t tls_base = dtv[slot * 2];
        uintptr_t marker = dtv[slot * 2 + 1];
        uintptr_t allocation;

        if (!glibc_dtv_entry_allocation(
                slot, tls_base, marker, &allocation))
            return 0;
        if (!allocation)
            continue;
        for (size_t prior = 1; prior < slot; prior++) {
            uintptr_t prior_base = dtv[prior * 2];
            uintptr_t prior_marker = dtv[prior * 2 + 1];
            uintptr_t prior_allocation;

            if (!glibc_dtv_entry_allocation(
                    prior, prior_base, prior_marker, &prior_allocation))
                return 0;
            if (prior_allocation == allocation)
                return 0;
        }
    }

    for (size_t slot = 1; slot <= capacity; slot++) {
        uintptr_t tls_base = dtv[slot * 2];
        uintptr_t marker = dtv[slot * 2 + 1];
        uintptr_t allocation;

        if (!glibc_dtv_entry_allocation(
                slot, tls_base, marker, &allocation))
            return 0;
        if (!allocation)
            continue;
        g_target_free((void *)allocation);
        dtv[slot * 2] = UINTPTR_MAX;
        dtv[slot * 2 + 1] = 0;
    }
    return 1;
}

static int install_glibc_tls_for_thread(uintptr_t tp,
                                        struct loaded_obj *obj)
{
    uintptr_t *old_dtv;
    uintptr_t *dtv;
    uintptr_t *new_raw = NULL;
    size_t old_capacity = 0;
    size_t static_capacity = 0;
    size_t new_map_size = 0;
    void *tls_allocation = NULL;
    uintptr_t tls_base;
    uintptr_t tls_marker;
    int old_owned;
    int slot_already_allocated;

    if (!tp || !runtime_tls_template_valid(obj) || obj->tls.modid == 0 ||
        obj->tls.modid > MAX_TOTAL_OBJS)
        return -1;

    old_dtv = *(uintptr_t **)(tp + TCB_OFF_DTV);
    if (!glibc_dtv_capacity(old_dtv, &old_capacity) ||
        !glibc_static_tls_capacity(&static_capacity))
        return -1;
    old_owned = glibc_dtv_is_owned(old_dtv);
    slot_already_allocated =
        old_dtv && old_capacity >= obj->tls.modid &&
        glibc_tls_slot_allocated(old_dtv[obj->tls.modid * 2]);
    if (old_owned && slot_already_allocated)
        return 0;

    dtv = old_dtv;
    if (!old_owned || old_capacity < obj->tls.modid) {
        size_t new_capacity = old_capacity;

        if (obj->tls.modid > new_capacity)
            new_capacity = obj->tls.modid;
        if (static_capacity > new_capacity)
            new_capacity = static_capacity;

        dtv = glibc_allocate_dtv(new_capacity, &new_map_size);
        if (!dtv)
            return -1;
        new_raw = dtv - 2;
        if (old_dtv) {
            size_t old_map_size;
            uint64_t old_words;
            uint64_t old_bytes;

            if (!glibc_dtv_map_size(old_capacity, &old_map_size) ||
                !u64_add_checked(old_capacity, 1, &old_words) ||
                !u64_mul_checked(old_words, 2, &old_words) ||
                !u64_add_checked(old_words, 2, &old_words) ||
                !u64_mul_checked(old_words, sizeof(uintptr_t), &old_bytes) ||
                old_bytes > old_map_size) {
                munmap(new_raw, new_map_size);
                return -1;
            }
            /* DTV storage ownership and dynamic-entry ownership are
             * independent.  A foreign vector was still populated by this
             * same target libc, so retain its generation-specific entry
             * marker when moving the entries into our mmap-backed vector.
             * Dropping a modern to_free pointer here would permanently leak
             * the corresponding TLS allocation. */
            memcpy(new_raw, old_dtv - 2, (size_t)old_bytes);
        }
        new_raw[0] = new_capacity;
        glibc_mark_dtv_owned(new_raw);
        dtv[0] = 1;
        dtv[1] = 0;
        if (!glibc_seed_static_tls_slots(tp, dtv, new_capacity)) {
            munmap(new_raw, new_map_size);
            return -1;
        }
    }

    if (slot_already_allocated) {
        tls_base = old_dtv[obj->tls.modid * 2];
        tls_marker = dtv[obj->tls.modid * 2 + 1];
    } else if (obj->tls.tpoff != 0) {
        uint8_t *static_block;

        if (!static_tls_block_address(tp, obj, &static_block)) {
            if (new_raw)
                munmap(new_raw, new_map_size);
            return -1;
        }
        tls_base = (uintptr_t)static_block;
        tls_marker = glibc_static_tls_marker();
    } else if (allocate_glibc_runtime_tls_block(
                   obj, &tls_allocation, &tls_base) < 0) {
        if (new_raw)
            munmap(new_raw, new_map_size);
        return -1;
    } else
        tls_marker = glibc_dynamic_tls_marker(tls_allocation);

    dtv[obj->tls.modid * 2] = tls_base;
    dtv[obj->tls.modid * 2 + 1] = tls_marker;
    if (new_raw) {
        *(uintptr_t **)(tp + TCB_OFF_DTV) = dtv;
        if (old_owned && !glibc_unmap_owned_dtv(old_dtv, old_capacity))
            ldr_dbg("[loader] warning: could not release replaced DTV\n");
    }

    if (g_debug) {
        ldr_msg("[loader] glibc dlopen tls: ");
        ldr_msg(obj->name ? obj->name : "?");
        ldr_dbg_hex(" mod=0x", obj->tls.modid);
        ldr_dbg_hex(" block=0x", tls_base);
    }
    return 0;
}

static void tls_runtime_fatal(const char *reason)
{
    ldr_msg("dlfreeze-loader: fatal TLS runtime failure: ");
    ldr_msg(reason);
    ldr_msg("\n");
    _exit(127);
}

static int dl_transaction_tls_address(uintptr_t tp, unsigned long modid,
                                      unsigned long ti_offset,
                                      void **address_out);

static void *runtime_tls_get_addr_locked(uintptr_t tp, unsigned long modid,
                                         unsigned long ti_offset)
    __attribute__((noinline, cold));

static void *runtime_tls_get_addr_locked(uintptr_t tp, unsigned long modid,
                                         unsigned long ti_offset)
{
    struct loaded_obj *obj = NULL;
    void *address;
    int transaction_result = dl_transaction_tls_address(
        tp, modid, ti_offset, &address);

    if (transaction_result > 0)
        return address;
    if (transaction_result < 0)
        tls_runtime_fatal("cannot stage transaction TLS block");

    for (int i = 0; i < g_nobj; i++) {
        if (g_all_objs[i].tls.modid == modid &&
            g_all_objs[i].tls.memsz != 0) {
            obj = &g_all_objs[i];
            break;
        }
    }
    if (!obj || !runtime_tls_template_valid(obj) ||
        (uint64_t)ti_offset > obj->tls.memsz)
        tls_runtime_fatal("invalid TLS module or offset");

    if (g_is_musl_runtime)
        return musl_lazy_install_tls(tp, modid, ti_offset);

    {
        uintptr_t *dtv = *(uintptr_t **)(tp + TCB_OFF_DTV);
        uintptr_t tls_block = 0;
        size_t capacity = 0;

        if (!glibc_dtv_capacity(dtv, &capacity))
            tls_runtime_fatal("invalid glibc DTV capacity");
        if (dtv && modid <= capacity)
            tls_block = dtv[(size_t)modid * 2];
        if (!glibc_tls_slot_allocated(tls_block)) {
            if (install_glibc_tls_for_thread(tp, obj) < 0)
                tls_runtime_fatal("cannot install glibc TLS block");
            dtv = *(uintptr_t **)(tp + TCB_OFF_DTV);
            if (!glibc_dtv_capacity(dtv, &capacity))
                tls_runtime_fatal("invalid grown glibc DTV capacity");
            if (dtv && modid <= capacity)
                tls_block = dtv[(size_t)modid * 2];
        }
        if (!glibc_tls_slot_allocated(tls_block) ||
            !runtime_tls_address(obj, tls_block, ti_offset, &address))
            tls_runtime_fatal("missing glibc TLS DTV slot");
    }
    return address;
}

static inline __attribute__((always_inline)) int
runtime_tls_get_addr_fast(uintptr_t tp, unsigned long modid,
                          unsigned long ti_offset, void **result_out)
{
    struct runtime_tls_fast_entry *entry;
    uint64_t extent_plus_one;
    uintptr_t *dtv;
    uintptr_t tls_base = 0;
    uint64_t address;

    /* Fast path for an already-published module with a slot admitted by this
     * thread's DTV header.  A known startup TP offset cannot bypass that
     * header: supported libc thread paths may expose a conservative DTV which
     * the slow path must grow and seed before __tls_get_addr returns. */
    if (tp && modid != 0 && modid <= MAX_TOTAL_OBJS) {
        entry = &g_runtime_tls_fast[modid];
        extent_plus_one = runtime_atomic_load64(&entry->extent_plus_one);
        if (extent_plus_one != 0 &&
            (uint64_t)ti_offset < extent_plus_one) {
            if (g_is_musl_runtime) {
                size_t capacity;

                dtv = *(uintptr_t **)musl_thread_dtv_slot(tp);
                capacity = dtv ? dtv[0] : 0;
                if (capacity <= MAX_TOTAL_OBJS && modid <= capacity)
                    tls_base = dtv[modid];
            } else {
                size_t capacity;

                dtv = *(uintptr_t **)(tp + TCB_OFF_DTV);
                if (glibc_dtv_capacity(dtv, &capacity) && dtv &&
                    modid <= capacity) {
                    uintptr_t candidate = dtv[(size_t)modid * 2];

                    if (glibc_tls_slot_allocated(candidate))
                        tls_base = candidate;
                }
            }
            if (tls_base &&
                u64_add_checked(tls_base, (uint64_t)ti_offset, &address) &&
                address <= UINTPTR_MAX) {
                *result_out = (void *)(uintptr_t)address;
                return 1;
            }
        }
    }
    return 0;
}

static void *runtime_tls_get_addr_slow(uintptr_t tp, unsigned long modid,
                                       unsigned long ti_offset)
    __attribute__((noinline, cold));

static void *runtime_tls_get_addr_slow(uintptr_t tp, unsigned long modid,
                                       unsigned long ti_offset)
{
    void *result;
    runtime_loader_lock_token lock_token =
        runtime_loader_lock_acquire();

    result = runtime_tls_get_addr_locked(tp, modid, ti_offset);
    runtime_loader_lock_release(lock_token);
    return result;
}

static void *runtime_tls_get_addr(uintptr_t tp, unsigned long modid,
                                  unsigned long ti_offset)
{
    void *result;

    if (runtime_tls_get_addr_fast(tp, modid, ti_offset, &result))
        return result;
    return runtime_tls_get_addr_slow(tp, modid, ti_offset);
}

static void *stub_tls_get_addr(struct tls_index *ti)
{
    uintptr_t tp;
    unsigned long modid;
    unsigned long offset;
    void *result;

    if (!ti)
        return NULL;
    tp = arch_get_tp();
    modid = ti->ti_module;
    offset = ti->ti_offset;
    if (runtime_tls_get_addr_fast(tp, modid, offset, &result))
        return result;
    return runtime_tls_get_addr_slow(tp, modid, offset);
}

/* Once the target runtime has been identified, relocation replay binds
 * __tls_get_addr directly to the matching fast path.  Keeping the glibc and
 * musl paths separate removes a process-invariant branch from every GD/LD
 * TLS access without weakening the publication, extent, or DTV-capacity
 * checks.  The generic entry above remains the safe early fallback before
 * the special-symbol table is published, and TLSDESC continues through the
 * shared checked implementation. */
static void *stub_tls_get_addr_glibc(struct tls_index *ti)
{
    uintptr_t tp;
    unsigned long modid;
    unsigned long offset;
    struct runtime_tls_fast_entry *entry;
    uintptr_t *dtv;
    uintptr_t tls_base;
    size_t capacity;
    uint64_t extent_plus_one;
    uint64_t address;

    if (!ti)
        return NULL;
    tp = arch_get_tp();
    modid = ti->ti_module;
    offset = ti->ti_offset;
    if (!tp || modid == 0 || modid > MAX_TOTAL_OBJS)
        return runtime_tls_get_addr_slow(tp, modid, offset);
    entry = &g_runtime_tls_fast[modid];
    extent_plus_one = runtime_atomic_load64(&entry->extent_plus_one);
    if (extent_plus_one == 0 || (uint64_t)offset >= extent_plus_one)
        return runtime_tls_get_addr_slow(tp, modid, offset);
    dtv = *(uintptr_t **)(tp + TCB_OFF_DTV);
    if (!glibc_dtv_capacity(dtv, &capacity) || !dtv || modid > capacity)
        return runtime_tls_get_addr_slow(tp, modid, offset);
    tls_base = dtv[(size_t)modid * 2];
    if (!glibc_tls_slot_allocated(tls_base) ||
        !u64_add_checked(tls_base, (uint64_t)offset, &address) ||
        address > UINTPTR_MAX)
        return runtime_tls_get_addr_slow(tp, modid, offset);
    return (void *)(uintptr_t)address;
}

static void *stub_tls_get_addr_musl(struct tls_index *ti)
{
    uintptr_t tp;
    unsigned long modid;
    unsigned long offset;
    struct runtime_tls_fast_entry *entry;
    uintptr_t *dtv;
    uintptr_t tls_base;
    size_t capacity;
    uint64_t extent_plus_one;
    uint64_t address;

    if (!ti)
        return NULL;
    tp = arch_get_tp();
    modid = ti->ti_module;
    offset = ti->ti_offset;
    if (!tp || modid == 0 || modid > MAX_TOTAL_OBJS)
        return runtime_tls_get_addr_slow(tp, modid, offset);
    entry = &g_runtime_tls_fast[modid];
    extent_plus_one = runtime_atomic_load64(&entry->extent_plus_one);
    if (extent_plus_one == 0 || (uint64_t)offset >= extent_plus_one)
        return runtime_tls_get_addr_slow(tp, modid, offset);
    dtv = *(uintptr_t **)musl_thread_dtv_slot(tp);
    capacity = dtv ? dtv[0] : 0;
    if (!dtv || capacity > MAX_TOTAL_OBJS || modid > capacity)
        return runtime_tls_get_addr_slow(tp, modid, offset);
    tls_base = dtv[modid];
    if (!tls_base ||
        !u64_add_checked(tls_base, (uint64_t)offset, &address) ||
        address > UINTPTR_MAX)
        return runtime_tls_get_addr_slow(tp, modid, offset);
    return (void *)(uintptr_t)address;
}

#if defined(__x86_64__)
static int64_t dlfreeze_x86_64_tlsdesc_resolve_c(void *arg_in) __attribute__((used));
static int64_t dlfreeze_x86_64_tlsdesc_resolve_c(void *arg_in)
{
    struct x86_64_tlsdesc_arg *arg = (struct x86_64_tlsdesc_arg *)arg_in;
#ifdef DLFREEZE_TLSDESC_XSTATE_GATE
    if (g_x86_64_tlsdesc_xstate_gate_clobber) {
        /* The isolated ABI gate deliberately models target code selected for
         * AVX.  Production builds do not contain this branch. */
        __asm__ volatile("vpxor %%ymm0, %%ymm0, %%ymm0" ::: "ymm0");
        return (int64_t)arg->offset;
    }
#endif
    uintptr_t tp = arch_get_tp();
    uintptr_t tls_addr = (uintptr_t)runtime_tls_get_addr(
        tp, (unsigned long)arg->modid, (unsigned long)arg->offset);
    return (int64_t)(tls_addr - tp);
}
#endif

/* _dl_allocate_tls_init — copy .tdata for every TLS module into a
 * new thread's TLS block.  Called by glibc's pthread_create. */
static int g_tls_alloc_count;
static int g_tls_init_count;
static void *stub_dl_allocate_tls_init_locked(void *mem)
{
    uintptr_t tp = (uintptr_t)mem;
    uintptr_t *dtv;
    size_t dtv_capacity;

    if (!mem)
        return NULL;
    dtv = *(uintptr_t **)(tp + TCB_OFF_DTV);
    if (!glibc_dtv_capacity(dtv, &dtv_capacity) || !dtv ||
        !glibc_seed_static_tls_slots(tp, dtv, dtv_capacity))
        return NULL;
    dtv[0] = 1;
    dtv[1] = 0;
    g_tls_init_count++;
    ldr_dbg("[loader] _dl_allocate_tls_init #");
    ldr_dbg_hex("", (uint64_t)g_tls_init_count);
    ldr_dbg_hex("[loader]   tp=", tp);
    ldr_dbg_hex("[loader]   tid=",
                (uint64_t)arch_raw_syscall0(SYS_gettid));
    /* Log the target-proven x86 self slot for diagnostics. */
#if defined(__x86_64__)
    if (g_debug) {
        uintptr_t fs_self = arch_read_tp_offset(GLIBC_TCB_OFF_SELF);
        ldr_dbg_hex("[loader]   caller self=", fs_self);
        ldr_dbg_hex("[loader]   target self before=",
                    *(uintptr_t *)(tp + GLIBC_TCB_OFF_SELF));
    }
#endif
    for (int i = 0; i < g_nobj; i++) {
        struct loaded_obj *obj = &g_all_objs[i];
        uint8_t *dst;
        const uint8_t *src;

        if (obj->tls.memsz == 0)
            continue;
        if (!runtime_tls_template_valid(obj))
            return NULL;
        src = obj->tls.filesz != 0
            ? (const uint8_t *)(uintptr_t)(obj->base + obj->tls.vaddr)
            : NULL;
        /* dlopen'd modules (tpoff==0) live in separate per-thread TLS
         * blocks pointed to by the DTV.  When glibc recycles a cached
         * stack, _dl_allocate_tls_init is called without _dl_allocate_tls,
         * so the existing DTV block is reused and must be reset back to
         * the module's .tdata/.tbss image.  Otherwise __thread variables
         * defined in dlopened libraries would leak across threads. */
        if (obj->tls.tpoff == 0) {
            uintptr_t *dtv = *(uintptr_t **)(tp + TCB_OFF_DTV);
            size_t capacity = 0;
            uintptr_t blk;

            if (!glibc_dtv_capacity(dtv, &capacity))
                return NULL;
            if (!dtv || obj->tls.modid > capacity ||
                !glibc_tls_slot_allocated(dtv[obj->tls.modid * 2])) {
                if (install_glibc_tls_for_thread(tp, obj) < 0)
                    return NULL;
                dtv = *(uintptr_t **)(tp + TCB_OFF_DTV);
                if (!glibc_dtv_capacity(dtv, &capacity) || !dtv ||
                    obj->tls.modid > capacity)
                    return NULL;
            }
            blk = dtv[obj->tls.modid * 2];
            if (!glibc_tls_slot_allocated(blk))
                return NULL;
            dst = (uint8_t *)blk;
            if (obj->tls.filesz != 0)
                memcpy(dst, src, (size_t)obj->tls.filesz);
            size_t bss = (size_t)(obj->tls.memsz - obj->tls.filesz);
            if (bss > 0)
                memset(dst + obj->tls.filesz, 0, bss);
            ldr_dbg("[loader] tls_init dlopen: ");
            ldr_dbg(obj->name ? obj->name : "?");
            ldr_dbg_hex(" mod=", obj->tls.modid);
            ldr_dbg_hex(" blk=", blk);
            continue;
        }
        if (!static_tls_block_address(tp, obj, &dst))
            return NULL;
        ldr_dbg("[loader] tls_init: ");
        ldr_dbg(obj->name ? obj->name : "?");
        ldr_dbg_hex(" tpoff=", (uintptr_t)obj->tls.tpoff);
        if (obj->tls.filesz != 0)
            memcpy(dst, src, (size_t)obj->tls.filesz);
        /* Zero the .tbss portion */
        size_t bss = (size_t)(obj->tls.memsz - obj->tls.filesz);
        if (bss > 0)
            memset(dst + obj->tls.filesz, 0, bss);
    }

    /* Variant-II x86 stores two architecturally visible self pointers in
     * its TCB head.  AArch64's second TCB word is private padding; leave it
     * zero instead of inventing a self-pointer convention. */
#if defined(__x86_64__)
    *(uintptr_t *)(tp + GLIBC_TCB_OFF_TCB) = tp;
    *(uintptr_t *)(tp + GLIBC_TCB_OFF_SELF) = tp;
    *(uint32_t *)(tp + GLIBC_TCB_OFF_FEATURE_1) =
        g_x86_cet_actual_feature_1;
#endif

#if defined(__aarch64__)
    glibc_aarch64_mark_rseq_unavailable(tp);
#elif defined(__x86_64__)
    if (g_rseq_size == 0 && g_glibc_minor >= 35)
        *(int32_t *)((intptr_t)tp + g_rseq_offset + 4) =
            GLIBC_RSEQ_CPU_ID_REGISTRATION_FAILED;
#endif

    return mem;
}

static void *stub_dl_allocate_tls_init(void *mem, bool main_thread)
{
    void *result;
    runtime_loader_lock_token lock_token;

    /* glibc added this argument in 2.34.  Older callers leave the second
     * argument register unspecified, so the cross-version shim must not
     * inspect it. */
    (void)main_thread;
    lock_token = runtime_loader_lock_acquire();
    result = stub_dl_allocate_tls_init_locked(mem);
    runtime_loader_lock_release(lock_token);
    return result;
}

/* _dl_allocate_tls — allocate DTV and copy .tdata for a new thread. */
static void *stub_dl_allocate_tls_locked(void *mem)
{
    uintptr_t *raw_dtv;
    uintptr_t *dtv;
    void *tls_allocations[MAX_TOTAL_OBJS];
    size_t tls_allocation_count = 0;
    size_t capacity = 0;
    size_t raw_dtv_map_size;

    g_tls_alloc_count++;
    ldr_dbg("[loader] _dl_allocate_tls #");
    ldr_dbg_hex("", (uint64_t)g_tls_alloc_count);
    ldr_dbg_hex("[loader]   tid=",
                (uint64_t)arch_raw_syscall0(SYS_gettid));
    if (!mem)
        return NULL;
    uintptr_t tp = (uintptr_t)mem;

    for (int i = 0; i < g_nobj; i++) {
        if (g_all_objs[i].tls.memsz == 0)
            continue;
        if (!runtime_tls_template_valid(&g_all_objs[i]) ||
            g_all_objs[i].tls.modid == 0 ||
            g_all_objs[i].tls.modid > MAX_TOTAL_OBJS)
            return NULL;
        if (g_all_objs[i].tls.modid > capacity)
            capacity = g_all_objs[i].tls.modid;
    }
    dtv = glibc_allocate_dtv(capacity, &raw_dtv_map_size);
    if (!dtv)
        return NULL;
    raw_dtv = dtv - 2;
    dtv[0] = 1;
    dtv[1] = 0;
    for (int i = 0; i < g_nobj; i++) {
        struct loaded_obj *obj = &g_all_objs[i];
        size_t slot;

        if (obj->tls.memsz == 0)
            continue;
        slot = obj->tls.modid;
        if (obj->tls.tpoff != 0) {
            uint8_t *static_block;

            if (!static_tls_block_address(tp, obj, &static_block))
                goto fail_dtv;
            dtv[slot * 2] = (uintptr_t)static_block;
            dtv[slot * 2 + 1] = glibc_static_tls_marker();
        } else {
            void *tls_allocation;
            uintptr_t tls_base;

            if (allocate_glibc_runtime_tls_block(
                    obj, &tls_allocation, &tls_base) < 0)
                goto fail_dtv;
            dtv[slot * 2] = tls_base;
            dtv[slot * 2 + 1] =
                glibc_dynamic_tls_marker(tls_allocation);
            tls_allocations[tls_allocation_count++] = tls_allocation;
        }
    }
    *(uintptr_t *)(tp + TCB_OFF_DTV) = (uintptr_t)dtv;

    /* Initialize the two x86 TCB pointers proved by the architecture ABI and
     * target pthread_self witness before the new thread starts. */
#if defined(__x86_64__)
    *(uintptr_t *)(tp + GLIBC_TCB_OFF_TCB) = tp;
    *(uintptr_t *)(tp + GLIBC_TCB_OFF_SELF) = tp;
#endif

    /* New x86 glibc threads inherit the witnessed process guards. */
#if defined(__x86_64__)
    if (g_saved_stack_guard)
        *(uintptr_t *)(tp + GLIBC_TCB_OFF_STACK_GUARD) = g_saved_stack_guard;
    if (g_glibc_x86_pointer_guard_in_tcb && g_saved_ptr_guard)
        *(uintptr_t *)(tp + GLIBC_TCB_OFF_PTR_GUARD) = g_saved_ptr_guard;
#endif

    /* Copy .tdata for all TLS modules */
    void *ret = stub_dl_allocate_tls_init(mem, false);

    if (!ret) {
        *(uintptr_t *)(tp + TCB_OFF_DTV) = 0;
        goto fail_dtv;
    }

    /* Verify the witnessed x86 TCB writes survived. */
#if defined(__x86_64__)
    if (g_debug) {
        ldr_dbg_hex("[loader] alloc_tls done tcb=",
                    *(uintptr_t *)(tp + GLIBC_TCB_OFF_TCB));
        ldr_dbg_hex("[loader] alloc_tls done dtv=",
                    *(uintptr_t *)(tp + TCB_OFF_DTV));
        ldr_dbg_hex("[loader] alloc_tls done self=",
                    *(uintptr_t *)(tp + GLIBC_TCB_OFF_SELF));
    }
#endif
    return ret;

fail_dtv:
    for (size_t i = 0; i < tls_allocation_count; i++)
        g_target_free(tls_allocations[i]);
    munmap(raw_dtv, raw_dtv_map_size);
    return NULL;
}

static void *stub_dl_allocate_tls(void *mem)
{
    void *result;
    runtime_loader_lock_token lock_token =
        runtime_loader_lock_acquire();

    result = stub_dl_allocate_tls_locked(mem);
    runtime_loader_lock_release(lock_token);
    return result;
}

/* glibc passes false when the TCB is part of a pthread stack mapping and
 * true only for storage returned by _dl_allocate_tls(NULL).  This loader
 * deliberately rejects the latter allocation form, so it owns the DTV but
 * never the caller's TCB allocation.  Dynamic entries use the target
 * generation's malloc/memalign contract and the matching target free. */
static void stub_dl_deallocate_tls_locked(void *mem, bool dealloc_tcb)
{
    uintptr_t tp = (uintptr_t)mem;
    uintptr_t **dtv_slot;
    uintptr_t *dtv;
    size_t capacity;

    (void)dealloc_tcb;
    if (!mem)
        return;
    dtv_slot = (uintptr_t **)(tp + TCB_OFF_DTV);
    dtv = *dtv_slot;
    if (!dtv || !glibc_dtv_is_owned(dtv) ||
        !glibc_dtv_capacity(dtv, &capacity))
        return;
    if (!glibc_release_dynamic_tls_slots(dtv, capacity)) {
        ldr_dbg("[loader] warning: refusing invalid TLS DTV teardown\n");
        return;
    }
    /* Do not leave a target-visible dangling DTV pointer across munmap. */
    *dtv_slot = NULL;
    if (!glibc_unmap_owned_dtv(dtv, capacity)) {
        *dtv_slot = dtv;
        ldr_dbg("[loader] warning: could not release TLS DTV\n");
    }
}

static void stub_dl_deallocate_tls(void *mem, bool dealloc_tcb)
{
    runtime_loader_lock_token lock_token =
        runtime_loader_lock_acquire();

    stub_dl_deallocate_tls_locked(mem, dealloc_tcb);
    runtime_loader_lock_release(lock_token);
}

/* ---- _dl_find_object implementation ---------------------------------- */

static void write_dl_find_object_result(const struct loaded_obj *obj,
                                        uintptr_t map_start,
                                        uintptr_t map_end,
                                        void *result)
{
    /* LP64 struct dl_find_object layout (glibc 2.35+):
     *   0: dlfo_flags           (unsigned long long)
     *   8: dlfo_map_start       (void *)
     *  16: dlfo_map_end         (void *)
     *  24: dlfo_link_map        (struct link_map *)
     *  32: dlfo_eh_frame        (void *) — .eh_frame_hdr
     *  40: legacy reserved[0], or dlfo_sframe in newer glibc
     *  48: remaining reserved ABI space
     * The public structure remains 96 bytes in both forms. */
    uint8_t *r = (uint8_t *)result;

    memset(r, 0, 96);
    *(unsigned long long *)(r + 0) = obj->sframe ? 1ULL : 0;
    *(void **)(r + 8) = (void *)map_start;
    *(void **)(r + 16) = (void *)map_end;
    *(void **)(r + 24) =
        (void *)(uintptr_t)&obj->public_link_map;
    *(void **)(r + 32) = (void *)obj->eh_frame_hdr;
    *(void **)(r + 40) = (void *)obj->sframe;
}

/* _dl_find_object — used by libgcc_s DWARF unwinder to find FDE info.
 * Search both the target graph and the introspection-only bootstrap object
 * containing the loader frames through which target callbacks can unwind. */
static int glro_dl_find_object(void *pc, void *result)
{
    uintptr_t addr = (uintptr_t)pc;
    runtime_loader_lock_token lock_token;

    if (!result)
        return -1;
    lock_token = runtime_loader_lock_acquire();
    dl_refresh_public_link_maps();
    for (int i = 0; i < g_nobj; i++) {
        uintptr_t map_start;
        uintptr_t map_end;

        if (dl_callback_object_admitted(i) &&
            loaded_obj_find_object_range(&g_all_objs[i], addr, 1,
                                         &map_start, &map_end)) {
            write_dl_find_object_result(
                &g_all_objs[i], map_start, map_end, result);
            runtime_loader_lock_release(lock_token);
            return 0;
        }
    }
    {
        uintptr_t map_start;
        uintptr_t map_end;

        if (g_bootstrap_introspection_obj.visible &&
            loaded_obj_find_object_range(
                &g_bootstrap_introspection_obj, addr, 1,
                &map_start, &map_end)) {
            write_dl_find_object_result(
                &g_bootstrap_introspection_obj,
                map_start, map_end, result);
            runtime_loader_lock_release(lock_token);
            return 0;
        }
    }
    runtime_loader_lock_release(lock_token);
    return -1;
}

/* argc/argv/envp saved for init functions of dlopen'd objects */
static int g_argc;
static char **g_argv;
static char **g_envp;
static const char *g_initial_library_path;
static void *g_initial_library_path_mapping;
static size_t g_initial_library_path_mapping_size;
static const char *g_initial_tmpdir;
static void *g_initial_tmpdir_mapping;
static size_t g_initial_tmpdir_mapping_size;

/* Frozen image context — saved by loader_run for lazy dlopen loading */
static const uint8_t *g_frozen_mem;
static uint64_t g_frozen_mem_foff;
static int g_frozen_srcfd;
static uint32_t g_frozen_source_flags;
static const struct dlfrz_lib_meta *g_frozen_metas;
static const struct dlfrz_entry *g_frozen_entries;
static const char *g_frozen_strtab;
static uint32_t g_frozen_num_entries;
/* The retained frozen-image mapping is loader-read-only for its lifetime.
 * Validate its interpreter dynamic ABI once before target TLS is installed,
 * then share that bounded view with every private-loader symbol proof.
 * Rebuilding the view for each relocation used to rescan every dynamic
 * symbol and hash bucket hundreds of times in larger programs. */
static struct dlfrz_elf64_dyn_view g_frozen_interp_dyn_view;
static int g_frozen_interp_dyn_view_ready;
static int g_frozen_interp_index = -1;

static int initialize_frozen_interp_dyn_view(void)
{
    int interp_index = -1;

    g_frozen_interp_dyn_view_ready = 0;
    g_frozen_interp_index = -1;
    memset(&g_frozen_interp_dyn_view, 0,
           sizeof(g_frozen_interp_dyn_view));
    if (!g_frozen_mem || !g_frozen_entries || !g_frozen_metas)
        return 0;
    for (uint32_t i = 0; i < g_frozen_num_entries; i++) {
        if (!(g_frozen_metas[i].flags & LDR_FLAG_INTERP))
            continue;
        if (interp_index >= 0)
            return 0;
        interp_index = (int)i;
    }
    if (interp_index < 0 ||
        g_frozen_entries[interp_index].data_offset < g_frozen_mem_foff ||
        g_frozen_entries[interp_index].data_size > SIZE_MAX)
        return 0;
    if (!dlfrz_elf64_dyn_view_init(
            g_frozen_mem +
                (g_frozen_entries[interp_index].data_offset -
                 g_frozen_mem_foff),
            (size_t)g_frozen_entries[interp_index].data_size,
            &g_frozen_interp_dyn_view))
        return 0;
    g_frozen_interp_index = interp_index;
    g_frozen_interp_dyn_view_ready = 1;
    return 1;
}

static enum runtime_loader_phase runtime_loader_phase(void)
{
    uint32_t phase = runtime_atomic_load32(&g_runtime_loader_phase);

    if (phase > RUNTIME_LOADER_PHASE_RUNNING)
        loader_exit(127);
    return (enum runtime_loader_phase)phase;
}

/* All startup graph fields consumed by dlfcn are complete before this call.
 * The release store is the sole publication point visible to resolver-time
 * callbacks (including callbacks reached on another thread). */
static void runtime_loader_publish_startup_graph(
    int nobj, int argc, char **argv, char **envp)
{
    int boundary = 0;

    if (nobj <= 0 || nobj > MAX_TOTAL_OBJS ||
        runtime_loader_phase() != RUNTIME_LOADER_PHASE_RESET ||
        g_nobj != 0)
        loader_exit(127);
    while (boundary < nobj && g_all_objs[boundary].visible)
        boundary++;
    for (int i = boundary; i < nobj; i++)
        if (g_all_objs[i].visible)
            loader_exit(127);

    g_bootstrap_publication_boundary = boundary;
    g_nobj = nobj;
    g_argc = argc;
    g_argv = argv;
    g_envp = envp;
    runtime_loader_lock_initialize();
    dl_refresh_public_link_maps();
    runtime_atomic_store32(&g_runtime_loader_phase,
                           RUNTIME_LOADER_PHASE_STARTUP_READONLY);
}

static void runtime_loader_enable_mutation(void)
{
    runtime_loader_lock_token lock_token =
        runtime_loader_lock_acquire();

    if (runtime_loader_phase() !=
            RUNTIME_LOADER_PHASE_STARTUP_READONLY ||
        g_nobj <= 0 || g_nobj > MAX_TOTAL_OBJS)
        loader_exit(127);
    runtime_atomic_store32(&g_runtime_loader_phase,
                           RUNTIME_LOADER_PHASE_RUNNING);
    runtime_loader_lock_release(lock_token);
}

/* The bootstrap transfers ownership of an optional frozen-image source fd
 * to loader_run.  Keep it through every startup mapping consumer, including
 * the target tunable service and TLS setup, then remove it before any target
 * resolver or constructor can observe loader-private descriptors. */
static void release_frozen_source_fd_after_tls(void)
{
    int fd = g_frozen_srcfd;

    g_frozen_srcfd = -1;
    /* The contained syscall proof covers only the inherited startup policy.
     * A program may install a stricter filter before a later dlopen, so never
     * issue this optional syscall after target TLS/application handoff. */
    g_frozen_source_flags &= ~DLFRZ_SOURCE_MREMAP_DONTUNMAP;
    g_startup_mremap_disabled = 1;
    if (fd >= 0)
        (void)arch_raw_close(fd);
}

static const char *dl_manifest_logical_name(
    const struct dlfrz_entry *entries, const char *strtab, uint32_t index)
{
    uint32_t offset = entries[index].logical_name_offset;

    return strtab + (offset ? offset : entries[index].name_offset);
}

static int dl_manifest_shlib_source_alias(
    const struct dlfrz_entry *entries, uint32_t left, uint32_t right)
{
    return entries &&
           (entries[left].flags & DLFRZ_FLAG_SHLIB) &&
           (entries[right].flags & DLFRZ_FLAG_SHLIB) &&
           entries[left].data_size != 0 &&
           entries[left].data_offset == entries[right].data_offset &&
           entries[left].data_size == entries[right].data_size;
}

struct dl_manifest_startup_owners {
    void *mapping;
    size_t mapping_size;
    uint8_t *is_owner;
    size_t owner_count;
};

static int dl_manifest_startup_priority(uint32_t flags)
{
    return (flags & LDR_FLAG_MAIN_EXE) ? 0 :
           (flags & LDR_FLAG_DLOPEN) ? 2 : 1;
}

static int dl_manifest_source_index_less(
    const struct dlfrz_entry *entries, uint32_t left, uint32_t right)
{
    if (entries[left].data_offset != entries[right].data_offset)
        return entries[left].data_offset < entries[right].data_offset;
    if (entries[left].data_size != entries[right].data_size)
        return entries[left].data_size < entries[right].data_size;
    return left < right;
}

static void dl_manifest_source_heap_sift(
    const struct dlfrz_entry *entries, uint32_t *indices,
    size_t root, size_t count)
{
    for (;;) {
        size_t child;
        size_t greater;
        uint32_t temporary;

        if (root > (SIZE_MAX - 1) / 2)
            return;
        child = root * 2 + 1;
        if (child >= count)
            return;
        greater = child;
        if (child + 1 < count &&
            dl_manifest_source_index_less(
                entries, indices[child], indices[child + 1]))
            greater = child + 1;
        if (!dl_manifest_source_index_less(
                entries, indices[root], indices[greater]))
            return;
        temporary = indices[root];
        indices[root] = indices[greater];
        indices[greater] = temporary;
        root = greater;
    }
}

static void dl_manifest_source_indices_sort(
    const struct dlfrz_entry *entries, uint32_t *indices, size_t count)
{
    for (size_t start = count / 2; start > 0; start--)
        dl_manifest_source_heap_sift(entries, indices, start - 1, count);
    for (size_t end = count; end > 1; end--) {
        uint32_t temporary = indices[0];

        indices[0] = indices[end - 1];
        indices[end - 1] = temporary;
        dl_manifest_source_heap_sift(entries, indices, 0, end - 1);
    }
}

static void dl_manifest_startup_owners_release(
    struct dl_manifest_startup_owners *owners)
{
    if (owners->mapping && owners->mapping_size)
        (void)munmap(owners->mapping, owners->mapping_size);
    memset(owners, 0, sizeof(*owners));
}

/* Startup population orders the main object, ordinary startup DSOs, then
 * promoted dormant trace closures.  Resolve all exact SHLIB source aliases
 * once with that ordering.  The sorted source-index worklist avoids the old
 * full-manifest scan for every candidate while retaining deterministic
 * O(N log N) behavior for hostile source ranges. */
static int dl_manifest_startup_owners_build(
    const struct dlfrz_entry *entries,
    const struct dlfrz_lib_meta *metas, uint32_t count,
    struct dl_manifest_startup_owners *owners)
{
    size_t source_count = 0;
    size_t indices_offset;
    size_t indices_bytes;
    size_t mapping_size;
    uint32_t *source_indices;

    memset(owners, 0, sizeof(*owners));
    if (!entries || !metas || count == 0)
        return -1;
    for (uint32_t i = 0; i < count; i++) {
        if (dl_flags_startup_mapped(metas[i].flags) &&
            (entries[i].flags & DLFRZ_FLAG_SHLIB) &&
            entries[i].data_size != 0)
            source_count++;
    }
    if (!property_align_up((size_t)count, _Alignof(uint32_t),
                           &indices_offset) ||
        source_count > SIZE_MAX / sizeof(uint32_t))
        return -1;
    indices_bytes = source_count * sizeof(uint32_t);
    if (indices_offset > SIZE_MAX - indices_bytes)
        return -1;
    mapping_size = indices_offset + indices_bytes;
    owners->mapping = mmap(NULL, mapping_size, PROT_READ | PROT_WRITE,
                           MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (owners->mapping == MAP_FAILED) {
        owners->mapping = NULL;
        return -1;
    }
    owners->mapping_size = mapping_size;
    owners->is_owner = (uint8_t *)owners->mapping;
    memset(owners->mapping, 0, mapping_size);
    source_indices = (uint32_t *)((uint8_t *)owners->mapping +
                                  indices_offset);

    source_count = 0;
    for (uint32_t i = 0; i < count; i++) {
        if (!dl_flags_startup_mapped(metas[i].flags))
            continue;
        owners->is_owner[i] = 1;
        owners->owner_count++;
        if ((entries[i].flags & DLFRZ_FLAG_SHLIB) &&
            entries[i].data_size != 0)
            source_indices[source_count++] = i;
    }
    dl_manifest_source_indices_sort(entries, source_indices, source_count);
    for (size_t begin = 0; begin < source_count;) {
        size_t end = begin + 1;
        uint32_t winner = source_indices[begin];
        int winner_priority =
            dl_manifest_startup_priority(metas[winner].flags);

        while (end < source_count &&
               entries[source_indices[end]].data_offset ==
                   entries[winner].data_offset &&
               entries[source_indices[end]].data_size ==
                   entries[winner].data_size) {
            uint32_t candidate = source_indices[end];
            int candidate_priority =
                dl_manifest_startup_priority(metas[candidate].flags);

            if (candidate_priority < winner_priority ||
                (candidate_priority == winner_priority &&
                 candidate < winner)) {
                winner = candidate;
                winner_priority = candidate_priority;
            }
            end++;
        }
        for (size_t i = begin; i < end; i++) {
            uint32_t candidate = source_indices[i];

            if (candidate == winner)
                continue;
            owners->is_owner[candidate] = 0;
            owners->owner_count--;
        }
        begin = end;
    }
    return 0;
}

/* dlerror is per-thread by contract.  A compiler TLS variable here would
 * address the bootstrap libc's TLS module after target-TP handoff, so use
 * the target runtime's public pthread-key ABI and loader-owned mmap storage. */
struct dl_error_state {
    int valid;
    char message[512];
};

static pthread_key_t g_dlerror_key;
static int g_dlerror_key_ready;
/* glibc stores this opaque identity and uses it only for explicit unregister.
 * The frozen loader is process-lifetime state, so its unique address cannot
 * be confused with an application's independently registered DSO handle. */
static unsigned char g_runtime_atfork_token;
static int (*g_target_pthread_key_create)(pthread_key_t *,
                                          void (*)(void *));
static void *(*g_target_pthread_getspecific)(pthread_key_t);
static int (*g_target_pthread_setspecific)(pthread_key_t, const void *);
static int (*g_target_pthread_atfork)(void (*)(void), void (*)(void),
                                      void (*)(void));
static int (*g_target_register_atfork)(void (*)(void), void (*)(void),
                                       void (*)(void), void *);
static struct dl_error_state g_dlerror_fallback;

struct dl_rpath_scope {
    const char *path;
    const struct loaded_obj *owner;
    const struct dl_rpath_scope *parent;
};

/* Late dependency discovery is a depth-first operation because first-open
 * identity and needed_by ancestry depend on native DT_NEEDED order.  Keep
 * the DFS state in the process-lifetime transaction object instead of on a
 * caller's (possibly very small) pthread stack. */
struct dl_dependency_work {
    const struct dl_rpath_scope *inherited_rpath;
    const struct dl_rpath_scope *child_inherited;
    const char *pending_needed;
    size_t dynamic_cursor;
    uint16_t object_index;
    uint16_t pending_dependency_index;
    uint8_t initialized;
    uint8_t waiting_for_child;
    uint8_t pending_record_bare_name;
    uint8_t pending_first_loaded_as_dependency;
};

#define DL_TRANSACTION_SCOPE_MAX (MAX_TOTAL_OBJS * 2U)

enum dl_tls_publication_kind {
    DL_TLS_PUBLICATION_NONE,
    DL_TLS_PUBLICATION_MUSL,
    DL_TLS_PUBLICATION_GLIBC,
};

/* Late TLS admission has a fallible prepare half and a non-failing publish
 * half.  Keeping the unpublished replacement DTV in the transaction makes
 * every allocation failure rollback-safe without exposing a half-committed
 * thread vector to target code. */
struct dl_tls_publication_plan {
    enum dl_tls_publication_kind kind;
    uintptr_t **dtv_slot;
    uintptr_t *new_dtv;
    void *new_mapping;
    size_t new_mapping_size;
    uintptr_t *old_dtv;
    size_t old_capacity;
    int old_owned;
};

/* A recursive dlopen is one transaction.  Constructors and dynamic TLS
 * publication are deferred until every DT_NEEDED edge and relocation has
 * succeeded, so a late missing dependency cannot run an earlier object's
 * constructor. */
struct dl_load_transaction {
    int active;
    int irreversible_effects_possible;
    int publish_global;
    int lazy_binding;
#if defined(__x86_64__)
    int x86_cet_disable_requested;
#endif
    int start_nobj;
    int high_water;
    int scope_root;
    int scope_root_valid;
    int scope_root_existing;
    size_t start_init_order_count;
    uint16_t start_global_scope_count;
    size_t start_gnu_unique_count;
    size_t start_gnu_loaded_name_count;
    struct dl_rpath_scope rpath_scopes[DL_TRANSACTION_SCOPE_MAX];
    size_t rpath_scope_count;
    uint8_t scope_members[MAX_TOTAL_OBJS];
    struct dl_dependency_work dependency_work[MAX_TOTAL_OBJS];
    size_t dependency_work_depth;
    struct loaded_obj *pending_init[MAX_TOTAL_OBJS];
    size_t pending_init_count;
    uintptr_t tls_bases[MAX_TOTAL_OBJS + 1];
    void *tls_maps_by_modid[MAX_TOTAL_OBJS + 1];
    void *tls_maps[MAX_TOTAL_OBJS];
    size_t tls_map_lengths[MAX_TOTAL_OBJS];
    size_t tls_map_count;
    struct dl_tls_publication_plan tls_publication;
#if defined(__aarch64__)
    struct aarch64_tlsdesc_page *start_tlsdesc_page;
    size_t start_tlsdesc_used;
#elif defined(__x86_64__)
    struct x86_64_tlsdesc_page *start_tlsdesc_page;
    size_t start_tlsdesc_used;
#endif
};

static struct dl_load_transaction g_dl_transaction;

/* ==== Embedded data-file VFS ========================================== */
/*
 * When -f patterns are used, non-ELF data files are packed into the frozen
 * binary with DLFRZ_FLAG_DATA.  At runtime we intercept openat() so that
 * any access to a path that matches an embedded file returns a memfd
 * containing the embedded data instead of going to the real filesystem.
 */

struct vfs_entry {
    const char     *path;      /* absolute path string (in strtab) */
    size_t          path_length;
    uint64_t        path_hash;
    const uint8_t  *data;      /* pointer into mmap'd frozen binary */
    uint64_t        size;
    int64_t         mtime_sec;
    int64_t         ctime_sec;
    uint32_t        mtime_nsec;
    uint32_t        ctime_nsec;
    uint32_t        flags;
    ino_t           inode;
};

enum vfs_regular_node_kind {
    VFS_REGULAR_NODE_DATA = 1,
    VFS_REGULAR_NODE_ELF,
};

struct vfs_regular_fd_map {
    int    fd;
    dev_t  placeholder_dev;
    ino_t  placeholder_ino;
    dev_t  placeholder_rdev;
    mode_t placeholder_type;
    struct timespec placeholder_ctime;
    enum vfs_regular_node_kind kind;
    const struct vfs_entry *entry;
    uint32_t manifest_index;
    uint64_t size;
    ino_t inode;
    mode_t mode;
};

/* Immutable lookup index for the ordinary ELF entries in the manifest.
 * Runtime VFS probes commonly miss the captured DATA table before asking
 * whether the same path names an embedded ELF.  Keep that second lookup
 * keyed and bounded too: scanning the full manifest for every host-path miss
 * otherwise multiplies application filesystem traffic by manifest size. */
struct frozen_elf_path_entry {
    const char *path;
    size_t path_length;
    uint64_t path_hash;
    uint32_t manifest_index;
};

static struct vfs_entry *g_vfs_table;
static size_t g_vfs_table_size;
static size_t g_vfs_count;
/* Overrides are also needed for an absolute traced DSO path even when the
 * trace captured no ordinary DATA entries: directory scanners and explicit
 * open/stat calls must still see the immutable ELF bytes in the manifest. */
static int g_vfs_overrides_active;
static struct vfs_regular_fd_map *g_vfs_regular_fd_maps;
static size_t g_vfs_regular_fd_map_count;
static size_t g_vfs_regular_fd_map_capacity;
static struct frozen_elf_path_entry *g_frozen_elf_path_table;
static size_t g_frozen_elf_path_table_size;
static size_t g_frozen_elf_path_count;
static ino_t *g_frozen_elf_inodes;
static uint64_t g_vfs_next_inode;
#ifdef DLFREEZE_VFS_COMPLEXITY_GATE
static size_t g_frozen_elf_lookup_probes;
#endif
static uint64_t g_vfs_hash_key[2];
static int g_vfs_hash_key_ready;
static volatile uint64_t g_vfs_temp_nonce;
#ifdef DLFREEZE_FILEBACK_GATE
enum vfs_temp_gate_stage {
    VFS_TEMP_GATE_PRIVATE_NAME,
    VFS_TEMP_GATE_UNLINKED_PRIVATE,
    VFS_TEMP_GATE_UNLINKED_FINAL,
};
static void (*g_vfs_temp_stage_hook)(
    int, const char *, int, int, enum vfs_temp_gate_stage);
static int g_vfs_temp_forced_unlink_errno;
#endif
static uint64_t g_symbol_name_fingerprint_seed;
static uint64_t g_symbol_name_fingerprint_multiplier;
static int g_symbol_name_fingerprint_key_ready;

static int vfs_is_negative_entry(const struct vfs_entry *ve)
{
    return ve && (ve->flags & DLFRZ_FLAG_DATA_NEGATIVE) != 0;
}

static int vfs_is_directory_entry(const struct vfs_entry *ve)
{
    return ve && (ve->flags & DLFRZ_FLAG_DATA_DIRECTORY) != 0;
}

static int vfs_is_regular_entry(const struct vfs_entry *ve)
{
    return ve &&
        (ve->flags & (DLFRZ_FLAG_DATA_VIRTUAL |
                      DLFRZ_FLAG_DATA_NEGATIVE |
                      DLFRZ_FLAG_DATA_DIRECTORY)) == 0;
}

/* Raw Linux syscalls return -errno.  VFS entry points expose libc-compatible
 * -1 results and publish failures only into the target runtime's errno slot. */
#define VFS_SYSCALL_0(number) \
    loader_syscall_result(arch_raw_syscall0(number))
#define VFS_SYSCALL_1(number, arg0) \
    loader_syscall_result(arch_raw_syscall1(number, (long)(arg0)))
#define VFS_SYSCALL_2(number, arg0, arg1) \
    loader_syscall_result(arch_raw_syscall2( \
        number, (long)(arg0), (long)(arg1)))
#define VFS_SYSCALL_3(number, arg0, arg1, arg2) \
    loader_syscall_result(arch_raw_syscall3( \
        number, (long)(arg0), (long)(arg1), (long)(arg2)))
#define VFS_SYSCALL_4(number, arg0, arg1, arg2, arg3) \
    loader_syscall_result(arch_raw_syscall4( \
        number, (long)(arg0), (long)(arg1), (long)(arg2), (long)(arg3)))
#define VFS_SYSCALL_5(number, arg0, arg1, arg2, arg3, arg4) \
    loader_syscall_result(arch_raw_syscall5( \
        number, (long)(arg0), (long)(arg1), (long)(arg2), (long)(arg3), \
        (long)(arg4)))
#define VFS_SYSCALL_6(number, arg0, arg1, arg2, arg3, arg4, arg5) \
    loader_syscall_result(arch_raw_syscall6( \
        number, (long)(arg0), (long)(arg1), (long)(arg2), (long)(arg3), \
        (long)(arg4), (long)(arg5)))
#define VFS_SYSCALL_SELECT(_number, _arg0, _arg1, _arg2, _arg3, _arg4, \
                           _arg5, selected, ...) selected
#define VFS_SYSCALL(...) \
    VFS_SYSCALL_SELECT(__VA_ARGS__, VFS_SYSCALL_6, VFS_SYSCALL_5, \
                       VFS_SYSCALL_4, VFS_SYSCALL_3, VFS_SYSCALL_2, \
                       VFS_SYSCALL_1, VFS_SYSCALL_0)(__VA_ARGS__)

